-- Migration: Add 2019 summer questions Q20-Q28 (Sharon's v6 batch)
--
-- 9 questions, additive. Q1-Q17 untouched. Q18-Q19 not yet produced
-- by Sharon and are intentionally left as gaps.
--
-- Q20-Q25 were generated in a v5-style format (missing source_metadata,
-- subtopic phrases outside the closed list). The 4 mechanical v5
-- fixes from commit 4d5a563 are applied here too, and subtopics are
-- mapped per the PM-approved override table. All 6 questions carry
-- notes_for_admin starting with `needs_review=true` and a
-- `subtopic_mapping_review` note showing the original phrase.
--
-- Q26-Q28 are v6-clean output and use Sharon's subtopic directly.
--
-- Idempotency: each DO $$ block checks for the external_id and
-- early-returns (RAISE NOTICE) if it already exists. Safe to re-run.

-- ============================================================
-- Q20 — 2019-S-Q20 — chapter=criminal_proc subtopic=search_seizure
-- notes: needs_review=true | subtopic_mapping_review: original='מעצר בפיקוח אלקטרוני והפסקתו' → mapped='search_seizure'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q20';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q20 skipped: external_id % already exists', '2019-S-Q20';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'search_seizure';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'search_seizure';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q20', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'הממונה על עבודות השירות הורה על הפסקת המעצר בפיקוח אלקטרוני של עמי, בן 17, ותמי, בת 19, והחזרתם למעצר בבית מעצר. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 20}'::jsonb,
    'השאלה עוסקת במועדים להבאת עצור בפני בית המשפט לאחר שהופסק מעצרו בפיקוח אלקטרוני, תוך הבחנה קריטית בין קטין לבגיר. הוראות אלו, הקבועות בסעיף 22י(ג) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), משקפות את האיזון בין הצורך בפיקוח שיפוטי לבין זכותו של העצור לחירות, תוך התחשבות במעמדו המיוחד של קטין.',
    'סעיף 22י(ג) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע את המועדים להבאת מפוקח בפני בית המשפט לאחר שהממונה על הפיקוח האלקטרוני הורה על הפסקת הפיקוח. סעיף 22י(ג)(1) קובע כי "אם המפוקח הוא קטין – יובא בפני בית המשפט בהקדם האפשרי ולא יאוחר מ-36 שעות לאחר הפסקת הפיקוח האלקטרוני" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22י). עמי, בן 17, הוא קטין, ולכן יובא בפני בית המשפט לא יאוחר מ-36 שעות. סעיף 22י(ג)(2) קובע כי "אם המפוקח הוא בגיר – יובא בפני בית המשפט בהקדם האפשרי ולא יאוחר מ-3 ימים לאחר הפסקת הפיקוח האלקטרוני" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22י). תמי, בת 19, היא בגירה, ולכן תובא בפני בית המשפט לא יאוחר מ-3 ימים. הוראות אלו מבטיחות פיקוח שיפוטי מהיר על החלטת הממונה, תוך התחשבות בגיל המפוקח.',
    'הסטודנט עלול לטעות ולייחס את אותו מועד הבאה בפני בית המשפט הן לקטין והן לבגיר, מבלי להבחין בהוראות הספציפיות של החוק המבדילות ביניהם.',
    '["מעצר בפיקוח אלקטרוני", "הפסקת פיקוח אלקטרוני", "קטין", "בגיר", "מועדי הבאה בפני בית המשפט", "חוק המעצרים", "זכויות עצור"]'::jsonb,
    '**וריאציה 1 — קטין:** הממונה הפסיק פיקוח אלקטרוני של קטין. מתי יובא בפני בית המשפט? ← בהקדם האפשרי ולא יאוחר מ-36 שעות (סעיף 22י(ג)(1) לחוק המעצרים). **וריאציה 2 — בגיר:** הממונה הפסיק פיקוח אלקטרוני של בגיר. מתי יובא בפני בית המשפט? ← בהקדם האפשרי ולא יאוחר מ-3 ימים (סעיף 22י(ג)(2) לחוק המעצרים). **וריאציה 3 — חשיבות ההבחנה:** מדוע קיימת הבחנה במועדים? ← בשל מעמדו המיוחד של קטין והצורך בפיקוח שיפוטי מהיר יותר על חירותו.',
    'הפסקת פיקוח אלקטרוני ← קטין: 36 שעות. בגיר: 3 ימים. (סעיף 22י(ג) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 22י"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''מעצר בפיקוח אלקטרוני והפסקתו'' → mapped=''search_seizure''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עמי ותמי יובאו בפני בית המשפט בהקדם האפשרי ולא יאוחר מ-36 שעות לאחר הפסקת הפיקוח.', false, 'בחירה זו שגויה. היא מתייחסת למועד הבאת קטין בפני בית המשפט, אך אינה נכונה לגבי בגיר, לגביו המועד ארוך יותר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עמי ותמי יובאו בפני בית המשפט בהקדם האפשרי - עמי לא יאוחר מ-24 שעות לאחר הפסקת הפיקוח, ותמי לא יאוחר מ-36 שעות לאחר הפסקת הפיקוח.', false, 'בחירה זו שגויה. המועדים הנקובים בה אינם תואמים את הוראות החוק לגבי קטין ובגיר לאחר הפסקת פיקוח אלקטרוני.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עמי ותמי יובאו בפני בית המשפט בהקדם האפשרי - עמי לא יאוחר מ-36 שעות לאחר הפסקת הפיקוח, ותמי לא יאוחר מ-3 ימים לאחר הפסקת הפיקוח.', true, 'בחירה זו נכונה. סעיף 22י(ג)(1) לחוק המעצרים קובע כי קטין יובא בפני בית המשפט לא יאוחר מ-36 שעות, וסעיף 22י(ג)(2) קובע כי בגיר יובא בפני בית המשפט לא יאוחר מ-3 ימים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עמי ותמי יובאו בפני בית המשפט בהקדם האפשרי ולא יאוחר מ-3 ימים לאחר הפסקת הפיקוח.', false, 'בחירה זו שגויה. היא מתייחסת למועד הבאת בגיר בפני בית המשפט, אך אינה נכונה לגבי קטין, לגביו המועד קצר יותר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הפסקת פיקוח אלקטרוני - סמכות הממונה', 1, 'הממונה על הפיקוח האלקטרוני הורה על הפסקת הפיקוח האלקטרוני של נאשם עקב הפרת תנאים. האם הממונה חייב להיוועץ בבית המשפט לפני מתן ההוראה על הפסקת הפיקוח?',
    'השאלה בוחנת את סמכותו של הממונה על הפיקוח האלקטרוני להפסיק מעצר בפיקוח אלקטרוני. סעיף 22י לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים) מקנה לממונה סמכות עצמאית להפסיק את הפיקוח במקרים מסוימים, ללא צורך באישור מוקדם של בית המשפט, אך מחייב אותו להודיע על כך לבית המשפט.',
    'סעיף 22י(א) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע כי "הממונה רשאי להפסיק את המעצר בפיקוח אלקטרוני אם שוכנע כי המפוקח הפר תנאי מתנאי הפיקוח האלקטרוני, או אם נתגלו עובדות חדשות המצדיקות זאת" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22י). סעיף 22י(ב) מוסיף כי "הממונה יודיע לבית המשפט על הפסקת המעצר בפיקוח אלקטרוני בהקדם האפשרי" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22י). מכאן עולה כי לממונה סמכות עצמאית להפסיק את הפיקוח, ואין עליו חובה להיוועץ בבית המשפט לפני קבלת ההחלטה, אלא רק להודיע לו על כך. לאחר הפסקת הפיקוח, יובא המפוקח בפני בית המשפט במועדים הקבועים בסעיף 22י(ג) (מ"ת (שלום ב"ש) 56578-08-17 מדינת ישראל נ'' חליל אלהואשלה, רפרנס 1).',
    'הסטודנט עלול לטעות ולחשוב שכל החלטה הנוגעת למעצר דורשת אישור או היוועצות מוקדמת של בית המשפט, מבלי להבחין בסמכות המנהלית המוקנית לממונה על הפיקוח האלקטרוני.',
    '["מעצר בפיקוח אלקטרוני", "הפסקת פיקוח אלקטרוני", "סמכות הממונה", "הפרת תנאים", "חוק המעצרים", "הודעה לבית המשפט"]'::jsonb,
    '**וריאציה 1 — סמכות הממונה:** האם הממונה רשאי להפסיק פיקוח אלקטרוני? ← כן, אם שוכנע שהופרו תנאים או נתגלו עובדות חדשות (סעיף 22י(א) לחוק המעצרים). **וריאציה 2 — חובת היוועצות:** האם הממונה חייב להיוועץ בבית המשפט לפני הפסקה? ← לא, אך חייב להודיע לבית המשפט בהקדם האפשרי (סעיף 22י(ב) לחוק המעצרים). **וריאציה 3 — הבאה בפני בית המשפט:** מה קורה לאחר הפסקת הפיקוח? ← המפוקח יובא בפני בית המשפט במועדים הקבועים בחוק (סעיף 22י(ג) לחוק המעצרים).',
    'הממונה רשאי להפסיק פיקוח אלקטרוני ללא היוועצות מוקדמת עם בית המשפט, אך חייב להודיע לו ולהביא את המפוקח בפניו במועדים הקבועים (סעיף 22י לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 22י", "מ\"ת (שלום ב\"ש) 56578-08-17 מדינת ישראל נ'' חליל אלהואשלה (1.11.2017)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט למעצר בפיקוח אלקטרוני', 2, 'בית המשפט שוקל להורות על מעצר נאשם בפיקוח אלקטרוני. מהם התנאים המצטברים שבית המשפט חייב לבחון לפני מתן צו כזה?',
    'השאלה מתייחסת לתנאים המצטברים שבית המשפט חייב לבחון בטרם יורה על מעצר בפיקוח אלקטרוני, כפי שקבועים בסעיף 22ב(א) לחוק המעצרים. מעצר בפיקוח אלקטרוני נחשב למדרג ביניים בין מעצר מאחורי סורג ובריח לבין שחרור לחלופת מעצר, ועל כן דורש עמידה בתנאים מחמירים.',
    'סעיף 22ב(א) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע את התנאים למעצר בפיקוח אלקטרוני. בית המשפט רשאי להורות על מעצר בפיקוח אלקטרוני אם התקיימו כל אלה: (1) מצא בית המשפט כי התמלאו התנאים למתן צו מעצר לפי הוראות סעיף 21(א) (קיומן של ראיות לכאורה ועילת מעצר); (2) לא ניתן להשיג את מטרת המעצר בדרך של שחרור בערובה כאמור בסעיף 21(ב)(1) (כלומר, אין חלופת מעצר פחותה שתאיין את המסוכנות או חשש השיבוש); (3) הנאשם נתן את הסכמתו למעצר בפיקוח אלקטרוני; (4) בית המשפט מצא כי בנסיבות המקרה מעצר בפיקוח אלקטרוני יאפשר את השגת תכלית המעצר; ו-(5) התקבל דיווח מהמנהל כי מקום הפיקוח המוצע ואמצעי התקשורת בו מאפשרים פיקוח אלקטרוני (מ"ת (שלום ב"ש) 56578-08-17 מדינת ישראל נ'' חליל אלהואשלה, רפרנס 2).',
    'הסטודנט עלול להתמקד רק בחלק מהתנאים (למשל, ראיות ועילה) ולשכוח את התנאים הנוספים הייחודיים למעצר בפיקוח אלקטרוני, כגון הסכמת הנאשם והתאמת מקום הפיקוח.',
    '["מעצר בפיקוח אלקטרוני", "תנאים מצטברים", "ראיות לכאורה", "עילת מעצר", "חלופת מעצר", "הסכמת נאשם", "התאמת מקום פיקוח", "חוק המעצרים"]'::jsonb,
    '**וריאציה 1 — תנאים מהותיים:** מהם התנאים המהותיים למעצר בפיקוח אלקטרוני? ← קיומן של ראיות לכאורה, עילת מעצר, וחוסר אפשרות להשיג את מטרת המעצר בחלופה פחותה (סעיף 22ב(א) לחוק המעצרים). **וריאציה 2 — תנאים פרוצדורליים:** מהם התנאים הפרוצדורליים למעצר בפיקוח אלקטרוני? ← הסכמת הנאשם, ודיווח מהמנהל על התאמת מקום הפיקוח (סעיף 22ב(א) ו-22ב(ג) לחוק המעצרים). **וריאציה 3 — מעמד הפיקוח האלקטרוני:** כיצד נתפס מעצר בפיקוח אלקטרוני? ← כמדרג ביניים בין מעצר מאחורי סורג ובריח לבין חלופת מעצר (מ"ת (שלום ב"ש) 56578-08-17 אלהואשלה, רפרנס 4).',
    'מעצר בפיקוח אלקטרוני ← דורש ראיות, עילה, חוסר חלופה פחותה, הסכמת נאשם, והתאמת מקום (סעיף 22ב(א) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 22ב", "מ\"ת (שלום ב\"ש) 56578-08-17 מדינת ישראל נ'' חליל אלהואשלה (1.11.2017)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'מעצר בפיקוח אלקטרוני בעבירות חמורות', 3, 'נאשם מואשם בעבירת רצח, המקימה חזקת מסוכנות סטטוטורית. הוא מבקש להשתחרר למעצר בפיקוח אלקטרוני. מה הדין?',
    'השאלה עוסקת בסייגים למעצר בפיקוח אלקטרוני בעבירות חמורות, המנויות בסעיף 22ב(ב) לחוק המעצרים, כגון עבירות רצח, נשק וסמים. בעבירות אלו, נקודת המוצא היא מעצר מאחורי סורג ובריח, ורק ב''טעמים מיוחדים שיירשמו'' ניתן להורות על מעצר בפיקוח אלקטרוני, תוך איזון בין חומרת העבירה למאפייני הנאשם.',
    'סעיף 22ב(ב) לחוק סדר הדין הפלילי (סמכויות אכיפה - מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע כי "על אף האמור בסעיף קטן (א), מצא בית המשפט כי יש לעצור את הנאשם, לא יוטל מעצר בפיקוח אלקטרוני לגבי מי שנאשם בעבירות המפורטות להלן, אלא אם כן שוכנע בית המשפט, מטעמים מיוחדים שיירשמו, כי בשל נסיבות ביצוע העבירה או נסיבותיו המיוחדות של הנאשם, ובכלל זה היותו של הנאשם קטין, ניתן להסתפק במעצר בפיקוח אלקטרוני" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22ב). עבירת רצח נמנית על העבירות המקימות חזקת מסוכנות סטטוטורית לפי סעיף 21(א)(1)(ג) לחוק המעצרים, ולכן חל עליה סייג זה (בש"פ 5038/21 מדינת ישראל נ'' אבראהים שאהין, רפרנס 59). הפסיקה מדגישה כי בעבירות אלו, נקודת המוצא היא מעצר מאחורי סורג ובריח, ורק במקרים חריגים מאוד, בהתקיים טעמים מיוחדים, ניתן לסטות מכך (ע"מ (פסיקה צבאית יבד"ץ) 20173-02-26 רס"ר א'' א'' נ'' התובע הצבאי הראשי, רפרנס 60; מ"ת (מחוזי ב"ש) 76564-05-23 סאמי אבו עצא נ'' מדינת ישראל פמ"ד פלילי, רפרנס 42).',
    'הסטודנט עלול לטעות ולחשוב שחזקת המסוכנות הסטטוטורית מונעת לחלוטין מעצר בפיקוח אלקטרוני בעבירות חמורות, מבלי להכיר את החריג של ''טעמים מיוחדים שיירשמו''.',
    '["מעצר בפיקוח אלקטרוני", "עבירות חמורות", "חזקת מסוכנות סטטוטורית", "טעמים מיוחדים", "חוק המעצרים", "איזון אינטרסים", "נסיבות הנאשם"]'::jsonb,
    '**וריאציה 1 — הכלל בעבירות חמורות:** מה הכלל לגבי מעצר בפיקוח אלקטרוני בעבירות כמו רצח? ← לא יוטל, אלא אם כן שוכנע בית המשפט מטעמים מיוחדים שיירשמו (סעיף 22ב(ב) לחוק המעצרים). **וריאציה 2 — מהם ''טעמים מיוחדים''?** מה יכול להיחשב ''טעמים מיוחדים''? ← נסיבות ביצוע העבירה או נסיבותיו המיוחדות של הנאשם, כולל היותו קטין (סעיף 22ב(ב) לחוק המעצרים). **וריאציה 3 — נקודת המוצא:** מהי נקודת המוצא בעבירות נשק (המקימות חזקת מסוכנות סטטוטורית)? ← מעצר מאחורי סורג ובריח, ורק בנסיבות חריגות מאוד ניתן לסטות מכך (ע"מ (פסיקה צבאית יבד"ץ) 20173-02-26 רס"ר א'' א'', רפרנס 60).',
    'מעצר בפיקוח אלקטרוני בעבירות חמורות (כמו רצח) ← רק ב''טעמים מיוחדים שיירשמו'' (סעיף 22ב(ב) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 22ב", "בש\"פ 5038/21 מדינת ישראל נ'' אבראהים שאהין (25.7.2021)", "ע\"מ (פסיקה צבאית יבד\"ץ) 20173-02-26 רס\"ר א'' א'' נ'' התובע הצבאי הראשי (12.2.2026)", "מ\"ת (מחוזי ב\"ש) 76564-05-23 סאמי אבו עצא נ'' מדינת ישראל פמ\"ד פלילי (13.11.2023)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'חלונות התאווררות לעצור בפיקוח אלקטרוני', 4, 'נאשם נתון במעצר בפיקוח אלקטרוני ומבקש לצאת לעבודה או להתאווררות. מהי הגישה הכללית של הפסיקה לבקשות מסוג זה?',
    'השאלה בוחנת את הגישה השיפוטית בנוגע לאפשרות של עצור בפיקוח אלקטרוני לצאת מחוץ למקום הפיקוח לצורך עבודה או התאווררות. הפסיקה רואה במעצר בפיקוח אלקטרוני כמעצר לכל דבר, ועל כן נוטה לצמצם מאוד את האפשרות לפתיחת ''חלונות יציאה'', למעט לתכליות מוגדרות בחוק או במקרים חריגים ביותר, תוך איזון בין חירות הנאשם למטרות המעצר.',
    'מעצר בפיקוח אלקטרוני, על פי תיקון מס'' 11 לחוק המעצרים, נחשב למעצר לכל דבר, ולא לחלופת מעצר (מ"ת (שלום נצ'') 9373-04-20 מוחמד טבאש נ'' מדינת ישראל, רפרנס 51). סעיף 22ד(1)(ג) לחוק המעצרים מצביע על הקריטריונים בהם ניתן לשקול היתר לפתיחת חלונות פיקוח, ואלה הם: טיפול רפואי, טיפול נפשי או טיפול אחר הדרוש למפוקח, או לצרכים טיפוליים-שיקומיים, או לתכלית אחרת שהומלצה בתסקיר המבחן (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 22ד). הפסיקה קבעה כי מעצר בפיקוח אלקטרוני אינו מתיישב עם היתר יציאה לעבודה, וכי אף שקיימת סמכות לפתיחת חלון פיקוח לצרכי עבודה, יש להפעילה במשורה ורק במקרים יוצאי דופן (ח"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' ר'' ו'', רפרנס 55; מ"ת (שלום נצ'') 9373-04-20 טבאש, רפרנס 51). גם לגבי התאווררות, הגישה היא מצמצמת למקרים חריגים ומצומצמים, בהם התכלית עולה בקנה אחד עם תכליות המעצר (ח"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' ר'' ו'', רפרנס 55).',
    'הסטודנט עלול לטעות ולחשוב שמעצר בפיקוח אלקטרוני דומה יותר למעצר בית רגיל, ולכן מאפשר גמישות רבה יותר ביציאות, מבלי להבין את מעמדו כמעצר לכל דבר ואת הגישה המצמצמת של הפסיקה.',
    '["מעצר בפיקוח אלקטרוני", "חלונות יציאה", "התאווררות", "עבודה", "חוק המעצרים", "תכליות מעצר", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — מעמד הפיקוח:** האם מעצר בפיקוח אלקטרוני הוא מעצר של ממש? ← כן, הוא נחשב מעצר לכל דבר, ולא חלופת מעצר (מ"ת (שלום נצ'') 9373-04-20 טבאש, רפרנס 51). **וריאציה 2 — יציאה לעבודה:** האם ניתן לאשר יציאה לעבודה לעצור בפיקוח אלקטרוני? ← ככלל לא, אלא במקרים חריגים ויוצאי דופן (ח"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' ר'' ו'', רפרנס 55). **וריאציה 3 — יציאה להתאווררות:** האם ניתן לאשר יציאה להתאווררות? ← רק במקרים חריגים ומצומצמים, בהם התכלית עולה בקנה אחד עם תכליות המעצר (ח"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' ר'' ו'', רפרנס 55).',
    'מעצר בפיקוח אלקטרוני ← מעצר לכל דבר ← חלונות יציאה (עבודה/התאווררות) ← רק במקרים חריגים ומצומצמים (סעיף 22ד לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 22ד", "מ\"ת (שלום נצ'') 9373-04-20 מוחמד טבאש נ'' מדינת ישראל (26.8.2020)", "ח\"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' ר'' ו'' (1.8.2022)", "ח\"א (פסיקה צבאית מרכז) 68/22 התובע הצבאי נ'' רב\"ט ר'' ר'' ו'' (29.8.2022)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, הממונה חייב להיוועץ בבית המשפט לפני הפסקת הפיקוח, שכן רק לבית המשפט סמכות להורות על מעצר.', false, 'בחירה זו שגויה. סעיף 22י(א) לחוק המעצרים מקנה לממונה סמכות עצמאית להפסיק את הפיקוח, ללא צורך בהיוועצות מוקדמת עם בית המשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, הממונה רשאי להפסיק את הפיקוח ללא היוועצות מוקדמת, אך עליו להודיע על כך לבית המשפט בהקדם האפשרי.', true, 'בחירה זו נכונה. סעיף 22י(א) לחוק המעצרים קובע כי הממונה רשאי להפסיק את הפיקוח, וסעיף 22י(ב) מחייב אותו להודיע על כך לבית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, הממונה חייב להיוועץ בבית המשפט, אך רק אם מדובר בהפרה חמורה של תנאי הפיקוח.', false, 'בחירה זו שגויה. החוק אינו מבחין בין חומרת ההפרה לעניין חובת היוועצות מוקדמת, ואינו דורש היוועצות כזו כלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, הממונה רשאי להפסיק את הפיקוח, אך רק אם קיבל את הסכמת הנאשם להפסקתו.', false, 'בחירה זו שגויה. הסכמת הנאשם אינה תנאי להפסקת הפיקוח על ידי הממונה, במיוחד כאשר מדובר בהפרת תנאים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'קיומן של ראיות לכאורה, עילת מעצר, והסכמת הנאשם למעצר בפיקוח אלקטרוני.', false, 'בחירה זו חלקית. היא כוללת את התנאים הראשונים אך חסרה את התנאי המרכזי של חוסר אפשרות להשיג את מטרת המעצר בחלופה פחותה, ואת התנאים הטכניים של הפיקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'התמלאו התנאים למתן צו מעצר לפי סעיף 21(א), לא ניתן להשיג את מטרת המעצר בחלופה פחותה, הנאשם הסכים לפיקוח, ומקום הפיקוח מאפשר זאת.', true, 'בחירה זו נכונה. היא משקפת את כל התנאים המצטברים הקבועים בסעיף 22ב(א) לחוק המעצרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'קיומן של ראיות לכאורה, עילת מעצר, והמלצה חיובית של שירות המבחן.', false, 'בחירה זו שגויה. המלצת שירות המבחן היא שיקול חשוב אך אינה תנאי מצטבר מחייב בחוק למתן צו מעצר בפיקוח אלקטרוני, וחסרים תנאים נוספים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'לא ניתן להשיג את מטרת המעצר בחלופה פחותה, והנאשם הסכים למעצר בפיקוח אלקטרוני.', false, 'בחירה זו חלקית. היא מתעלמת מהתנאים הבסיסיים של קיומן של ראיות לכאורה ועילת מעצר, וכן מהתנאים הטכניים של הפיקוח.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לא ניתן להורות על מעצר בפיקוח אלקטרוני בעבירת רצח, שכן חזקת המסוכנות הסטטוטורית מונעת זאת באופן מוחלט.', false, 'בחירה זו שגויה. סעיף 22ב(ב) לחוק המעצרים מאפשר מעצר בפיקוח אלקטרוני גם בעבירות אלו, אך רק ב''טעמים מיוחדים שיירשמו''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'ניתן להורות על מעצר בפיקוח אלקטרוני בעבירת רצח, אך רק אם בית המשפט שוכנע, מטעמים מיוחדים שיירשמו, כי ניתן להסתפק בכך.', true, 'בחירה זו נכונה. סעיף 22ב(ב) לחוק המעצרים קובע חריג לכלל אי-המעצר בפיקוח אלקטרוני בעבירות חמורות, המאפשר זאת ב''טעמים מיוחדים שיירשמו''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'ניתן להורות על מעצר בפיקוח אלקטרוני בעבירת רצח רק אם הנאשם קטין ונעדר עבר פלילי.', false, 'בחירה זו שגויה. אף שאלו שיקולים רלוונטיים, הם אינם תנאים בלעדיים, והחוק מתייחס ל''נסיבות ביצוע העבירה או נסיבותיו המיוחדות של הנאשם'', כולל היותו קטין, כחלק מ''טעמים מיוחדים''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט יורה על מעצר בפיקוח אלקטרוני רק אם שירות המבחן המליץ על כך באופן חד משמעי.', false, 'בחירה זו שגויה. המלצת שירות המבחן היא שיקול חשוב, אך אינה מחייבת את בית המשפט, וההחלטה נתונה לשיקול דעתו על בסיס ''טעמים מיוחדים''.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הפסיקה נוטה לאשר חלונות יציאה לעבודה או התאווררות, שכן מעצר בפיקוח אלקטרוני אינו מעצר של ממש.', false, 'בחירה זו שגויה. הפסיקה קובעת כי מעצר בפיקוח אלקטרוני הוא מעצר לכל דבר, ונוטה לצמצם מאוד את האפשרות לחלונות יציאה לעבודה או התאווררות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הפסיקה נוטה לדחות בקשות לחלונות יציאה לעבודה או התאווררות, שכן מעצר בפיקוח אלקטרוני הוא מעצר לכל דבר, וחלונות כאלה יאושרו רק במקרים חריגים ומצומצמים.', true, 'בחירה זו נכונה. הפסיקה רואה במעצר בפיקוח אלקטרוני כמעצר של ממש, ומתירה חלונות יציאה רק לתכליות מוגדרות בחוק או במקרים חריגים ביותר, מטעמים שיירשמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'חלונות יציאה לעבודה יאושרו תמיד, ואילו חלונות התאווררות יאושרו רק אם הנאשם קטין.', false, 'בחירה זו שגויה. אין הבחנה כזו בחוק או בפסיקה, והגישה הכללית היא לצמצם את כל סוגי חלונות היציאה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'היתר יציאה לעבודה יינתן רק אם הנאשם הוא המפרנס היחיד במשפחתו, ואילו התאווררות אינה אפשרית כלל.', false, 'בחירה זו שגויה. אף ששיקולים כלכליים יכולים להילקח בחשבון, הם אינם תנאי בלעדי, והתאווררות אפשרית במקרים חריגים.', 4);

END $$;

