-- notes: needs_review=true | subtopic_mapping_review: original='שחרור בערובה על ידי קצין ממונה וערר על תנאיו' → mapped='search_seizure'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
