  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q21';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q21 skipped: external_id % already exists', '2019-S-Q21';
