  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q21', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'דני שוחרר בערובה על ידי הקצין הממונה, והוא מעוניין להגיש ערר על תנאי שחרורו בערובה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 21}'::jsonb,
    'השאלה עוסקת בזכותו של חשוד ששוחרר בערובה על ידי הקצין הממונה לערור על תנאי שחרורו. חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים) מבחין בין ערר על גובה הערובה לבין ערר על תנאי השחרור, וקובע מועדים ותנאים שונים לכל אחד מהם, תוך מתן גמישות רבה יותר בערר על תנאים המשתנים עם הזמן והנסיבות.',
    'סעיף 43 לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) מסדיר את זכות הערר על החלטות הקצין הממונה. סעיף 43(1) קובע כי מי ששוחרר בערובה על ידי הקצין הממונה רשאי לערור בפני בית משפט שלום "על גובה הערובה או על סבירות תנאיה, תוך 14 ימים מיום החלטת הקצין הממונה" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 43). לעומת זאת, סעיף 43(2) קובע כי ערר "על תנאי השחרור בערובה שנקבעו" ניתן להגיש "בכל עת, ובתנאי שהשתנו הנסיבות ויש בהן כדי להשפיע על קביעת תנאי השחרור" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 43). ההבחנה בין המועדים והתנאים נובעת מהצורך בייצוב מהיר של גובה הערובה, לעומת גמישות רבה יותר בתנאים המגבילים, אשר עשויים להשתנות עם התפתחות החקירה או חלוף הזמן (Literature: נבו - המתמחה, דיני מעצרים (2026) | קביעת ערובה על ידי הקצין הממונה). במקרה של דני, המעוניין לערור על תנאי שחרורו, עליו להגיש את הערר לבית משפט השלום, והוא רשאי לעשות זאת בכל עת, ובלבד שהשתנו הנסיבות הרלוונטיות.',
    'הסטודנט עלול לבלבל בין המועדים השונים להגשת ערר על החלטת קצין ממונה, ולא להבחין בין ערר על גובה הערובה (14 יום) לבין ערר על תנאי השחרור (בכל עת, בשינוי נסיבות).',
    '["ערר", "קצין ממונה", "תנאי שחרור בערובה", "שינוי נסיבות", "מועדים להגשת ערר", "חוק המעצרים", "בית משפט השלום"]'::jsonb,
    '**וריאציה 1 — ערר על תנאי שחרור:** מתי מגישים ערר על תנאי שחרור שנקבעו על ידי קצין ממונה? ← בכל עת, אם נשתנו הנסיבות (סעיף 43(2) לחוק המעצרים). **וריאציה 2 — ערר על גובה ערובה:** מתי מגישים ערר על גובה ערובה שנקבעה על ידי קצין ממונה? ← תוך 14 יום (סעיף 43(1) לחוק המעצרים). **וריאציה 3 — ערכאה:** לאיזו ערכאה מוגש הערר? ← לבית משפט השלום (סעיף 43 לחוק המעצרים).',
    'ערר על תנאי שחרור (קצין ממונה) ← לבית משפט השלום ← בכל עת ← אם נשתנו הנסיבות (סעיף 43(2) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 43", "נבו - המתמחה, דיני מעצרים (2026) | קביעת ערובה על ידי הקצין הממונה"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''שחרור בערובה על ידי קצין ממונה וערר על תנאיו'' → mapped=''search_seizure''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על דני להגיש ערר למפקד המחוז של המשטרה בתוך 14 יום.', false, 'בחירה זו שגויה. ערר על החלטת קצין ממונה מוגש לבית משפט השלום, ולא למפקד המחוז, והמועד להגשה תלוי בסוג הערר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על דני להגיש ערר ליועץ המשפטי לממשלה בתוך 14 יום, בתנאי שהשתנו הנסיבות שיש בהן כדי להשפיע על קביעת התנאים.', false, 'בחירה זו שגויה. ערר מוגש לבית משפט השלום, ולא ליועץ המשפטי לממשלה. המועד של 14 יום רלוונטי לערר על גובה הערובה, לא על תנאי השחרור.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על דני להגיש ערר לבית משפט השלום בתוך 30 יום.', false, 'בחירה זו שגויה. המועד להגשת ערר על תנאי שחרור בערובה אינו מוגבל ל-30 יום, אלא ניתן להגישו בכל עת, בכפוף לשינוי נסיבות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'דני רשאי להגיש ערר לבית משפט השלום בכל עת, בתנאי שהשתנו הנסיבות שיש בהן כדי להשפיע על קביעת התנאים.', true, 'בחירה זו נכונה. סעיף 43(2) לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים) קובע כי מי ששוחרר בערובה על ידי הקצין הממונה רשאי לערור על תנאי השחרור בערובה בפני בית משפט השלום בכל עת, אם נשתנו הנסיבות ויש בהן כדי להשפיע על קביעת תנאי השחרור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ערר על גובה ערובה שנקבעה על ידי קצין ממונה', 1, 'חשוד שוחרר בערובה על ידי הקצין הממונה, והוא מעוניין להגיש ערר על גובה הערובה שנקבעה. מהו המועד להגשת ערר זה?',
    'שאלה זו בוחנת את ההבחנה בין סוגי העררים השונים שניתן להגיש על החלטת קצין ממונה, ובפרט את המועד להגשת ערר על גובה הערובה. חוק המעצרים קובע מועדים שונים לעררים על גובה הערובה לעומת עררים על תנאי השחרור, וחשוב להכיר את ההבחנה הזו.',
    'סעיף 43 לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע את זכות הערר על החלטת הקצין הממונה. סעיף 43(1) לחוק קובע במפורש כי מי ששוחרר בערובה על ידי הקצין הממונה רשאי לערור בפני בית משפט שלום "על גובה הערובה או על סבירות תנאיה, תוך 14 ימים מיום החלטת הקצין הממונה" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 43). לעומת זאת, ערר על תנאי השחרור בערובה ניתן להגיש בכל עת, אם נשתנו הנסיבות (סעיף 43(2)). ההבחנה במועדים נובעת מהצורך בייצוב מהיר של גובה הערובה, לעומת גמישות רבה יותר בתנאים המשתנים עם הזמן והנסיבות (Literature: רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר - מורה נבוכים (2024) | ט. בקשת חשוד לשחרור בערובה - סעיף 44(א)).',
    'הסטודנט עלול לבלבל בין המועדים השונים להגשת ערר על החלטת קצין ממונה, ולא להבחין בין ערר על גובה הערובה לבין ערר על תנאי השחרור.',
    '["ערר", "קצין ממונה", "גובה ערובה", "מועדים להגשת ערר", "חוק המעצרים", "בית משפט השלום"]'::jsonb,
    '**וריאציה 1 — ערר על גובה ערובה:** מתי מגישים ערר על גובה ערובה שנקבעה על ידי קצין ממונה? ← תוך 14 יום (סעיף 43(1) לחוק המעצרים). **וריאציה 2 — ערר על תנאי שחרור:** מתי מגישים ערר על תנאי שחרור שנקבעו על ידי קצין ממונה? ← בכל עת, אם נשתנו הנסיבות (סעיף 43(2) לחוק המעצרים). **וריאציה 3 — ערכאה:** לאיזו ערכאה מוגש הערר? ← לבית משפט השלום (סעיף 43 לחוק המעצרים).',
    'ערר על גובה ערובה (קצין ממונה) ← 14 יום. ערר על תנאי שחרור (קצין ממונה) ← בכל עת, בשינוי נסיבות. (סעיף 43 לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 43", "רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר - מורה נבוכים (2024) | ט. בקשת חשוד לשחרור בערובה - סעיף 44(א)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שינוי נסיבות בערר על תנאי שחרור', 2, 'מה נחשב ''שינוי נסיבות'' המצדיק הגשת ערר על תנאי שחרור בערובה שנקבעו על ידי קצין ממונה?',
    'השאלה מתמקדת בפרשנות המונח ''שינוי נסיבות'' בהקשר של ערר על תנאי שחרור בערובה. הפסיקה הרחיבה את משמעות המונח מעבר לשינויים עובדתיים ישירים, וכוללת בו גם חלוף זמן ניכר והתפתחויות בחקירה, כל עוד יש להם השפעה על הצורך בתנאים המגבילים.',
    'סעיף 43(2) לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ"ו-1996, מאפשר הגשת ערר על תנאי שחרור בערובה "אם נשתנו הנסיבות ויש בהן כדי להשפיע על קביעת תנאי השחרור" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 43). הפסיקה פירשה את המונח ''שינוי נסיבות'' באופן רחב. הוא יכול לכלול התפתחות חדשה בחקירה, חלוף זמן ניכר, או שינוי במצב המשפטי של החשוד (בש"פ 5536/13 מדינת ישראל נ'' פלוני, רפרנס 19; מ"י (שלום ת"א) 8580-08-20 מדינת ישראל נ'' אמיר ברמלי, רפרנס 9). לדוגמה, שמיעת כל ראיות התביעה יכולה להיחשב שינוי נסיבות המצדיק בחינה מחודשת של תנאי השחרור, שכן חשש לשיבוש הליכי משפט פוחת (בש"פ 9401/09 פלוני נ'' מדינת ישראל, רפרנס 24). המבחן הוא האם השינוי משפיע על הצורך בתנאים המגבילים ועל האיזון בין חירות החשוד לבין מטרות המעצר (Literature: רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר מורה נבוכים (2025) | ט. מעצר בפיקוח אלקטרוני).',
    'הסטודנט עלול לפרש את המונח ''שינוי נסיבות'' באופן מצומצם מדי, ולא לכלול בו גורמים כמו חלוף זמן או התפתחות בחקירה, אשר הפסיקה רואה בהם שינוי נסיבות רלוונטי.',
    '["שינוי נסיבות", "ערר על תנאי שחרור", "חלוף זמן ניכר", "התפתחות בחקירה", "חוק המעצרים", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — הגדרת שינוי נסיבות:** מה נחשב ''שינוי נסיבות'' בערר על תנאי שחרור? ← התפתחות חדשה בחקירה, חלוף זמן ניכר, או שינוי במצב המשפטי של החשוד (בש"פ 5536/13 פלוני, רפרנס 19). **וריאציה 2 — דוגמה לשינוי נסיבות:** האם שמיעת כל ראיות התביעה היא שינוי נסיבות? ← כן, שכן חשש לשיבוש הליכי משפט פוחת (בש"פ 9401/09 פלוני, רפרנס 24). **וריאציה 3 — מטרת השינוי:** מהי מטרת בחינת שינוי הנסיבות? ← לבדוק האם השינוי משפיע על הצורך בתנאים המגבילים ועל האיזון בין חירות החשוד למטרות המעצר (מ"י (שלום ת"א) 8580-08-20 ברמלי, רפרנס 9).',
    'שינוי נסיבות בערר על תנאי שחרור ← התפתחות בחקירה, חלוף זמן, שינוי מצב משפטי ← משפיע על הצורך בתנאים (סעיף 43(2) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 43", "בש\"פ 5536/13 מדינת ישראל נ'' פלוני (20.8.2013)", "מ\"י (שלום ת\"א) 8580-08-20 מדינת ישראל נ'' אמיר ברמלי (28.1.2021)", "בש\"פ 9401/09 פלוני נ'' מדינת ישראל (27.11.2009)", "רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר מורה נבוכים (2025) | ט. מעצר בפיקוח אלקטרוני"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'ערר על תנאי הפקדת נשק', 3, 'חשוד בעבירה שנעשתה באלימות חמורה שוחרר בערובה על ידי הקצין הממונה, ובין תנאי השחרור נקבעה חובת הפקדת כלי הנשק שברשותו. החשוד מעוניין לערור על תנאי זה. מה הדין?',
    'השאלה עוסקת בחריג לכלל ''שינוי נסיבות'' בהגשת ערר על תנאי שחרור בערובה, המתייחס ספציפית לחובת הפקדת נשק. סעיף 43(3) לחוק המעצרים מאפשר ערר על תנאי זה גם ללא שינוי נסיבות, וזאת מתוך איזון בין הצורך בביטחון הציבור לבין זכותו של החשוד.',
    'סעיף 42(ב2) לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע כי "החליט הקצין הממונה לשחרר בערובה חשוד בעבירה שנעשתה באלימות חמורה, באכזריות או תוך שימוש בנשק חם או קר, יתנה את שחרורו בהפקדת כלי הנשק שברשותו כאמור בסעיף קטן (ב)(8)" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 42). סעיף 43(3) לחוק קובע חריג לכלל שלפיו ערר על תנאי שחרור מותנה בשינוי נסיבות. הוא מאפשר ערר על תנאי לפי סעיף 42(ב2) "אם בנסיבות העניין לא נשקפת סכנה לבטחונו של אדם או לבטחון הציבור מביטול התנאי" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 43). כלומר, במקרה של חובת הפקדת נשק בעבירות אלימות חמורה, החשוד רשאי לערור על התנאי גם אם לא חל שינוי נסיבות, ובלבד שיוכיח כי ביטול התנאי אינו מסכן את ביטחון הציבור או אדם (Literature: נבו - המתמחה, דיני מעצרים (2026) | קביעת ערובה על ידי הקצין הממונה).',
    'הסטודנט עלול לטעות ולחשוב שכל ערר על תנאי שחרור מחייב שינוי נסיבות, מבלי להכיר את החריג הספציפי הנוגע להפקדת נשק.',
    '["ערר", "קצין ממונה", "הפקדת נשק", "עבירות אלימות חמורה", "חריג לשינוי נסיבות", "ביטחון הציבור", "חוק המעצרים"]'::jsonb,
    '**וריאציה 1 — חובת הפקדת נשק:** מתי הקצין הממונה חייב להתנות שחרור בהפקדת נשק? ← בעבירה שנעשתה באלימות חמורה, באכזריות או תוך שימוש בנשק חם או קר (סעיף 42(ב2) לחוק המעצרים). **וריאציה 2 — ערר על תנאי הפקדת נשק:** האם ניתן לערור על תנאי הפקדת נשק ללא שינוי נסיבות? ← כן, אם לא נשקפת סכנה לביטחון אדם או הציבור מביטול התנאי (סעיף 43(3) לחוק המעצרים). **וריאציה 3 — ערכאה:** לאיזו ערכאה מוגש ערר זה? ← לבית משפט השלום (סעיף 43 לחוק המעצרים).',
    'ערר על תנאי הפקדת נשק (קצין ממונה) ← לבית משפט השלום ← גם ללא שינוי נסיבות ← אם אין סכנה (סעיפים 42(ב2), 43(3) לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 42", "חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 43", "נבו - המתמחה, דיני מעצרים (2026) | קביעת ערובה על ידי הקצין הממונה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'בקשה לעיון חוזר על החלטת בית משפט', 4, 'נאשם ששוחרר בערובה על ידי בית המשפט מעוניין לשנות את תנאי שחרורו. מהו ההליך המתאים לכך?',
    'השאלה עוסקת בהליך המתאים לשינוי תנאי שחרור בערובה שנקבעו על ידי בית המשפט. בניגוד לערר על החלטת קצין ממונה, כאשר ההחלטה ניתנה על ידי בית המשפט, ההליך המתאים הוא בקשה לעיון חוזר, המאפשרת בחינה מחודשת של התנאים לאור שינוי נסיבות.',
    'סעיף 52(א) לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ"ו-1996 (להלן: חוק המעצרים) קובע כי "עצור, משוחרר בערובה או תובע רשאי לפנות לבית המשפט בבקשה לעיון חוזר, בענין הנוגע למעצר, לשחרור או להפרת תנאי השחרור בערובה, לרבות בהחלטה לפי סעיף זה, אם נתגלו עובדות חדשות, נשתנו נסיבות או עבר זמן ניכר מעת מתן ההחלטה" (Law: חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), סעיף 52). הליך זה מאפשר לבית המשפט שנתן את ההחלטה המקורית לבחון אותה מחדש לאור שינויים שהתרחשו. זאת בניגוד לערר, המוגש לערכאה גבוהה יותר ובוחן את חוקיות וסבירות ההחלטה המקורית (Literature: רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר מורה נבוכים (2025) | ט. בקשת חשוד לשחרור בערובה - סעיף 44(א)). הפסיקה מדגישה כי בקשה לעיון חוזר היא המסלול הנכון כאשר חל שינוי נסיבות או חלוף זמן ניכר (בש"פ 5536/13 מדינת ישראל נ'' פלוני, רפרנס 19).',
    'הסטודנט עלול לבלבל בין הליך הערר לבין הליך העיון החוזר, ולא להבין מתי יש לפנות לערכאה גבוהה יותר (ערר) ומתי לערכאה שנתנה את ההחלטה (עיון חוזר).',
    '["עיון חוזר", "שינוי נסיבות", "תנאי שחרור בערובה", "בית המשפט", "חוק המעצרים", "הליך דיוני", "ערר"]'::jsonb,
    '**וריאציה 1 — שינוי תנאים שנקבעו על ידי בית המשפט:** מהו ההליך לשינוי תנאי שחרור שנקבעו על ידי בית המשפט? ← בקשה לעיון חוזר (סעיף 52 לחוק המעצרים). **וריאציה 2 — עילות לעיון חוזר:** מתי ניתן להגיש בקשה לעיון חוזר? ← אם נתגלו עובדות חדשות, נשתנו נסיבות או עבר זמן ניכר (סעיף 52(א) לחוק המעצרים). **וריאציה 3 — הבחנה מערר:** מה ההבדל בין עיון חוזר לערר? ← עיון חוזר מוגש לערכאה שנתנה את ההחלטה, וערר לערכאה גבוהה יותר (Literature: רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר מורה נבוכים (2025) | ט. בקשת חשוד לשחרור בערובה - סעיף 44(א)).',
    'שינוי תנאי שחרור שנקבעו על ידי בית המשפט ← בקשה לעיון חוזר ← אם נתגלו עובדות חדשות, נשתנו נסיבות או עבר זמן ניכר (סעיף 52 לחוק המעצרים).',
    '["חוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים), תשנ\"ו-1996, סעיף 52", "בש\"פ 5536/13 מדינת ישראל נ'' פלוני (20.8.2013)", "מ\"י (שלום ת\"א) 8580-08-20 מדינת ישראל נ'' אמיר ברמלי (28.1.2021)", "רון שפירא, איתי ברסלר-גונן, אילנית הלל, הליכי מעצר מורה נבוכים (2025) | ט. בקשת חשוד לשחרור בערובה - סעיף 44(א)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בכל עת, בתנאי שהשתנו הנסיבות.', false, 'בחירה זו שגויה. מועד זה רלוונטי לערר על תנאי השחרור, ולא על גובה הערובה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'תוך 14 יום מיום החלטת הקצין הממונה.', true, 'בחירה זו נכונה. סעיף 43(1) לחוק סדר הדין הפלילי (סמכויות אכיפה – מעצרים) קובע כי ערר על גובה הערובה או סבירות תנאיה יוגש תוך 14 יום מיום החלטת הקצין הממונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'תוך 30 יום מיום החלטת הקצין הממונה.', false, 'בחירה זו שגויה. המועד של 30 יום אינו רלוונטי לערר על החלטת קצין ממונה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'תוך 7 ימים מיום מתן הערבות או הערבון.', false, 'בחירה זו שגויה. מועד זה רלוונטי לערר על החלטת קצין משטרה בצו בדבר הוראות ביטחון (יהודה והשומרון), ולא בחוק המעצרים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'כל שינוי במצב האישי של החשוד, גם אם אינו משפיע על מטרת המעצר.', false, 'בחירה זו שגויה. שינוי נסיבות צריך להיות רלוונטי ובעל השפעה על קביעת תנאי השחרור, ולא כל שינוי אישי יצדיק זאת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'התפתחות חדשה בחקירה, חלוף זמן ניכר, או שינוי במצב המשפטי של החשוד, שיש בהם כדי להשפיע על קביעת התנאים.', true, 'בחירה זו נכונה. הפסיקה מפרשת ''שינוי נסיבות'' באופן רחב וכוללת בו התפתחות בחקירה, חלוף זמן ניכר, או שינוי במצב המשפטי, כל עוד יש להם השפעה על תנאי השחרור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק שינוי בחומרת העבירה המיוחסת לחשוד.', false, 'בחירה זו שגויה. שינוי נסיבות אינו מוגבל רק לשינוי בחומרת העבירה, אלא יכול לכלול מגוון רחב של גורמים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רק אם הקצין הממונה עצמו מסכים כי חל שינוי בנסיבות.', false, 'בחירה זו שגויה. הסכמת הקצין הממונה אינה תנאי להגשת ערר על שינוי נסיבות, אלא בית המשפט הוא שיכריע בכך.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'החשוד אינו רשאי לערור על תנאי זה, שכן הוא חובה סטטוטורית בעבירות אלימות חמורה.', false, 'בחירה זו שגויה. החוק מאפשר ערר על תנאי זה, אך בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'החשוד רשאי לערור על תנאי זה בפני בית משפט השלום, גם אם לא נשתנו הנסיבות, אם בנסיבות העניין לא נשקפת סכנה לביטחונו של אדם או לביטחון הציבור מביטול התנאי.', true, 'בחירה זו נכונה. סעיף 43(3) לחוק המעצרים קובע חריג לכלל שינוי הנסיבות, ומאפשר ערר על תנאי הפקדת נשק אם לא נשקפת סכנה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'החשוד רשאי לערור על תנאי זה רק אם הקצין הממונה הסכים לביטולו.', false, 'בחירה זו שגויה. הסכמת הקצין הממונה אינה תנאי להגשת ערר, אלא בית המשפט הוא שיכריע בכך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'החשוד רשאי לערור על תנאי זה רק אם יוכיח כי הנשק אינו שלו.', false, 'בחירה זו שגויה. בעלות על הנשק אינה התנאי לערר, אלא היעדר סכנה לביטחון הציבור או אדם.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הגשת ערר לבית המשפט שלערעור.', false, 'בחירה זו שגויה. ערר מוגש על החלטה שניתנה, אך שינוי תנאים בעקבות שינוי נסיבות נעשה באמצעות בקשה לעיון חוזר בערכאה שנתנה את ההחלטה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הגשת בקשה לעיון חוזר לבית המשפט שנתן את ההחלטה, אם נתגלו עובדות חדשות, נשתנו נסיבות או עבר זמן ניכר.', true, 'בחירה זו נכונה. סעיף 52(א) לחוק המעצרים קובע כי משוחרר בערובה רשאי לפנות לבית המשפט בבקשה לעיון חוזר אם נתגלו עובדות חדשות, נשתנו נסיבות או עבר זמן ניכר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הגשת בקשה לביטול הערובה ליועץ המשפטי לממשלה.', false, 'בחירה זו שגויה. היועץ המשפטי לממשלה אינו הגורם המוסמך לדון בבקשות לשינוי תנאי שחרור בערובה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הגשת בקשה לשינוי תנאים לקצין הממונה.', false, 'בחירה זו שגויה. הקצין הממונה מוסמך לקבוע תנאי שחרור לחשודים, אך לא לשנות תנאים שנקבעו על ידי בית המשפט.', 4);

END $$;

-- ============================================================
-- Q22 — 2019-S-Q22 — chapter=civil_proc subtopic=proceedings
-- notes: needs_review=true | note: קיימת אי-בהירות בין הוראת תקנה 149(2)(א) לתקסד"א (הבקשה היא הערעור) לבין פרשנויות מסוימות המצביעות על מועד נפרד של 30 יום להגשת הערעור לאחר קבלת הרשות. התשובה הנכונה מתבססת על קיומו של מועד נפרד זה. | citation_review_required=true | subtopic_mapping_review: original='ערעור על החלטה אחרת של בית משפט לעניינים מינהליים' → mapped='proceedings'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q22 skipped: external_id % already exists', '2019-S-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
