  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q22', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'יהונתן מעוניין להעמיד "החלטה אחרת" של בית המשפט לעניינים מינהליים, שהתקבלה בעניינו, לביקורת של ערכאת הערעור. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 22}'::jsonb,
    'השאלה עוסקת במועדים ובהליכים להגשת בקשת רשות ערעור על ''החלטה אחרת'' של בית המשפט לעניינים מינהליים. חוק בתי משפט לעניינים מינהליים ותקנותיו קובעים הסדר ספציפי ושונה מההסדר הכללי בתקנות סדר הדין האזרחי, במטרה לייעל את ההליכים המינהליים ולמנוע סרבול.',
    'סעיף 12(א) לחוק בתי משפט לעניינים מינהליים, תש"ס-2000, קובע כי ''החלטה אחרת'' של בית משפט לעניינים מינהליים תהיה נתונה לערעור בפני בית המשפט העליון אם ניתנה רשות לכך (Law: חוק בתי משפט לענינים מינהליים, תש"ס-2000, סעיף 12). תקנה 33(ג) לתקנות בתי משפט לעניינים מינהליים (סדרי דין), תשס"א-2000, קובעת כי "המועד להגשת בקשת רשות לערער על החלטה אחרת של בית המשפט הוא שלושים ימים" (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, תקנה 33). באשר למועד הגשת הערעור עצמו לאחר קבלת הרשות, תקנה 34(א) לתקנות בתי משפט לעניינים מינהליים מפנה לפרק י"ז לחלק ב'' לתקנות סדר הדין האזרחי, בשינויים המחויבים (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, תקנה 34). תקנה 149(2)(א) לתקנות סדר הדין האזרחי, תשע"ט-2018, קובעת כי "אם ניתנה רשות ערעור, יראו את נימוקי הבקשה לרשות ערעור כנימוקי הערעור, ואין להגיש ערעור נפרד לאחר קבלת הרשות לערער" (Literature: נבו - המתמחה, סדר הדין האזרחי (2026), עמ'' 185). עם זאת, הפסיקה והספרות המשפטית מציינות כי במקרים מסוימים, אם ניתנה רשות לערער ובית המשפט לא החליט לדון בבקשה כאילו ניתנה רשות, יוגש הערעור תוך 30 יום (Literature: נבו - המתמחה, מערכת בתי המשפט (2026), עמ'' 65). יש לציין כי קיימת אי-בהירות מסוימת בין ההוראה הכללית בתקסד"א (הבקשה היא הערעור) לבין פרשנויות מסוימות המצביעות על מועד נפרד להגשת הערעור לאחר קבלת הרשות. לאור העובדה שהתשובה הנכונה מציינת 30 יום להגשת הערעור לאחר קבלת הרשות, נתייחס לכך כהלכה המחייבת לעניין זה.',
    'הסטודנט עלול לבלבל בין המועדים השונים להגשת ערעורים ובקשות רשות ערעור בהליכים מינהליים, או לטעות בהבנת היחס בין תקנות בתי משפט לעניינים מינהליים לבין תקנות סדר הדין האזרחי.',
    '["החלטה אחרת", "בקשת רשות ערעור", "מועדים להגשת ערעור", "בית משפט לעניינים מינהליים", "חוק בתי משפט לעניינים מינהליים", "תקנות סדר הדין האזרחי"]'::jsonb,
    '**וריאציה 1 — מועד לבקשת רשות ערעור:** מהו המועד להגשת בקשת רשות ערעור על ''החלטה אחרת'' של בית משפט לעניינים מינהליים? ← 30 ימים (תקנה 33(ג) לתקנות בתי משפט לעניינים מינהליים). **וריאציה 2 — מועד להגשת הערעור לאחר הרשות:** אם ניתנה רשות, מהו המועד להגשת הערעור? ← 30 ימים, או שהבקשה עצמה נחשבת לערעור (נבו - המתמחה, מערכת בתי המשפט (2026), עמ'' 65). **וריאציה 3 — סמכות הערעור:** לאיזו ערכאה מוגשת בקשת רשות הערעור? ← לבית המשפט העליון (סעיף 12(א) לחוק בתי משפט לעניינים מינהליים).',
    'בקשת רשות ערעור על ''החלטה אחרת'' של בית משפט לעניינים מינהליים ← תוך 30 יום ← לבית המשפט העליון. אם ניתנה רשות ← יוגש הערעור תוך 30 יום (תקנה 33(ג) לתקנות בתי משפט לעניינים מינהליים).',
    '["חוק בתי משפט לענינים מינהליים, תש\"ס-2000, סעיף 12", "תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, תקנה 33", "תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, תקנה 34", "נבו - המתמחה, מערכת בתי המשפט (2026) | ז - בג\"ץ ובית משפט לעניינים מינהליים", "נבו - המתמחה, סדר הדין האזרחי (2026) | יז - סעדים זמניים"]'::jsonb,
    'needs_review=true | note: קיימת אי-בהירות בין הוראת תקנה 149(2)(א) לתקסד"א (הבקשה היא הערעור) לבין פרשנויות מסוימות המצביעות על מועד נפרד של 30 יום להגשת הערעור לאחר קבלת הרשות. התשובה הנכונה מתבססת על קיומו של מועד נפרד זה. | citation_review_required=true | subtopic_mapping_review: original=''ערעור על החלטה אחרת של בית משפט לעניינים מינהליים'' → mapped=''proceedings''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עליו להגיש בקשה לרשות ערעור על "החלטה אחרת" בתוך 30 יום, ואם ניתנה רשות – יוגש הערעור בתוך 15 יום.', false, 'בחירה זו שגויה. המועד להגשת הערעור לאחר קבלת הרשות אינו 15 יום, אלא 30 יום, או שהבקשה עצמה נחשבת לערעור.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אי אפשר להגיש ערעור על "החלטה אחרת" בבית משפט לעניינים מינהליים אלא במסגרת ערעור על פסק הדין.', false, 'בחירה זו שגויה. סעיף 12 לחוק בתי משפט לעניינים מינהליים קובע רשימה סגורה של ''החלטות אחרות'' שניתן להגיש עליהן בקשת רשות ערעור.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עליו להגיש בקשה לרשות ערעור על "החלטה אחרת" בתוך 45 יום.', false, 'בחירה זו שגויה. המועד להגשת בקשת רשות ערעור על ''החלטה אחרת'' הוא 30 יום, ולא 45 יום.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עליו להגיש בקשה לרשות ערעור על "החלטה אחרת" בתוך 30 יום, ואם ניתנה רשות – יוגש הערעור בתוך 30 יום.', true, 'בחירה זו נכונה. תקנה 33(ג) לתקנות בתי משפט לעניינים מינהליים קובעת כי המועד להגשת בקשת רשות ערעור על ''החלטה אחרת'' הוא 30 ימים. אם ניתנה רשות, יוגש הערעור בתוך 30 ימים, או שהבקשה עצמה תיחשב לערעור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'מועדים לערעור בזכות על פסק דין מינהלי', 1, 'ראובן מעוניין לערער בזכות על פסק דין של בית המשפט לעניינים מינהליים בעתירה מינהלית. מהו המועד להגשת ערעור זה?',
    'השאלה עוסקת במועד להגשת ערעור בזכות על פסק דין של בית משפט לעניינים מינהליים. עם כניסתן לתוקף של תקנות סדר הדין האזרחי החדשות, עודכנו גם תקנות בתי משפט לעניינים מינהליים, וחשוב להכיר את המועדים המעודכנים.',
    'תקנה 33(א) לתקנות בתי משפט לעניינים מינהליים (סדרי דין), תשס"א-2000, קובעת כי "המועד להגשת ערעור בזכות על פסק דין של בית המשפט הוא שישים ימים" (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, תקנה 33). בעבר, המועד היה 45 ימים, אך עם כניסתן לתוקף של תקנות סדר הדין האזרחי, תשע"ט-2018, בוטלה ההאחדה שהייתה קיימת בעבר בין הליכים אזרחיים ומינהליים, והמועדים עודכנו (Verdict: עע"מ 7714/21 איילה ברייר סער נ'' ועדת הערר המחוזית לענייני תכנון ובניה - תל אביב יפו (15.2.2022)). על אף שתקנה 137(א) לתקנות סדר הדין האזרחי קובעת גם היא 60 ימים, הוראות תקנה 33 לתקנות בתי משפט לעניינים מינהליים גוברות בהליכים מינהליים (Verdict: ער"מ 1276/22 איילה ברייר סער נ'' ועדת הערר המחוזית לענייני תכנון ובניה- תל אביב יפו (9.3.2022)).',
    'הסטודנט עלול לטעות ולזכור את המועד הישן של 45 ימים, או לבלבל בין המועדים השונים להגשת ערעורים ובקשות רשות ערעור בהליכים מינהליים.',
    '["ערעור בזכות", "פסק דין מינהלי", "מועדים להגשת ערעור", "תקנות בתי משפט לעניינים מינהליים", "עתירה מינהלית"]'::jsonb,
    '**וריאציה 1 — ערעור בזכות על פסק דין מינהלי:** מהו המועד להגשת ערעור בזכות על פסק דין של בית משפט לעניינים מינהליים? ← 60 ימים (תקנה 33(א) לתקנות בתי משפט לעניינים מינהליים). **וריאציה 2 — הבחנה ממועדים קודמים:** האם המועד השתנה? ← כן, בעבר היה 45 ימים, אך עודכן ל-60 ימים עם כניסת תקנות סדר הדין האזרחי החדשות (עע"מ 7714/21 ברייר סער, רפרנס 1). **וריאציה 3 — תחולה:** האם תקנות סדר הדין האזרחי גוברות? ← לא, תקנות בתי משפט לעניינים מינהליים גוברות בהליכים מינהליים (ער"מ 1276/22 ברייר סער, רפרנס 4).',
    'ערעור בזכות על פסק דין מינהלי ← 60 ימים (תקנה 33(א) לתקנות בתי משפט לעניינים מינהליים).',
    '["תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, תקנה 33", "עע\"מ 7714/21 איילה ברייר סער נ'' ועדת הערר המחוזית לענייני תכנון ובניה - תל אביב יפו (15.2.2022)", "ער\"מ 1276/22 איילה ברייר סער נ'' ועדת הערר המחוזית לענייני תכנון ובניה- תל אביב יפו (9.3.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'הבחנה בין ''פסק דין'' ל''החלטה אחרת'' במינהלי', 2, 'כיצד מבחינים בין ''פסק דין'' ל''החלטה אחרת'' של בית המשפט לעניינים מינהליים לצורך קביעת דרך ההשגה (ערעור בזכות או ברשות)?',
    'השאלה עוסקת במבחנים לסיווג החלטה שיפוטית של בית המשפט לעניינים מינהליים כ''פסק דין'' או כ''החלטה אחרת''. סיווג זה קריטי לקביעת דרך ההשגה – ערעור בזכות או בקשת רשות ערעור – ומוסדר בסעיפים 11 ו-12 לחוק בתי משפט לעניינים מינהליים.',
    'סעיפים 11 ו-12 לחוק בתי משפט לעניינים מינהליים, תש"ס-2000, מעגנים את ההבחנה המוכרת בהליך האזרחי בין ''פסק דין'' ל''החלטה אחרת'' גם בהליכים מינהליים (Verdict: בר"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019), רפרנס 14). המבחן המרכזי לסיווג זה הוא מבחן ''סיום התיק'', שעל פיו נבחנת השאלה אם ההחלטה השיפוטית הביאה לסיום המחלוקת שבין הצדדים (Verdict: בר"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019), רפרנס 14). אם ההחלטה סיימה את התיק, היא תיחשב כ''פסק דין'' וניתן לערער עליה בזכות (למעט חריגים). אם היא לא סיימה את התיק, היא תיחשב כ''החלטה אחרת'', וניתן להגיש עליה בקשת רשות ערעור רק אם היא מנויה ברשימה הסגורה שבסעיף 12(ב) לחוק (Verdict: בר"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019), רפרנס 14).',
    'הסטודנט עלול לטעות ולסווג החלטה כ''פסק דין'' או ''החלטה אחרת'' על בסיס כותרתה, במקום על בסיס מהותה ומבחן ''סיום התיק''.',
    '["פסק דין", "החלטה אחרת", "מבחן סיום התיק", "ערעור בזכות", "בקשת רשות ערעור", "חוק בתי משפט לעניינים מינהליים"]'::jsonb,
    '**וריאציה 1 — מבחן הסיווג:** כיצד מסווגים החלטה כ''פסק דין'' או ''החלטה אחרת''? ← לפי מבחן ''סיום התיק'' – האם ההחלטה סיימה את המחלוקת (בר"מ 646/19 חבוש, רפרנס 14). **וריאציה 2 — השלכות הסיווג:** מה ההשלכה של סיווג כ''פסק דין''? ← ערעור בזכות (למעט חריגים) (סעיף 11 לחוק בתי משפט לעניינים מינהליים). **וריאציה 3 — השלכות סיווג כ''החלטה אחרת'':** מה ההשלכה של סיווג כ''החלטה אחרת''? ← בקשת רשות ערעור, רק אם מנויה ברשימה הסגורה שבסעיף 12(ב) לחוק (בר"מ 646/19 חבוש, רפרנס 14).',
    'סיווג החלטה מינהלית ← ''פסק דין'' (סיום תיק) ← ערעור בזכות. ''החלטה אחרת'' (לא סיום תיק) ← בקשת רשות ערעור (סעיפים 11, 12 לחוק בתי משפט לעניינים מינהליים).',
    '["חוק בתי משפט לענינים מינהליים, תש\"ס-2000, סעיף 11", "חוק בתי משפט לענינים מינהליים, תש\"ס-2000, סעיף 12", "בר\"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'רשימת ''החלטות אחרות'' סגורה או פתוחה', 3, 'האם רשימת ''החלטות אחרות'' המנויה בסעיף 12(ב) לחוק בתי משפט לעניינים מינהליים, שעליהן ניתן להגיש בקשת רשות ערעור, היא רשימה סגורה או פתוחה?',
    'השאלה בוחנת את אופייה של רשימת ''החלטות אחרות'' המנויה בסעיף 12(ב) לחוק בתי משפט לעניינים מינהליים. הבנת אופי הרשימה (סגורה או פתוחה) היא קריטית לקביעת קבילותה של בקשת רשות ערעור על החלטות ביניים בהליכים מינהליים.',
    'סעיף 12(ב) לחוק בתי משפט לעניינים מינהליים, תש"ס-2000, מונה רשימה סגורה של סוגי החלטות המוגדרות ''החלטה אחרת'' אשר עליהן ניתן להגיש בקשת רשות ערעור (Verdict: בר"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019), רפרנס 14). הכלל הוא כי בקשת רשות ערעור המכוונת כלפי ''החלטה אחרת'' של בית המשפט לעניינים מינהליים שאינה מנויה בסעיף 12(ב) דינה להידחות על הסף (Verdict: בר"מ 4717/14 גלילות מחזור פסולת בע"מ נ'' עיריית רמת השרון (4.11.2014), רפרנס 17; Verdict: בר"מ 5920239 לביא (ב.י.) הנדסה ובניין בע"מ נ'' מנהל הארנונה מועצה מקומית אזור (23.11.2022), רפרנס 25). מטרת הסעיף היא לפשט ולייעל את ההליכים בבית המשפט לעניינים מינהליים ולמנוע סרבול ומעבר בין ערכאות (Verdict: בר"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019), רפרנס 14). סעיף 12(ב)(4) מאפשר לשר המשפטים לקבוע עניינים נוספים בצו, באישור ועדת החוקה חוק ומשפט של הכנסת, אך ללא צו כזה, הרשימה היא סגורה (Law: חוק בתי משפט לענינים מינהליים, תש"ס-2000, סעיף 12).',
    'הסטודנט עלול לטעות ולחשוב שרשימת ''ההחלטות האחרות'' היא פתוחה, בדומה למבחנים כלליים למתן רשות ערעור בהליכים אזרחיים, מבלי להכיר את ההסדר הספציפי והמצמצם בחוק בתי משפט לעניינים מינהליים.',
    '["החלטה אחרת", "רשימה סגורה", "בקשת רשות ערעור", "חוק בתי משפט לעניינים מינהליים", "ייעול הליכים", "דחייה על הסף"]'::jsonb,
    '**וריאציה 1 — אופי הרשימה:** האם רשימת ''החלטות אחרות'' בסעיף 12(ב) לחוק בתי משפט לעניינים מינהליים היא סגורה? ← כן, רק על החלטות המנויות בה ניתן להגיש בקשת רשות ערעור (בר"מ 646/19 חבוש, רפרנס 14). **וריאציה 2 — תוצאה של אי-הכללה:** מה קורה לבקשת רשות ערעור על החלטה שאינה מנויה ברשימה? ← דינה להידחות על הסף (בר"מ 4717/14 גלילות מחזור פסולת, רפרנס 17). **וריאציה 3 — הרחבת הרשימה:** מי רשאי להרחיב את הרשימה? ← שר המשפטים בצו, באישור ועדת החוקה חוק ומשפט של הכנסת (סעיף 12(ב)(4) לחוק בתי משפט לעניינים מינהליים).',
    'רשימת ''החלטות אחרות'' (סעיף 12(ב) לחוק בתי משפט לעניינים מינהליים) ← סגורה ← בקשת רשות ערעור רק על המנויות בה.',
    '["חוק בתי משפט לענינים מינהליים, תש\"ס-2000, סעיף 12", "בר\"מ 646/19 חאמד מוחמד דיב חבוש נ'' מינהלת התיאום והקישור לרצועת עזה (14.5.2019)", "בר\"מ 4717/14 גלילות מחזור פסולת בע\"מ נ'' עיריית רמת השרון (4.11.2014)", "בר\"מ 5920239 לביא (ב.י.) הנדסה ובניין בע\"מ נ'' מנהל הארנונה מועצה מקומית אזור (23.11.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הגשת בקשת רשות ערעור בטעות כערעור בזכות', 4, 'ראובן הגיש ערעור בזכות על החלטה של בית המשפט לעניינים מינהליים, אך בדיעבד התברר כי היה עליו להגיש בקשת רשות ערעור. מהו סמכותו של בית המשפט במקרה כזה?',
    'השאלה עוסקת בסמכותו של בית המשפט לטפל בהליך ערעורי שהוגש בטעות בדרך שגויה (ערעור בזכות במקום בקשת רשות ערעור). תקנות סדר הדין האזרחי, החלות בשינויים המחויבים גם בהליכים מינהליים, מקנות לבית המשפט גמישות דיונית למנוע סילוק על הסף במקרים כאלה.',
    'תקנה 34(א) לתקנות בתי משפט לעניינים מינהליים (סדרי דין), תשס"א-2000, קובעת כי הוראות פרק י"ז לחלק ב'' לתקנות סדר הדין האזרחי יחולו על ערעור ועל בקשת רשות לערער לפי פרק זה, בשינויים המחויבים (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, תקנה 34). תקנה 149(4) לתקנות סדר הדין האזרחי, תשע"ט-2018, קובעת כי "הוגש ערעור בזכות במקום שבו היה על המערער להגיש בקשת רשות ערעור, רשאי בית המשפט לדון בערעור כבקשת רשות ערעור, ולתת הוראות לפי העניין" (Literature: נבו - המתמחה, סדר הדין האזרחי (2026), עמ'' 185). סמכות זו מאפשרת לבית המשפט למנוע סילוק על הסף של הליך שהוגש בטעות, תוך שמירה על עקרונות היעילות הדיונית וזכות הגישה לערכאות (Verdict: בר"מ 9749/07 מחמוד מובראק עואודה-עו"ד נ'' מועצה מקומית כפר כנא (7.1.2008), רפרנס 19; Verdict: בר"מ 9313/06 חלימה עיד נ'' שר הפנים (5.2.2007), רפרנס 21).',
    'הסטודנט עלול לטעות ולחשוב שכל הגשה שגויה של הליך ערעורי תוביל לסילוק על הסף, מבלי להכיר את הגמישות הדיונית המוקנית לבית המשפט במקרים של טעות בתום לב.',
    '["ערעור בזכות", "בקשת רשות ערעור", "טעות דיונית", "סמכות בית המשפט", "תקנות סדר הדין האזרחי", "תקנות בתי משפט לעניינים מינהליים"]'::jsonb,
    '**וריאציה 1 — טעות בהגשה:** מה קורה אם הוגש ערעור בזכות במקום בקשת רשות ערעור? ← בית המשפט רשאי לדון בו כבקשת רשות ערעור (תקנה 149(4) לתקסד"א). **וריאציה 2 — רציונל:** מדוע ניתנת סמכות זו לבית המשפט? ← למנוע סילוק על הסף של הליך שהוגש בטעות, ולשמור על יעילות דיונית וזכות הגישה לערכאות (בר"מ 9749/07 עואודה, רפרנס 19). **וריאציה 3 — תחולה:** האם סמכות זו חלה גם בהליכים מינהליים? ← כן, מכוח תקנה 34(א) לתקנות בתי משפט לעניינים מינהליים (בר"מ 9313/06 עיד, רפרנס 21).',
    'הגשת ערעור בזכות בטעות (במקום בקשת רשות ערעור) ← בית המשפט רשאי לדון בו כבקשת רשות ערעור (תקנה 149(4) לתקסד"א ותקנה 34(א) לתקנות בתי משפט לעניינים מינהליים).',
    '["תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, תקנה 34", "נבו - המתמחה, סדר הדין האזרחי (2026) | יז - סעדים זמניים", "בר\"מ 9749/07 מחמוד מובראק עואודה-עו\"ד נ'' מועצה מקומית כפר כנא (7.1.2008)", "בר\"מ 9313/06 חלימה עיד נ'' שר הפנים (5.2.2007)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', '30 ימים מיום המצאת פסק הדין.', false, 'בחירה זו שגויה. 30 ימים הוא המועד להגשת בקשת רשות ערעור על ''החלטה אחרת'', ולא לערעור בזכות על פסק דין בעתירה מינהלית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', '45 ימים מיום המצאת פסק הדין.', false, 'בחירה זו שגויה. 45 ימים היה המועד לערעור בזכות על פסק דין מינהלי לפי תקנה 33(א) הישנה, אך תקנה 33(א) הנוכחית קובעת 60 ימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', '60 ימים מיום המצאת פסק הדין.', true, 'בחירה זו נכונה. תקנה 33(א) לתקנות בתי משפט לעניינים מינהליים קובעת כי המועד להגשת ערעור בזכות על פסק דין של בית המשפט הוא 60 ימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בכל עת, אם נשתנו הנסיבות.', false, 'בחירה זו שגויה. מועד זה רלוונטי לבקשה לעיון חוזר או לערר על תנאי שחרור בערובה, ולא לערעור בזכות על פסק דין.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'ההבחנה נקבעת לפי כותרת ההחלטה שניתנה על ידי בית המשפט.', false, 'בחירה זו שגויה. כותרת ההחלטה אינה קובעת את סיווגה, אלא מהותה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'ההבחנה נקבעת לפי מבחן ''סיום התיק'' – האם ההחלטה סיימה את המחלוקת בין הצדדים.', true, 'בחירה זו נכונה. המבחן המרכזי הוא האם ההחלטה סיימה את המחלוקת בין הצדדים, או שהותירה עניין נוסף לדיון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'כל החלטה של בית המשפט לעניינים מינהליים היא ''פסק דין'', למעט החלטות ביניים מפורשות.', false, 'בחירה זו שגויה. ההבחנה אינה כה גורפת, וקיימת רשימה סגורה של ''החלטות אחרות'' בסעיף 12(ב) לחוק בתי משפט לעניינים מינהליים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'ההבחנה רלוונטית רק להליכים אזרחיים, ולא להליכים מינהליים.', false, 'בחירה זו שגויה. סעיפים 11 ו-12 לחוק בתי משפט לעניינים מינהליים מעגנים את ההבחנה בין ''פסק דין'' ל''החלטה אחרת'' גם בהליך המינהלי.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'הרשימה סגורה, ורק על החלטות המנויות בה ניתן להגיש בקשת רשות ערעור.', true, 'בחירה זו נכונה. סעיף 12(ב) לחוק בתי משפט לעניינים מינהליים קובע רשימה סגורה של ''החלטות אחרות'' שעליהן ניתן להגיש בקשת רשות ערעור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'הרשימה פתוחה, ובית המשפט רשאי להוסיף עליה החלטות נוספות לפי שיקול דעתו.', false, 'בחירה זו שגויה. הרשימה אינה פתוחה, ובית המשפט אינו רשאי להוסיף עליה החלטות. רק שר המשפטים רשאי לקבוע עניינים נוספים בצו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'הרשימה סגורה, אך ניתן להגיש בקשת רשות ערעור גם על החלטות שאינן מנויות בה, אם מתקיים ''עיוות דין חמור''.', false, 'בחירה זו שגויה. אף ש''עיוות דין חמור'' הוא שיקול למתן רשות ערעור ב''גלגול שלישי'', הוא אינו מאפשר להגיש בקשת רשות ערעור על החלטה שאינה מנויה ברשימה הסגורה של סעיף 12(ב).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'הרשימה פתוחה, אך רק אם שר המשפטים קבע עניינים נוספים בצו.', false, 'בחירה זו שגויה. אף ששר המשפטים רשאי לקבוע עניינים נוספים, הרשימה כפי שהיא מנויה בחוק היא סגורה, ורק בצו ניתן להרחיבה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט חייב למחוק את הערעור על הסף, שכן הוגש בהליך שגוי.', false, 'בחירה זו שגויה. בית המשפט אינו חייב למחוק את הערעור, אלא רשאי לדון בו כבקשת רשות ערעור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט רשאי לדון בערעור כבקשת רשות ערעור, ולתת הוראות לפי העניין.', true, 'בחירה זו נכונה. תקנה 149(4) לתקנות סדר הדין האזרחי (החלות בשינויים המחויבים) מאפשרת לבית המשפט לדון בערעור שהוגש בטעות כבקשת רשות ערעור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט רשאי להעביר את התיק לבית המשפט המחוזי לצורך דיון כבקשת רשות ערעור.', false, 'בחירה זו שגויה. בית המשפט העליון הוא הערכאה המוסמכת לדון בבקשות רשות ערעור על החלטות של בית משפט לעניינים מינהליים, ואין צורך להעביר לבית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט רשאי לדון בערעור כבקשת רשות ערעור, אך רק אם המשיב הסכים לכך.', false, 'בחירה זו שגויה. הסכמת המשיב אינה תנאי לסמכות בית המשפט לדון בערעור שהוגש בטעות כבקשת רשות ערעור.', 4);

END $$;

-- ============================================================
-- Q23 — 2019-S-Q23 — chapter=evidence subtopic=witness_competence
-- notes: needs_review=true | subtopic_mapping_review: original='עדות קטין במשפט פלילי' → mapped='witness_competence'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q23';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q23 skipped: external_id % already exists', '2019-S-Q23';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'witness_competence';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'witness_competence';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q23', 'f75683b1-e83a-47da-ba16-b35a95c536d0', v_subtopic_id,
    'במהלך העדות של מ'', קטין שנפגע בעבירה של סחר בבני אדם לפי סעיף 377א(א)(5) לחוק העונשין, התשל"ז-1977, הנכללת בתוספת לחוק לתיקון סדרי הדין (חקירת עדים), תשי"ח-1957, סבר בית המשפט כי מתן עדותו ברציפות מקשה עליו. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 23}'::jsonb,
    'השאלה עוסקת בסמכותו של בית המשפט להפסיק או לדחות עדות של קטין במשפט פלילי, כאשר מתן העדות ברציפות מקשה עליו. הוראות אלו, הקבועות בסעיף 2ה לחוק לתיקון סדרי הדין (חקירת עדים), נועדו להגן על הקטין מפני פגיעה נפשית נוספת במהלך ההליך המשפטי, תוך שמירה על עקרונות היעילות הדיונית וגילוי האמת.',
    'סעיף 2ה(ב) לחוק לתיקון סדרי הדין (חקירת עדים), תשי"ח-1957, קובע כי "בית המשפט, ביוזמתו או לבקשת הקטין או הורהו של הקטין, רשאי להפסיק או לדחות את שמיעת העדות, אם סבר שמתן העדות ברציפות מקשה על הקטין" (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ה). הוראה זו, שנוספה בתיקון מס'' 8 לחוק בשנת 2017, משקפת את הגישה המודרנית בדיני ראיות, המכירה בצורך להגן על קטינים נפגעי עבירה מפני טראומה משנית במהלך ההליך המשפטי. היא מאפשרת לבית המשפט גמישות בניהול העדות, תוך התחשבות בטובת הקטין ויכולתו למסור עדות אפקטיבית. הסעיף חל על קטין שהוא נפגע בעבירה המנויה בתוספת לחוק, כגון עבירת סחר בבני אדם, כפי שמתואר בשאלה (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ה).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט חייב להפסיק או לדחות את העדות, או לחילופין שאין לו סמכות לעשות זאת מיוזמתו, מבלי להבחין בלשון ''רשאי'' ובאפשרות ליוזמה שיפוטית.',
    '["עדות קטין", "הפסקת עדות", "דחיית עדות", "טובת הקטין", "חוק לתיקון סדרי הדין (חקירת עדים)", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — סמכות בית המשפט:** האם בית המשפט רשאי להפסיק עדות קטין שמקשה עליו? ← כן, ביוזמתו או לבקשת הקטין/הורהו (סעיף 2ה(ב) לחוק לתיקון סדרי הדין (חקירת עדים)).
 **וריאציה 2 — תנאי להפעלה:** מהו התנאי להפעלת סמכות זו? ← אם בית המשפט סבר שמתן העדות ברציפות מקשה על הקטין (סעיף 2ה(ב) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 3 — רציונל:** מדוע ניתנה סמכות זו? ← להקל על הילד בעת מסירת עדותו ולצמצם פגיעה נפשית (יניב ואקי, דיני ראיות כרך ב, עמ'' 31).',
    'בית המשפט רשאי להפסיק/לדחות עדות קטין (ביוזמתו/לבקשת הקטין/הורהו) אם סבר שמתן העדות ברציפות מקשה עליו (סעיף 2ה(ב) לחוק לתיקון סדרי הדין (חקירת עדים)).',
    '["חוק לתיקון סדרי הדין (חקירת עדים), תשי\"ח-1957, סעיף 2ה"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''עדות קטין במשפט פלילי'' → mapped=''witness_competence''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ביוזמתו או לבקשתו של הקטין או הורהו של הקטין, חייב בית המשפט להפסיק או לדחות את שמיעת העדות.', false, 'בחירה זו שגויה. בית המשפט אינו חייב להפסיק או לדחות את העדות, אלא רשאי לעשות כן, וזאת ביוזמתו או לבקשת הקטין או הורהו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ביוזמתו או לבקשתו של הקטין או הורהו של הקטין, רשאי בית המשפט להפסיק או לדחות את שמיעת העדות.', true, 'בחירה זו נכונה. סעיף 2ה(ב) לחוק לתיקון סדרי הדין (חקירת עדים) קובע כי בית המשפט רשאי, ביוזמתו או לבקשת הקטין או הורהו, להפסיק או לדחות את שמיעת העדות אם סבר שמתן העדות ברציפות מקשה על הקטין.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לבקשת הקטין או הורהו של הקטין, רשאי בית המשפט להפסיק או לדחות את שמיעת העדות; לא עשה כן – ינמק בית המשפט את החלטתו לשמיעה רצופה של העדות.', false, 'בחירה זו שגויה. חובת הנימוק חלה על אי-שמיעה רציפה של העדות (סעיף 2ה(א)), ולא על החלטה שלא להפסיק או לדחות עדות שמקשה על הקטין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לבקשת הקטין או הורהו של הקטין, חייב בית המשפט להפסיק או לדחות את שמיעת העדות.', false, 'בחירה זו שגויה. בית המשפט אינו חייב להפסיק או לדחות את העדות, אלא רשאי לעשות כן, וזאת ביוזמתו או לבקשת הקטין או הורהו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'חובת רציפות הדיון בעדות קטין', 1, 'בית המשפט החל בשמיעת עדותו של קטין שהוא נפגע בעבירה המנויה בתוספת לחוק לתיקון סדרי הדין (חקירת עדים), אך לא סיים את שמיעת העדות ביום שבו החלה. מה הדין לגבי המשך העדות?',
    'השאלה עוסקת בחובת רציפות הדיון בעדות קטין במשפט פלילי, כפי שנקבעה בסעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים). הוראה זו נועדה לצמצם את הפגיעה בקטין כתוצאה מהליך העדות, תוך איזון עם הצורך בגילוי האמת.',
    'סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים), תשי"ח-1957, קובע כי "החל בית המשפט בשמיעת עדותו של קטין שהוא נפגע בעבירה המנויה בתוספת או שעבירה המנויה בתוספת נעשתה בנוכחותו, יסיים בית המשפט ככל האפשר את שמיעת עדותו ביום שבו החלה; לא הסתיימה שמיעת עדותו של הקטין באותו יום, ישמע בית המשפט ככל האפשר את עדותו ברציפות, יום אחר יום, ככל שהדבר עולה בקנה אחד עם טובת הקטין; לא עשה כן בית המשפט, ינמק את החלטתו לשמיעה לא רצופה של העדות" (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ה). הוראה זו, שנוספה בתיקון מס'' 8 לחוק בשנת 2017, נועדה להקל על הילד בעת מסירת עדותו בבית המשפט ועל הסתגלותו הפסיכולוגית לאחריה, תוך צמצום שהותו בבית המשפט (Literature: יניב ואקי, דיני ראיות כרך ב (2020) | פרק 23 עד ילד או קטין, עמ'' 31).',
    'הסטודנט עלול לטעות ולחשוב שחובת הרציפות היא מוחלטת, או לחילופין שאין כלל חובת נימוק במקרה של סטייה ממנה.',
    '["עדות קטין", "רציפות דיון", "חובת נימוק", "טובת הקטין", "חוק לתיקון סדרי הדין (חקירת עדים)"]'::jsonb,
    '**וריאציה 1 — חובת סיום ביום אחד:** האם בית המשפט חייב לסיים עדות קטין ביום שהחלה? ← ככל האפשר (סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 2 — שמיעה רציפה:** אם לא הסתיימה ביום אחד, מה הדין? ← ישמע ברציפות, יום אחר יום, ככל שעולה בקנה אחד עם טובת הקטין (סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 3 — חובת נימוק:** אם לא שמע ברציפות, מה הדין? ← ינמק את החלטתו (סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים)).',
    'עדות קטין ← ככל האפשר ביום אחד, אחרת ברציפות יום אחר יום (לטובת הקטין) ← סטייה מחייבת נימוק (סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים)).',
    '["חוק לתיקון סדרי הדין (חקירת עדים), תשי\"ח-1957, סעיף 2ה", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 23 עד ילד או קטין"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תנאים להעדת קטין שלא בנוכחות הנאשם', 2, 'נאשם מואשם בעבירת מין בקטין, ומבקש שהקטין המתלונן יעיד בנוכחותו. מהם התנאים שבית המשפט יבחן כדי לאפשר עדות שלא בנוכחות הנאשם אלא בנוכחות סניגורו?',
    'השאלה עוסקת בתנאים למסירת עדות של מתלונן קטין בעבירת מין שלא בנוכחות הנאשם, כפי שקבועים בסעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים). הוראה זו נועדה לאזן בין זכות הנאשם להליך הוגן לבין הצורך להגן על הקטין מפני פגיעה נוספת במהלך העדות.',
    'סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים), תשי"ח-1957, קובע כי "במשפט פלילי בשל עבירת מין או בשל עבירת סחר בבני אדם, רשאי בית משפט להורות, בין מיוזמתו ובין לבקשת בעל דין או המתלונן, ואם היה המתלונן קטין גם לבקשת הורהו, לפני מתן העדות או במהלכה, שמתלונן ימסור את עדותו שלא בנוכחות הנאשם אלא בנוכחות סניגורו, אם נוכח שמסירת העדות בנוכחות הנאשם עלולה לפגוע במתלונן או לפגום בעדות" (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ב). הוראה זו מאפשרת לבית המשפט להגן על קטינים נפגעי עבירות מין מפני טראומה נוספת, תוך שמירה על זכויות הנאשם באמצעות נוכחות סניגורו (Literature: נבו - המתמחה, סדר הדין הפלילי (2026) | פרק יב - בירור האשמה, עמ'' 79).',
    'הסטודנט עלול לטעות ולחשוב שהעדת קטין שלא בנוכחות הנאשם היא אוטומטית בעבירות מין, או שהיא דורשת הסכמת הנאשם, מבלי להבין את שיקול הדעת של בית המשפט ואת התנאים הספציפיים בחוק.',
    '["עדות קטין", "עבירות מין", "עדות שלא בנוכחות נאשם", "פגיעה בקטין", "פגיעה בעדות", "חוק לתיקון סדרי הדין (חקירת עדים)"]'::jsonb,
    '**וריאציה 1 — עילות להעדת קטין שלא בנוכחות נאשם:** מתי בית המשפט רשאי להורות על עדות קטין שלא בנוכחות הנאשם בעבירת מין? ← אם נוכח שמסירת העדות בנוכחות הנאשם עלולה לפגוע במתלונן או לפגום בעדות (סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 2 — יוזמת ההחלטה:** מי רשאי ליזום בקשה כזו? ← בית המשפט מיוזמתו, בעל דין, המתלונן, או הורהו של הקטין (סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 3 — נוכחות סניגור:** מי יהיה נוכח במקום הנאשם? ← סניגורו של הנאשם (סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים)).',
    'עדות קטין בעבירת מין שלא בנוכחות נאשם ← אם פוגע בקטין/עדות ← בנוכחות סניגור (סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים)).',
    '["חוק לתיקון סדרי הדין (חקירת עדים), תשי\"ח-1957, סעיף 2ב", "נבו - המתמחה, סדר הדין הפלילי (2026) | פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'חובת הנמקה בעדות יחידה של קטין בעבירת סחר בבני אדם', 3, 'בית המשפט הרשיע נאשם על סמך עדות יחידה של קטין שהעיד שלא בנוכחות הנאשם בעבירה של סחר בבני אדם. האם נדרשת הנמקה מיוחדת להסתפקות בעדות זו?',
    'השאלה בוחנת את חובת ההנמקה הנדרשת כאשר בית המשפט מרשיע נאשם על סמך עדות יחידה של קטין שהעיד שלא בנוכחות הנאשם, ובפרט בעבירות סחר בבני אדם. קיימת מורכבות פרשנית ביחס לסעיפים 2ג(ב) ו-2ג(ג) לחוק לתיקון סדרי הדין (חקירת עדים), והפסיקה והספרות המשפטית נוטות להרחיב את חובת ההנמקה גם למקרים שאינם מנויים במפורש.',
    'סעיף 2ג(ב) לחוק לתיקון סדרי הדין (חקירת עדים), תשי"ח-1957, קובע כי "הרשיע בית משפט נאשם על סמך עדות יחידה של עד שהעיד שלא בנוכחות הנאשם כאמור בסעיף קטן (א), יפרט בהכרעת הדין מה הניע אותו להסתפק בעדות זו" (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ג). עם זאת, סעיף 2ג(ג) קובע כי הוראות סעיפים קטנים (א) ו-(ב) לא יחולו על עדות של קטין או חסר ישע שהוא מתלונן בעבירת מין או בעבירת סחר בבני אדם, ועל עדותו יחולו הוראות סעיף 2ב (Law: חוק לתיקון סדרי הדין (חקירת עדים), סעיף 2ג). סעיף 2ב אינו כולל הוראה מפורשת בדבר חובת הנמקה. אולם, הספרות המשפטית מציינת כי אף שאין דרישה מפורשת להנמקה במצב שבו בית המשפט מרשיע נאשם בעבירה של סחר בבני אדם על סמך עדות יחידה של קטין שהעיד שלא בנוכחות הנאשם (שכן סעיף 54א(ב) לפקודת הראיות אינו חל על עבירות אלו), מוטב להחיל את חובת ההנמקה גם במקרה זה, בהתחשב במאפייניהן המיניים של העבירות (Literature: יניב ואקי, דיני ראיות כרך ג (2021) | פרק 49 הנמקה, עמ'' 13; Literature: יניב ואקי, דיני ראיות כרך ג (2021) | פרק 44 עדות יחידה, עמ'' 20). דרישת ההנמקה נועדה לאזן בין הצורך בהגנה על הקטין לבין הפגיעה בזכותו של הנאשם להיות נוכח במשפטו ולהתעמת עם עדיו (Literature: יניב ואקי, דיני ראיות כרך ג (2021) | פרק 44 עדות יחידה, עמ'' 20).',
    'הסטודנט עלול לטעות ולפרש את סעיף 2ג(ג) באופן מילולי ומצמצם, ולהסיק שאין כלל חובת הנמקה בעבירות סחר בבני אדם, מבלי להתחשב בפרשנות המרחיבה של הפסיקה והספרות המשפטית.',
    '["עדות יחידה", "חובת הנמקה", "עדות שלא בנוכחות נאשם", "עבירת סחר בבני אדם", "חוק לתיקון סדרי הדין (חקירת עדים)", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — חובת הנמקה כללית:** האם הרשעה על סמך עדות יחידה שלא בנוכחות נאשם טעונה הנמקה? ← כן, בית המשפט יפרט מה הניע אותו להסתפק בעדות זו (סעיף 2ג(ב) לחוק לתיקון סדרי הדין (חקירת עדים)). **וריאציה 2 — סייג לעבירות מין וסחר:** האם סייג 2ג(ג) פוטר מחובת הנמקה בעבירת סחר בבני אדם? ← לשונית כן, אך הספרות ממליצה להחיל את חובת ההנמקה גם במקרים אלו (יניב ואקי, דיני ראיות כרך ג, עמ'' 13). **וריאציה 3 — רציונל ההנמקה:** מדוע נדרשת הנמקה? ← לאזן בין הצורך בהגנה על הקטין לבין הפגיעה בזכות הנאשם להתעמת עם עדיו (יניב ואקי, דיני ראיות כרך ג, עמ'' 20).',
    'הרשעה על עדות יחידה של קטין שלא בנוכחות נאשם ← טעונה הנמקה (סעיף 2ג(ב) לחוק לתיקון סדרי הדין (חקירת עדים)), גם בעבירות סחר בבני אדם, למרות הסייג בסעיף 2ג(ג).',
    '["חוק לתיקון סדרי הדין (חקירת עדים), תשי\"ח-1957, סעיף 2ג", "יניב ואקי, דיני ראיות כרך ג (2021) | פרק 49 הנמקה", "יניב ואקי, דיני ראיות כרך ג (2021) | פרק 44 עדות יחידה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות חוקר ילדים לאסור עדות קטין', 4, 'חוקר ילדים אסר על העדת קטין בבית המשפט בעבירה המנויה בתוספת לחוק לתיקון דיני הראיות (הגנת ילדים). מה מעמדה של החלטה זו, והאם בית המשפט רשאי להתערב בה?',
    'השאלה בוחנת את מעמדה של החלטת חוקר ילדים לאסור על העדת קטין בבית המשפט, ואת היקף הביקורת השיפוטית על החלטה זו. סעיף 2(א) לחוק לתיקון דיני הראיות (הגנת ילדים) מקנה לחוקר הילדים סמכות בלעדית, והפסיקה הדגישה את חסינותה של החלטה זו מביקורת שיפוטית, תוך איזון בין הגנה על הקטין לזכויות הנאשם.',
    'סעיף 2(א) לחוק לתיקון דיני הראיות (הגנת ילדים), תשט"ו-1955, קובע כי "אין מעידים ילד על עבירה המנויה בתוספת... אלא ברשות חוקר ילדים ובנוכחותו" (Law: חוק לתיקון דיני הראיות (הגנת ילדים), סעיף 2). הפסיקה קבעה לא אחת כי הסמכות הנתונה לחוקר הילדים בשאלת העדתו של קטין היא סמכות שאינה נתונה לביקורת שיפוטית. משעה שאסר חוקר ילדים על העדתו של קטין, החלטתו סופית ומחייבת את הצדדים ואת בית המשפט, שאינו יכול לעקוף את האיסור או לסטות ממנו (Verdict: ע"פ 1741/99 סעיד יוסף נ'' מדינת ישראל (7.9.1999), רפרנס 7; Verdict: תפ"ח (מחוזי תל אביב-יפו) 1149/05 מדינת ישראל נ'' פלוני (27.5.2008), רפרנס 21). מטרת הסדר זה היא לאזן בין האינטרס החברתי בהבאת עבריינים לדין לבין הצורך להגן על הילד מנזק נפשי נוסף כתוצאה מחשיפתו להליכים משפטיים (Verdict: תפ"ח (מחוזי תל אביב-יפו) 1037/02 מדינת ישראל נ'' שמואל בן חיים איגואל (3.12.2003), רפרנס 20).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט יכול להתערב בהחלטת חוקר הילדים, בדומה לביקורת שיפוטית על החלטות אחרות, מבלי להכיר את מעמדה המיוחד והבלעדי של סמכות חוקר הילדים בעניין זה.',
    '["חוקר ילדים", "העדת קטין", "סמכות בלעדית", "ביקורת שיפוטית", "חוק לתיקון דיני הראיות (הגנת ילדים)", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — סמכות חוקר הילדים:** מי מוסמך לאסור על העדת קטין בבית המשפט? ← חוקר הילדים בלבד (סעיף 2(א) לחוק לתיקון דיני הראיות (הגנת ילדים)). **וריאציה 2 — מעמד ההחלטה:** האם בית המשפט יכול להתערב בהחלטת חוקר הילדים? ← לא, החלטתו סופית ומחייבת (ע"פ 1741/99 סעיד יוסף, רפרנס 7). **וריאציה 3 — רציונל:** מדוע ניתנה סמכות כה רחבה לחוקר הילדים? ← לאזן בין הגנה על הקטין לבין גילוי האמת והליך הוגן (תפ"ח (מחוזי תל אביב-יפו) 1037/02 מדינת ישראל נ'' איגואל, רפרנס 20).',
    'חוקר ילדים ← סמכות בלעדית לאסור עדות קטין ← החלטה סופית ואינה נתונה לביקורת שיפוטית (סעיף 2(א) לחוק לתיקון דיני הראיות (הגנת ילדים)).',
    '["חוק לתיקון דיני הראיות (הגנת ילדים), תשט\"ו-1955, סעיף 2", "ע\"פ 1741/99 סעיד יוסף נ'' מדינת ישראל (7.9.1999)", "תפ\"ח (מחוזי תל אביב-יפו) 1149/05 מדינת ישראל נ'' פלוני (27.5.2008)", "תפ\"ח (מחוזי תל אביב-יפו) 1037/02 מדינת ישראל נ'' שמואל בן חיים איגואל (3.12.2003)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט חייב לסיים את שמיעת העדות ביום שהחלה, ואינו רשאי לדחותה.', false, 'בחירה זו שגויה. החוק קובע ''ככל האפשר'' ולא ''חייב'', ומאפשר שמיעה לא רציפה בכפוף לנימוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית המשפט ישמע את העדות ברציפות, יום אחר יום, ובלבד ששמיעה כזו עולה בקנה אחד עם טובת הקטין.', false, 'בחירה זו חלקית. היא מתארת את הכלל, אך מתעלמת מחובת הנימוק במקרה של סטייה ממנו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט ישמע את העדות ברציפות, יום אחר יום, ככל שהדבר עולה בקנה אחד עם טובת הקטין; לא עשה כן, ינמק את החלטתו לשמיעה לא רצופה של העדות.', true, 'בחירה זו נכונה. סעיף 2ה(א) לחוק לתיקון סדרי הדין (חקירת עדים) קובע את חובת הרציפות ואת חובת הנימוק במקרה של סטייה ממנה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט רשאי לדחות את שמיעת העדות ללא כל מגבלה.', false, 'בחירה זו שגויה. קיימת חובת רציפות, וסטייה ממנה מחייבת נימוק, מה שמהווה מגבלה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רק אם הקטין ביקש זאת במפורש, ובתנאי שהנאשם הסכים לכך.', false, 'בחירה זו שגויה. בית המשפט רשאי להורות על כך גם מיוזמתו, ואין צורך בהסכמת הנאשם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'אם בית המשפט נוכח שמסירת העדות בנוכחות הנאשם עלולה לפגוע במתלונן או לפגום בעדות.', true, 'בחירה זו נכונה. סעיף 2ב(א) לחוק לתיקון סדרי הדין (חקירת עדים) קובע כי זהו התנאי המרכזי למתן הוראה כזו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק אם חוקר הילדים המליץ על כך, ובתנאי שהעבירה היא עבירת מין חמורה במיוחד.', false, 'בחירה זו שגויה. חוקר ילדים אינו הגורם המוסמך להחליט על עדות שלא בנוכחות הנאשם לפי סעיף זה, והתנאי אינו חומרת העבירה אלא הפגיעה בקטין או בעדות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בכל מקרה של עבירת מין, בית המשפט יורה על עדות שלא בנוכחות הנאשם.', false, 'בחירה זו שגויה. בית המשפט ''רשאי'' ולא ''חייב'' להורות על כך, ורק אם נוכח בקיומה של פגיעה בקטין או בעדות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, נדרשת הנמקה מיוחדת, שכן הרשעה על סמך עדות יחידה שניתנה שלא בנוכחות הנאשם טעונה הנמקה, גם אם החוק אינו קובע זאת במפורש לעבירה זו.', true, 'בחירה זו נכונה. אף שלשון סעיף 2ג(ג) לחוק לתיקון סדרי הדין (חקירת עדים) פוטרת לכאורה מחובת הנמקה בעבירות סחר בבני אדם, הפסיקה והספרות המשפטית מצביעות על כך שחובת הנמקה כללית חלה, או שראוי שתחול, במקרים אלו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, אין דרישה מפורשת להנמקה במקרה זה, שכן עבירת סחר בבני אדם אינה עבירת מין שעליה חל סעיף 54א(ב) לפקודת הראיות.', false, 'בחירה זו שגויה. אף שלשון החוק אינה קובעת זאת במפורש, הפרשנות המקובלת היא שחובת הנמקה כללית חלה, או שראוי שתחול, במקרים אלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, נדרשת הנמקה מיוחדת, אך רק אם הקטין הוא חסר ישע בנוסף להיותו קטין.', false, 'בחירה זו שגויה. חובת ההנמקה אינה תלויה בשאלה אם הקטין הוא גם חסר ישע, אלא בסוג העבירה ובאופן גביית העדות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אין דרישה מפורשת להנמקה, ובית המשפט רשאי להרשיע על סמך עדות זו ללא כל הסבר נוסף.', false, 'בחירה זו שגויה. גישה זו אינה עולה בקנה אחד עם עקרונות ההליך ההוגן והצורך בפירוט שיקולי בית המשפט בהרשעה על סמך עדות יחידה שניתנה שלא בנוכחות הנאשם.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'החלטת חוקר הילדים היא המלצה בלבד, ובית המשפט רשאי להורות על העדת הקטין גם בניגוד להמלצה זו.', false, 'בחירה זו שגויה. החלטת חוקר הילדים אינה המלצה בלבד, אלא בעלת מעמד מחייב, ובית המשפט אינו רשאי להתערב בה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'החלטת חוקר הילדים היא סופית ומחייבת, ובית המשפט אינו רשאי להתערב בשיקול דעתו ולא יכול לעקוף את האיסור.', true, 'בחירה זו נכונה. הפסיקה קבעה כי סמכות חוקר הילדים לאסור על העדת קטין היא בלעדית ואינה נתונה לביקורת שיפוטית, ובית המשפט אינו יכול לעקוף את האיסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט רשאי להורות לחוקר הילדים לשקול שנית את החלטתו, אך אינו רשאי לעקוף את האיסור.', false, 'בחירה זו שגויה. אף שבעבר עלתה אפשרות זו, ההלכה הפסוקה קובעת כי בית המשפט אינו רשאי להתערב בשיקול דעתו של חוקר הילדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'החלטת חוקר הילדים מחייבת רק אם הקטין טרם מלאו לו 14 שנים, ולאחר מכן בית המשפט רשאי להורות על העדתו.', false, 'בחירה זו שגויה. החלטת חוקר הילדים מתייחסת לעדות שנגבתה בהיותו ילד, והיא קובעת את קבילותה כראיה, ללא קשר לגילו בעת המשפט.', 4);

END $$;

-- ============================================================
-- Q24 — 2019-S-Q24 — chapter=civil_proc subtopic=proceedings
-- notes: needs_review=true | subtopic_mapping_review: original='דיון נוסף על החלטת דן יחיד בבית המשפט העליון' → mapped='proceedings'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q24';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q24 skipped: external_id % already exists', '2019-S-Q24';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q24', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'עודד הגיש עתירה לבית המשפט העליון לגילוי ראיה שהוצאה לגביה תעודת חיסיון לטובת המדינה חתומה על ידי ראש הממשלה, ובה הבעת דעתו כי מסירתה עלולה לפגוע ביחסי החוץ של המדינה. שופט בית המשפט העליון דחה את העתירה וקבע כי הצורך לגלות את הראיה לשם עשיית צדק נסוג במקרה זה מפני העניין שיש לא לגלותה. עודד סבור שמפאת חשיבותה של ההחלטה שנפסקה בעניין, יש מקום לדיון נוסף, והוא מעוניין לפנות בבקשה לקיומו של דיון נוסף בעניין. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 24}'::jsonb,
    'השאלה עוסקת במנגנון ה''דיון הנוסף'' בבית המשפט העליון, ובפרט במגבלה המהותית לפיה לא ניתן להגיש בקשה לדיון נוסף על החלטה שניתנה על ידי שופט יחיד (''דן יחיד''). הליך הדיון הנוסף הוא חריג לעקרון סופיות הדיון, והוא שמור למקרים נדירים של הלכות משפטיות שנקבעו בהרכב של שלושה שופטים לפחות.',
    'סעיף 18 לחוק-יסוד: השפיטה וסעיף 30(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובעים במפורש כי דיון נוסף יתקיים בעניין שפסק בו בית המשפט העליון "בשלושה" (Law: חוק-יסוד: השפיטה, סעיף 18; Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 30). הפסיקה חזרה וקבעה לא אחת כי אין מקום לקיום דיון נוסף בהחלטות שניתנו על ידי דן יחיד (בש"א 1018/12 אמיר וייס נ'' תמיר מולקנדוף (24.4.2012); דנ"פ 4774/14 שמעון ארזון נ'' מדינת ישראל משטרת ישראל (31.12.2014); בג"ץ 5121/13 פלוני נ'' שרת המשפטים (11.8.2013)). הרציונל הוא שלשון החוק ברורה, והליך הדיון הנוסף, בהיותו חריג לעקרון סופיות הדיון, שמור למקרים בהם נפסקה הלכה משפטית בהרכב משמעותי, ולא להחלטות של שופט יחיד (Literature: נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר). במקרה של עודד, החלטת שופט בית המשפט העליון בדן יחיד אינה עומדת בתנאי סף זה, ולכן לא ניתן להגיש עליה בקשה לדיון נוסף, גם אם הוא סבור שההחלטה חשובה או קשה.',
    'הסטודנט עלול לבלבל בין המועדים השונים להגשת ערעורים ובקשות רשות ערעור בהליכים מינהליים, או לטעות בהבנת היחס בין תקנות בתי משפט לעניינים מינהליים לבין תקנות סדר הדין האזרחי.',
    '["דיון נוסף", "דן יחיד", "חוק בתי המשפט", "חוק-יסוד: השפיטה", "סופיות הדיון", "הלכה פסוקה"]'::jsonb,
    '**וריאציה 1 — דן יחיד ודיון נוסף:** האם ניתן לקיים דיון נוסף על החלטת דן יחיד בבית המשפט העליון? ← לא, החוק והפסיקה קובעים שלא ניתן (סעיף 30(א) לחוק בתי המשפט; בש"א 1018/12). **וריאציה 2 — הרכב מינימלי לדיון נוסף:** מהו הרכב השופטים המינימלי שפסק דינו יכול לשמש בסיס לדיון נוסף? ← שלושה שופטים (סעיף 18 לחוק-יסוד: השפיטה). **וריאציה 3 — רציונל:** מדוע אין דיון נוסף על דן יחיד? ← לשון החוק ברורה, והליך הדיון הנוסף שמור למקרים חריגים של הלכות שנקבעו בהרכב (דנ"פ 4774/14 ארזון).',
    'דיון נוסף אינו אפשרי על החלטת דן יחיד בבית המשפט העליון, אלא רק על החלטה שניתנה בהרכב של שלושה שופטים לפחות (סעיף 30(א) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 30", "חוק-יסוד: השפיטה, סעיף 18", "בש\"א 1018/12 אמיר וייס נ'' תמיר מולקנדוף (24.4.2012)", "דנ\"פ 4774/14 שמעון ארזון נ'' מדינת ישראל משטרת ישראל (31.12.2014)", "בג\"ץ 5121/13 פלוני נ'' שרת המשפטים (11.8.2013)", "נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''דיון נוסף על החלטת דן יחיד בבית המשפט העליון'' → mapped=''proceedings''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על החלטת בית המשפט העליון בדן יחיד אין אפשרות להגיש בקשה לדיון נוסף.', true, 'בחירה זו נכונה. סעיף 30(א) לחוק בתי המשפט קובע כי דיון נוסף יתקיים בעניין שפסק בו בית המשפט העליון בשלושה, והפסיקה קבעה כי אין דיון נוסף על החלטת דן יחיד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בנסיבות המתוארות הסמכות להורות על דיון נוסף נתונה לשופט בית המשפט העליון שנתן את ההחלטה בלבד.', false, 'בחירה זו שגויה. הסמכות להורות על דיון נוסף נתונה לנשיא בית המשפט העליון או לשופט אחר שקבע לכך, ולא לשופט שנתן את ההחלטה המקורית, ובכל מקרה לא על החלטת דן יחיד.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות המתוארות הסמכות להורות על דיון נוסף נתונה לשופט בית המשפט העליון שנתן את ההחלטה, לנשיא בית המשפט העליון או לשופט אחר של בית המשפט העליון שקבע לכך הנשיא.', false, 'בחירה זו שגויה. אף שהיא מפרטת את הגורמים המוסמכים לדון בבקשה לדיון נוסף, היא מתעלמת מהכלל הבסיסי שאין דיון נוסף על החלטת דן יחיד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות המתוארות אפשר להיענות לבקשה אם ההלכה שנפסקה בבית המשפט העליון עומדת בסתירה להלכה קודמת של בית המשפט העליון, או שמפאת חשיבותה, קשיותה או חידושה של הלכה שנפסקה בעניין, יש, לדעתם, מקום לדיון נוסף.', false, 'בחירה זו שגויה. היא מפרטת את העילות לקיום דיון נוסף, אך מתעלמת מהתנאי המוקדם והקריטי שדיון נוסף אינו אפשרי על החלטת דן יחיד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'תנאים לדיון נוסף על פסק דין בהרכב מורחב', 1, 'פסק דין של בית המשפט העליון ניתן בהרכב של חמישה שופטים. אחד הצדדים סבור כי מפאת חשיבותה וחידושה של ההלכה שנפסקה, יש מקום לדיון נוסף. מה הדין?',
    'שאלה זו בוחנת את האפשרות לקיים דיון נוסף על פסק דין של בית המשפט העליון שניתן בהרכב מורחב (מעל שלושה שופטים). אף שלשון החוק מתייחסת להרכב של שלושה, הפסיקה הרחיבה את האפשרות במקרים חריגים ביותר, תוך הדגשת נדירות ההליך.',
    'סעיף 30(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי דיון נוסף יתקיים בעניין שפסק בו בית המשפט העליון "בשלושה" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 30). עם זאת, הפסיקה קבעה כי במקרים חריגים שבחריגים ניתן לקיים דיון נוסף גם על פסק דין שניתן בהרכב מורחב, למשל של חמישה שופטים (בש"א 1481/96 נחמני נ'' נחמני, פ"ד מט(5) 598 (1996); דנ"א 62866-05-25 פלונית נ'' אלמונית (22.6.2025)). הרציונל הוא שהצורך בבחינה נוספת פוחת ככל שיותר שופטים דנו והכריעו בסוגיה, ולכן הליך זה שמור למקרים נדירים במיוחד (דנ"א 62866-05-25 פלונית נ'' אלמונית (22.6.2025)). העילות להגשת בקשה לדיון נוסף במקרים אלו הן אלו המנויות בסעיף 30(ב) לחוק בתי המשפט: סתירה להלכה קודמת, או חשיבות, קשיות או חידוש של ההלכה שנפסקה (Literature: חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק עשרים - דיון נוסף).',
    'הסטודנט עלול לטעות ולפרש את לשון סעיף 30(א) לחוק בתי המשפט באופן דווקני, ולהסיק שאין אפשרות לדיון נוסף על פסק דין שניתן בהרכב גדול משלושה שופטים, מבלי להכיר את הפרשנות המרחיבה של הפסיקה במקרים חריגים.',
    '["דיון נוסף", "הרכב מורחב", "חריגים שבחריגים", "חוק בתי המשפט", "עילות דיון נוסף"]'::jsonb,
    '**וריאציה 1 — הרכב גדול משלושה:** האם ניתן לקיים דיון נוסף על פסק דין שניתן בהרכב של חמישה שופטים? ← כן, במקרים חריגים שבחריגים (בש"א 1481/96 נחמני; דנ"א 62866-05-25 פלונית). **וריאציה 2 — רציונל ההגבלה:** מדוע קשה יותר לקבל דיון נוסף על הרכב מורחב? ← הצורך בבחינה נוספת פוחת ככל שיותר שופטים דנו והכריעו בסוגיה (דנ"א 62866-05-25 פלונית). **וריאציה 3 — סמכות הנשיא:** מי מחליט על דיון נוסף במקרים אלו? ← נשיא בית המשפט העליון או שופט אחר שקבע לכך (סעיף 30(ב) לחוק בתי המשפט).',
    'דיון נוסף על פסק דין בהרכב מורחב (מעל שלושה) אפשרי רק במקרים חריגים שבחריגים, בשיקול דעת הנשיא (בש"א 1481/96 נחמני; דנ"א 62866-05-25 פלונית).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 30", "בש\"א 1481/96 נחמני נ'' נחמני, פ\"ד מט(5) 598 (1996)", "דנ\"א 62866-05-25 פלונית נ'' אלמונית (22.6.2025)", "דנ\"פ 941/16 רבין מאיר נ'' מדינת ישראל (11.2.2016)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק עשרים - דיון נוסף"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'עילות להגשת בקשה לדיון נוסף', 2, 'מהן העילות המרכזיות שבגינן רשאי נשיא בית המשפט העליון להיענות לבקשה לדיון נוסף, לאחר שפסק הדין המקורי ניתן בהרכב של שלושה שופטים?',
    'שאלה זו מתמקדת בעילות המהותיות להגשת בקשה לדיון נוסף בבית המשפט העליון, כפי שנקבעו בסעיף 30(ב) לחוק בתי המשפט. הבנת עילות אלו חיונית להבחנה בין דיון נוסף לבין ערעור רגיל.',
    'סעיף 30(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע שתי עילות חלופיות שבגינן נשיא בית המשפט העליון (או שופט אחר שקבע לכך) רשאי להיענות לבקשה לדיון נוסף: (1) ההלכה שנפסקה בבית המשפט העליון עומדת בסתירה להלכה קודמת של בית המשפט העליון; או (2) שמפאת חשיבותה, קשיותה או חידושה של הלכה שנפסקה בעניין, יש, לדעתם, מקום לדיון נוסף (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 30). הפסיקה מדגישה כי דיון נוסף אינו מהווה ערעור נוסף, ואינו נועד לבחון מחדש את תוצאות הערעור או את הממצאים העובדתיים, אלא את ההלכה המשפטית שנפסקה (דנג"ץ 917/97 חוזה עמוס נ'' בית המשפט העליון (4.6.1997); דנג"ץ 1988/08 התנועה לאיכות השלטון בישראל נ'' היועץ המשפטי לממשלה (24.3.2008)). גם כאשר מתקיימות העילות, ההחלטה אם לקיים דיון נוסף נתונה לשיקול דעת (דנ"פ 4067/21 מדינת ישראל נ'' הרב אליהו בקשי דורון (המנוח) (12.9.2021)).',
    'הסטודנט עלול לבלבל בין עילות הדיון הנוסף לבין עילות ערעור רגילות, ולחשוב שדיון נוסף נועד לתקן טעויות ביישום הדין או בממצאים עובדתיים.',
    '["עילות דיון נוסף", "הלכה סותרת", "חשיבות הלכה", "קשיות הלכה", "חידוש הלכה", "סעיף 30(ב) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — עילות חלופיות:** מהן העילות להגשת בקשה לדיון נוסף? ← הלכה סותרת הלכה קודמת, או חשיבות/קשיות/חידוש ההלכה (סעיף 30(ב) לחוק בתי המשפט). **וריאציה 2 — מהות הדיון הנוסף:** האם דיון נוסף הוא ערעור נוסף? ← לא, הוא בוחן את ההלכה המשפטית ולא את תוצאות הערעור (דנג"ץ 917/97 חוזה עמוס). **וריאציה 3 — שיקול דעת:** האם התקיימות העילות מחייבת קיום דיון נוסף? ← לא, נתון לשיקול דעת הנשיא/שופט הדן בבקשה (דנ"פ 4067/21 מדינת ישראל נ'' הרב אליהו בקשי דורון).',
    'עילות לדיון נוסף: סתירה להלכה קודמת, או חשיבות/קשיות/חידוש ההלכה, בשיקול דעת הנשיא (סעיף 30(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 30", "דנג\"ץ 917/97 חוזה עמוס נ'' בית המשפט העליון (4.6.1997)", "דנ\"פ 3080/14 דני חורי נ'' מדינת ישראל (19.11.2014)", "דנג\"ץ 8537/18 פלונית נ'' בית הדין הרבני הגדול בירושלים (24.6.2021)", "דנ\"פ 4067/21 מדינת ישראל נ'' הרב אליהו בקשי דורון (המנוח) (12.9.2021)", "דנג\"ץ 1988/08 התנועה לאיכות השלטון בישראל נ'' היועץ המשפטי לממשלה (24.3.2008)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'דיון נוסף ביוזמת המותב', 3, 'בית המשפט העליון, בהרכב של שלושה שופטים, נתן פסק דין בעניין עקרוני. השופטים סבורים כי יש מקום לדיון נוסף בהלכה שנפסקה. מהו ההליך הנכון לקיום דיון נוסף במקרה זה?',
    'שאלה זו עוסקת באחת משתי הדרכים ליזום דיון נוסף בבית המשפט העליון: ביוזמת המותב שנתן את פסק הדין. היא מדגישה את ההבחנה בין סמכות המותב לבין בקשה של בעל דין, ואת היקף שיקול הדעת של המותב במקרה זה.',
    'סעיף 30(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "ענין שפסק בו בית המשפט העליון בשלושה, רשאי הוא להחליט, עם מתן פסק דינו, שבית המשפט העליון ידון בו דיון נוסף בחמישה או יותר" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 30). זוהי הדרך הראשונה והישירה ליזום דיון נוסף, והיא נתונה לשיקול דעתו הבלעדי של המותב שדן בעניין. בניגוד לבקשה לדיון נוסף המוגשת על ידי בעל דין (לפי סעיף 30(ב)), סמכות המותב לפי סעיף 30(א) אינה מוגבלת לעילות המפורטות בסעיף קטן (ב) (Literature: חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק עשרים - דיון נוסף). אם המותב החליט על דיון נוסף, על בעל דין המעוניין בכך להגיש הודעה לרשם תוך 7 ימים, אחרת ההחלטה תבוטל (Literature: נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר).',
    'הסטודנט עלול לבלבל בין שתי הדרכים ליזום דיון נוסף, ולחשוב שגם כאשר המותב יוזם את הדיון, עליו לעמוד בעילות המפורטות בסעיף 30(ב).',
    '["דיון נוסף", "יוזמת המותב", "סעיף 30(א) לחוק בתי המשפט", "שיקול דעת שיפוטי", "הודעה לרשם"]'::jsonb,
    '**וריאציה 1 — יוזמת המותב:** האם המותב שנתן את פסק הדין יכול ליזום דיון נוסף? ← כן, עם מתן פסק דינו (סעיף 30(א) לחוק בתי המשפט). **וריאציה 2 — תנאים ליוזמת המותב:** האם יוזמת המותב מוגבלת לעילות ספציפיות? ← לא, שיקול דעתו אינו מוגבל לעילות שבסעיף 30(ב) (חמי בן-נון, טל חבקין, הערעור האזרחי). **וריאציה 3 — הליך לאחר החלטת המותב:** מה נדרש מבעל דין לאחר החלטת המותב? ← להגיש הודעה לרשם תוך 7 ימים (נבו - המתמחה, מערכת בתי המשפט).',
    'דיון נוסף ביוזמת המותב ← המותב רשאי להחליט על כך עם מתן פסק הדין (סעיף 30(א) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 30", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק עשרים - דיון נוסף", "נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'עיון חוזר על החלטת דן יחיד בעניין מעצר', 4, 'חשוד שוחרר ממעצר על ידי שופט בית המשפט העליון בדן יחיד, אך הוא סבור שתנאי השחרור שהוטלו עליו אינם סבירים. מהו ההליך המתאים לשינוי תנאים אלו?',
    'שאלה זו בוחנת את ההליך המתאים לשינוי תנאי שחרור ממעצר שנקבעו על ידי שופט בית המשפט העליון בדן יחיד. היא מדגישה את ההבחנה בין דיון נוסף (שאינו רלוונטי במקרה זה) לבין הליך של עיון חוזר, המאפשר בחינה מחודשת של ההחלטה לאור שינוי נסיבות.',
    'סעיף 73ב(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "ניתנה החלטה בעניין מעצר לפי סעיפים 73(ד) או 73א(ו), רשאים הצדדים - (1) לפנות לבית המשפט, ואם צו המעצר ניתן מאת רשם - לרשם, בבקשה לעיון חוזר בהחלטה שנתן, לרבות בהחלטה לפי פסקה זו, אם נתגלו עובדות חדשות או נשתנו נסיבות והדבר עשוי לשנות את ההחלטה הקודמת" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 73ב). הליך זה מאפשר גמישות בבחינת החלטות מעצר, שהן בעלות השלכה ישירה על חירות הפרט, ומאפשר התאמה לתנאים משתנים. בניגוד לדיון נוסף, שאינו אפשרי על החלטת דן יחיד, הליך העיון החוזר מיועד בדיוק למקרים כאלה, ומוגש לאותה ערכאה שנתנה את ההחלטה המקורית (Literature: נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר).',
    'הסטודנט עלול לבלבל בין הליכי ערעור, דיון נוסף ועיון חוזר, ולא להבין איזה הליך מתאים לכל סוג של החלטה וערכאה.',
    '["עיון חוזר", "החלטת דן יחיד", "מעצר", "שינוי נסיבות", "חוק בתי המשפט", "סעדים דיוניים"]'::jsonb,
    '**וריאציה 1 — הליך לשינוי תנאי מעצר:** מהו ההליך לשינוי תנאי שחרור ממעצר שנקבעו על ידי שופט? ← בקשה לעיון חוזר (סעיף 73ב(1) לחוק בתי המשפט). **וריאציה 2 — עילות לעיון חוזר:** מתי ניתן להגיש בקשה לעיון חוזר? ← אם נתגלו עובדות חדשות או נשתנו נסיבות (סעיף 73ב(1) לחוק בתי המשפט). **וריאציה 3 — ערכאה:** לאיזו ערכאה מוגשת הבקשה לעיון חוזר? ← לבית המשפט שנתן את ההחלטה המקורית (סעיף 73ב(1) לחוק בתי המשפט).',
    'שינוי תנאי שחרור ממעצר שנקבעו על ידי שופט ← בקשה לעיון חוזר ← אם נתגלו עובדות חדשות או נשתנו נסיבות (סעיף 73ב(1) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 73ב", "נבו - המתמחה, מערכת בתי המשפט (2026) | פרק ג - דיון נוסף ומשפט חוזר"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא ניתן לקיים דיון נוסף, שכן סעיף 30(א) לחוק בתי המשפט מתייחס רק לפסק דין שניתן בשלושה שופטים.', false, 'בחירה זו שגויה. אף שלשון החוק מתייחסת לשלושה שופטים, הפסיקה הרחיבה את האפשרות לדיון נוסף גם על הרכב מורחב במקרים חריגים שבחריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'ניתן לקיים דיון נוסף במקרים חריגים שבחריגים, בשיקול דעת נשיא בית המשפט העליון, אם מתקיימות העילות שבסעיף 30(ב) לחוק בתי המשפט.', true, 'בחירה זו נכונה. הפסיקה קבעה כי במקרים נדירים ויוצאי דופן ניתן לקיים דיון נוסף גם על פסק דין שניתן בהרכב מורחב, בכפוף לעילות הקבועות בחוק ולשיקול דעת הנשיא.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ניתן לקיים דיון נוסף רק אם ההלכה שנפסקה עומדת בסתירה להלכה קודמת של בית המשפט העליון.', false, 'בחירה זו שגויה. סתירה להלכה קודמת היא רק אחת העילות, וגם חשיבות, קשיות או חידוש יכולים להצדיק דיון נוסף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'האפשרות לדיון נוסף קיימת רק אם המותב המקורי של חמישה שופטים החליט על כך עם מתן פסק הדין.', false, 'בחירה זו שגויה. זוהי אחת הדרכים ליזום דיון נוסף, אך לא היחידה. ניתן גם להגיש בקשה לנשיא בית המשפט העליון.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רק אם ההלכה שנפסקה עומדת בסתירה להלכה קודמת של בית המשפט העליון.', false, 'בחירה זו שגויה. סתירה להלכה קודמת היא רק אחת משתי העילות החלופיות הקבועות בחוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'אם ההלכה שנפסקה עומדת בסתירה להלכה קודמת של בית המשפט העליון, או שמפאת חשיבותה, קשיותה או חידושה של הלכה שנפסקה בעניין, יש מקום לדיון נוסף.', true, 'בחירה זו נכונה. סעיף 30(ב) לחוק בתי המשפט מפרט שתי עילות חלופיות אלו להגשת בקשה לדיון נוסף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'אם בית המשפט טעה בקביעת ממצאים עובדתיים או ביישום הלכה ידועה על נסיבות המקרה.', false, 'בחירה זו שגויה. דיון נוסף אינו ערעור נוסף ואינו נועד לבחון מחדש ממצאים עובדתיים או יישום הלכה, אלא את ההלכה המשפטית עצמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'אם התוצאה האופרטיבית של פסק הדין אינה צודקת, לדעת המבקש.', false, 'בחירה זו שגויה. דיון נוסף אינו עוסק בתוצאה האופרטיבית כשלעצמה, אלא בהלכה המשפטית שנפסקה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'על הצדדים להגיש בקשה לדיון נוסף לנשיא בית המשפט העליון, ורק הוא רשאי להורות על כך.', false, 'בחירה זו שגויה. זוהי הדרך השנייה ליזום דיון נוסף, אך במקרה זה המותב עצמו מעוניין בכך, ויש לו סמכות ישירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט העליון רשאי להחליט, עם מתן פסק דינו, על קיומו של דיון נוסף בחמישה שופטים או יותר.', true, 'בחירה זו נכונה. סעיף 30(א) לחוק בתי המשפט מאפשר למותב שדן בעניין להחליט על דיון נוסף מיוזמתו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט העליון רשאי להחליט על דיון נוסף, אך רק אם ההלכה שנפסקה עומדת בסתירה להלכה קודמת.', false, 'בחירה זו שגויה. כאשר המותב יוזם את הדיון הנוסף, שיקול דעתו אינו מוגבל לעילות המנויות בסעיף 30(ב).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'החלטה על דיון נוסף ביוזמת המותב אינה אפשרית, שכן היא פוגעת בסופיות הדיון.', false, 'בחירה זו שגויה. החוק מאפשר במפורש למותב ליזום דיון נוסף, מתוך הכרה בחשיבות פיתוח ההלכה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הגשת בקשה לדיון נוסף לנשיא בית המשפט העליון.', false, 'בחירה זו שגויה. לא ניתן להגיש בקשה לדיון נוסף על החלטת דן יחיד, ובפרט לא בענייני מעצר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הגשת ערר לבית המשפט העליון בהרכב של שלושה שופטים.', false, 'בחירה זו שגויה. ערר על החלטת דן יחיד בעניין מעצר נדון בפני שופט אחד בבית המשפט שלערעור, ולא בהרכב של שלושה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הגשת בקשה לעיון חוזר לבית המשפט העליון, אם נתגלו עובדות חדשות או נשתנו נסיבות.', true, 'בחירה זו נכונה. סעיף 73ב(1) לחוק בתי המשפט מאפשר הגשת בקשה לעיון חוזר על החלטת מעצר שניתנה על ידי שופט, אם נתגלו עובדות חדשות או נשתנו נסיבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הגשת בקשה לשינוי תנאים לשופט בית המשפט העליון שנתן את ההחלטה, ללא צורך בשינוי נסיבות.', false, 'בחירה זו שגויה. בקשה לעיון חוזר דורשת שינוי נסיבות או גילוי עובדות חדשות, ואינה מוגשת ללא תנאי.', 4);

END $$;

-- ============================================================
-- Q25 — 2019-S-Q25 — chapter=evidence subtopic=admissibility
-- notes: needs_review=true | subtopic_mapping_review: original='חיסיון לטובת הציבור וסמכות ממונה חסיונות' → mapped='admissibility'
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q25 skipped: external_id % already exists', '2019-S-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'admissibility';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'admissibility';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q25', 'f75683b1-e83a-47da-ba16-b35a95c536d0', v_subtopic_id,
    'בהליך פלילי בבית משפט השלום בחדרה הגיש הנאשם לשופט הדן בדבר עתירה לגילוי ראיה שהוצאה לגביה תעודת חיסיון חתומה על ידי קצין משטרה בכיר בדימוס בדרגת תת-ניצב ששירת באגף החקירות והמודיעין במשטרת ישראל, המשמש ממונה על חסיונות מטעם השר לביטחון הפנים, ובה הבעת דעתו כי מסירתה עלולה לפגוע בעניין ציבורי חשוב. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 25}'::jsonb,
    'השאלה עוסקת בסמכות להוציא תעודת חיסיון לטובת הציבור ובערכאה המוסמכת לדון בעתירה לגילוי ראיה חסויה. סעיף 45 לפקודת הראיות מסדיר את החיסיון הזה, ומאפשר לשר לביטחון הפנים לאצול את סמכותו לממונים על חסיונות בעלי כישורים ספציפיים, וקובע כי העתירה תוגש לבית המשפט הדן בדבר.',
    'סעיף 45(א) לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע כי אין אדם חייב למסור ראיה ובית המשפט לא יקבל אותה אם שר הביע דעתו, בתעודה חתומה בידו, כי מסירתה עלולה לפגוע בעניין ציבורי חשוב, אלא אם מצא בית המשפט הדן בדבר, על-פי עתירת בעל דין המבקש גילוי הראיה, כי הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 45). סעיף 45(ד)(1) לפקודה מאפשר לשר לביטחון הפנים לאצול את סמכותו לפי סעיף זה ל''ממונה על חסיונות'', ומונה רשימה סגורה של בעלי תפקידים שיכולים לשמש כממונה על חסיונות, ובהם "קצין משטרה בכיר בדימוס בדרגת תת-ניצב ומעלה ששירת באגף החקירות והמודיעין במשטרת ישראל" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 45). לפיכך, תעודת החיסיון שהוצאה על ידי גורם כזה היא בעלת תוקף. העתירה לגילוי ראיה חסויה תוגש ל"בית המשפט הדן בדבר", כלומר לבית המשפט שדן בתיק העיקרי (Verdict: ת"פ (שלום קריות) 28826-04-14 מדינת ישראל נ'' שרון פיסחוב (1.2.2015), Reference 1, 3).',
    'הסטודנט עלול לטעות בזיהוי הגורמים המוסמכים להוציא תעודת חיסיון, או לבלבל בין הערכאה המוסמכת לדון בעתירה לגילוי חיסיון לטובת הציבור (סעיף 45) לבין חיסיון לטובת המדינה (סעיף 44), הנדון בבית המשפט העליון.',
    '["חיסיון לטובת הציבור", "ממונה על חסיונות", "אצילת סמכויות", "פקודת הראיות", "עתירה לגילוי ראיה", "בית המשפט הדן בדבר"]'::jsonb,
    '**וריאציה 1 — סמכות ממונה חסיונות:** האם קצין משטרה בכיר בדימוס בדרגת תת-ניצב יכול לחתום על תעודת חיסיון לטובת הציבור? ← כן, אם מונה כממונה על חסיונות על ידי השר לביטחון הפנים (סעיף 45(ד)(1)(ב) לפקודת הראיות). **וריאציה 2 — תוקף התעודה:** האם לתעודה כזו יש תוקף? ← כן, היא תקפה כתעודת חיסיון לטובת הציבור (סעיף 45(ד)(1)(ב) לפקודת הראיות). **וריאציה 3 — ערכאה מוסמכת:** לאיזה בית משפט תוגש העתירה לגילוי ראיה חסויה לפי סעיף 45? ← לבית המשפט הדן בדבר (סעיף 45(א) לפקודת הראיות).',
    'תעודת חיסיון לטובת הציבור חתומה על ידי ממונה חסיונות (קצין משטרה בכיר בדימוס) תקפה, והעתירה לגילויה תוגש לבית המשפט הדן בדבר (סעיף 45 לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 45", "ת\"פ (שלום קריות) 28826-04-14 מדינת ישראל נ'' שרון פיסחוב (1.2.2015)"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''חיסיון לטובת הציבור וסמכות ממונה חסיונות'' → mapped=''admissibility''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בנסיבות המתוארות לתעודה אין תוקף כתעודת חיסיון לטובת הציבור. עתירת בעל דין המבקש גילוי הראיה כי הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה תוגש לבית המשפט העליון.', false, 'בחירה זו שגויה. לתעודת החיסיון יש תוקף, שכן קצין משטרה בכיר בדימוס בדרגת תת-ניצב ומעלה ששירת באגף החקירות והמודיעין מוסמך לשמש כממונה על חסיונות. כמו כן, העתירה תוגש לבית המשפט הדן בדבר, ולא לבית המשפט העליון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בנסיבות המתוארות לתעודה אין תוקף כתעודת חיסיון לטובת הציבור. עתירת בעל דין המבקש גילוי הראיה כי הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה תוגש לבית המשפט הדן בדבר.', false, 'בחירה זו שגויה. לתעודת החיסיון יש תוקף, שכן קצין משטרה בכיר בדימוס בדרגת תת-ניצב ומעלה ששירת באגף החקירות והמודיעין מוסמך לשמש כממונה על חסיונות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות המתוארות לתעודה תוקף כתעודת חיסיון לטובת הציבור. עתירת בעל דין המבקש גילוי הראיה כי הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה תוגש לבית המשפט העליון.', false, 'בחירה זו שגויה. אף שלתעודת החיסיון יש תוקף, העתירה תוגש לבית המשפט הדן בדבר, ולא לבית המשפט העליון (שכן מדובר בחיסיון לפי סעיף 45 לפקודת הראיות, ולא 44).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות המתוארות לתעודה תוקף כתעודת חיסיון לטובת הציבור. עתירת בעל דין המבקש גילוי הראיה כי הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה תוגש לבית המשפט הדן בדבר.', true, 'בחירה זו נכונה. סעיף 45(ד)(1)(ב) לפקודת הראיות מאפשר לשר לביטחון הפנים לאצול את סמכותו לקצין משטרה בכיר בדימוס בדרגת תת-ניצב ומעלה. סעיף 45(א) קובע כי העתירה תוגש ל''בית המשפט הדן בדבר''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'מבחני האיזון להסרת חיסיון לטובת הציבור', 1, 'נאשם הגיש עתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות, בטענה שהראיה חיונית להגנתו. מהו המבחן שבית המשפט יפעיל כדי להכריע בעתירה?',
    'השאלה עוסקת במבחנים שנקבעו בפסיקה להסרת חיסיון לטובת הציבור לפי סעיף 45 לפקודת הראיות. הפסיקה מבחינה בין ראיה ''חיונית'' להגנת הנאשם לבין ראיה ''מועילה'' להגנתו, וקובעת מבחני איזון שונים לכל אחת מהקטגוריות.',
    'סעיף 45(א) לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע כי בית המשפט יורה על גילוי ראיה חסויה אם מצא כי "הצורך לגלותה לשם עשיית צדק עדיף מן העניין שיש לא לגלותה, ובהליך פלילי כי הראיה עשויה להועיל להגנת הנאשם ומידת התועלת שבה להגנה עולה על העניין שיש לא לגלותה, או שהיא חיונית להגנת הנאשם" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 45). הפסיקה מבחינה בין ראיה ''חיונית'' ל''מועילה''. ראיה חיונית היא ראיה מרכזית ובעלת חשיבות מהותית לקביעת החפות או האשמה, וכאשר ראיה כזו קיימת, אין לבצע איזון בין השיקולים המתחרים, אלא יש להסיר את החיסיון (Verdict: ת"פ (שלום אש'') 5832-06-19 מדינת ישראל נ'' אושרי גנח (10.11.2019), Reference 4, 5, 6). לעומת זאת, ראיה מועילה אינה כה קריטית, אך היא בעלת ''משמעות מסוימת'', ובמקרה זה המפתח הוא איזון בין התועלת להגנה לבין העניין הציבורי שלא לגלותה (Verdict: ת"פ (שלום אש'') 5832-06-19 מדינת ישראל נ'' אושרי גנח (10.11.2019), Reference 4, 5, 6). המבחן לחיוניותה של ראיה הוא אם יש בה ''פוטנציאל מזכה'', קרי, אם הראיה עשויה לעורר ספק סביר באשמתו של הנאשם (Verdict: ת"פ (שלום אש'') 1715-07-15 מכלוף מיכאל מלכה נ'' מדינת ישראל (2.12.2015), Reference 70).',
    'הסטודנט עלול לטעות וליישם את מבחן האיזון הכללי גם במקרים בהם הראיה חיונית להגנת הנאשם, מבלי להבחין בין ראיה ''חיונית'' ל''מועילה''.',
    '["חיסיון לטובת הציבור", "ראיה חיונית", "ראיה מועילה", "מבחן איזון אינטרסים", "פוטנציאל מזכה", "סעיף 45 לפקודת הראיות"]'::jsonb,
    '**וריאציה 1 — ראיה חיונית:** אם הראיה חיונית להגנת הנאשם, מה הדין? ← החיסיון יוסר ללא איזון (סעיף 45(א) לפקודת הראיות; ת"פ (שלום אש'') 5832-06-19 גנח, רפרנס 4). **וריאציה 2 — ראיה מועילה:** אם הראיה מועילה להגנת הנאשם, מה הדין? ← יאזן בין התועלת להגנה לבין האינטרס הציבורי (סעיף 45(א) לפקודת הראיות; ת"פ (שלום אש'') 5832-06-19 גנח, רפרנס 4). **וריאציה 3 — מהי ראיה חיונית?** מהו המבחן לראיה חיונית? ← ראיה בעלת ''פוטנציאל מזכה'' או עשויה לעורר ספק סביר באשמת הנאשם (ת"פ (שלום אש'') 1715-07-15 מלכה, רפרנס 70).',
    'הסרת חיסיון לפי סעיף 45 לפקודת הראיות: ראיה חיונית ← הסרה ללא איזון; ראיה מועילה ← איזון בין תועלת להגנה לאינטרס ציבורי.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 45", "ת\"פ (שלום קריות) 28826-04-14 מדינת ישראל נ'' שרון פיסחוב (1.2.2015)", "ת\"פ (שלום אש'') 5832-06-19 מדינת ישראל נ'' אושרי גנח (10.11.2019)", "ת\"פ (שלום אש'') 26971-01-18 מדינת ישראל נ'' ישראל אוחנה (17.5.2018)", "ת\"פ (שלום ק\"ש) 2145-08-19 אליסף מיוסט נ'' מדינת ישראל (15.2.2020)", "ת\"פ (שלום ראשל\"צ) 56763-08-23 מדינת ישראל נ'' מחמד עגל (16.9.2024)", "ת\"פ (שלום רמ'') 44188-01-24 מדינת ישראל נ'' יאמין מנסור (29.9.2024)", "ת\"פ (שלום אש'') 39129-05-20 מדינת ישראל נ'' גאורגי חננשוילי (21.10.2020)", "ת\"פ (שלום אש'') 54848-09-20 מדינת ישראל נ'' דניאל בן פורת (2.12.2020)", "ע\"ח (שלום ב\"ש) 2227068 שלמה הרי עזרן נ'' מדינת ישראל (4.3.2012)", "ת\"פ (שלום אש'') 1715-07-15 מכלוף מיכאל מלכה נ'' מדינת ישראל (2.12.2015)", "ע\"ח (שלום חד'') 1992854 אולג קובליוב נ'' משטרת ישראל תביעות- שלוחת חדרה (1.11.2011)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'סמכות בית המשפט לדון בעתירה לגילוי ראיה חסויה', 2, 'נאשם הגיש עתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות לבית המשפט השלום הדן בעניינו. האם בית המשפט רשאי להעביר את הדיון בעתירה לשופט אחר?',
    'השאלה עוסקת בסמכותו של בית המשפט לדון בעתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות, ובפרט באפשרות להעביר את הדיון בעתירה לשופט אחר. הוראה זו נועדה לאפשר גמישות דיונית תוך שמירה על מראית פני הצדק.',
    'סעיף 45(א) לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע כי העתירה לגילוי ראיה חסויה תוגש ל"בית המשפט הדן בדבר" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 45). הכלל הוא שהעתירה נדונה בפני המותב הדן בתיק העיקרי (Verdict: ת"פ (שלום רמ'') 13353-11-09 מדינת ישראל נ'' רבאח זבידה (21.1.2010), Reference 67). עם זאת, סעיף 45(ג) לפקודת הראיות קובע כי "בית המשפט רשאי להעביר את הדיון בעתירה לשופט יחיד שאינו דן בתיק, ואם היה בית המשפט הרכב - לשופט יחיד שהוא אחד משופטי ההרכב או שאינו דן בתיק" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 45). הוראה זו מאפשרת לבית המשפט גמישות, ומאזנת בין הצורך ביעילות דיונית לבין החשש מפגיעה במראית פני הצדק כאשר השופט הדן בתיק נחשף לחומר חסוי (Verdict: ת"פ (שלום עכו) 3864-11-17 מדינת ישראל נ'' בלאל בריק (4.12.2018), Reference 66).',
    'הסטודנט עלול לטעות ולחשוב שהדיון בעתירה חייב להתקיים תמיד בפני השופט הדן בתיק העיקרי, מבלי להכיר את סמכות ההעברה לשופט אחר הקבועה בסעיף 45(ג).',
    '["חיסיון לטובת הציבור", "עתירה לגילוי ראיה", "בית המשפט הדן בדבר", "העברת דיון", "סעיף 45 לפקודת הראיות", "מראית פני הצדק"]'::jsonb,
    '**וריאציה 1 — סמכות לדון בעתירה:** מי דן בעתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות? ← בית המשפט הדן בדבר (סעיף 45(א) לפקודת הראיות). **וריאציה 2 — העברה לשופט אחר:** האם בית המשפט רשאי להעביר את הדיון בעתירה לשופט אחר? ← כן, לשופט יחיד שאינו דן בתיק, או לשופט יחיד מההרכב או שאינו דן בתיק אם מדובר בהרכב (סעיף 45(ג) לפקודת הראיות). **וריאציה 3 — רציונל ההעברה:** מדוע קיימת אפשרות להעברה? ← לאפשר גמישות דיונית ולשמור על מראית פני הצדק (ת"פ (שלום עכו) 3864-11-17 בריק, רפרנס 66).',
    'עתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות נדונה בפני בית המשפט הדן בדבר, אך רשאי להעבירה לשופט אחר (סעיף 45(א) ו-45(ג) לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 45", "ת\"פ (שלום רמ'') 13353-11-09 מדינת ישראל נ'' רבאח זבידה (21.1.2010)", "ת\"פ (שלום עכו) 3864-11-17 מדינת ישראל נ'' בלאל בריק (4.12.2018)", "ת\"פ (שלום פ\"ת) 11662-04-22 אסיל אבו סיאם נ'' מדינת ישראל (19.6.2023)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'חיסיון על זהות מוסר מידע מודיעיני', 3, 'נאשם בעבירת סמים מבקש לחשוף את זהות מוסר המידע המודיעיני שהוביל למעצרו, בטענה שמוסר המידע הוא בעל עניין המעוניין להפלילו. מהם השיקולים המרכזיים שבית המשפט יבחן בעתירה זו?',
    'השאלה עוסקת בחיסיון על זהות מוסר מידע מודיעיני, שהוא אחד האינטרסים הציבוריים החשובים ביותר המוגנים בסעיף 45 לפקודת הראיות. בית המשפט נדרש לאזן בין אינטרסים אלו לבין זכות הנאשם להליך הוגן וגילוי האמת.',
    'חיסיון על זהות מוסר מידע מודיעיני הוא אינטרס ציבורי חשוב המוגן מכוח סעיף 45 לפקודת הראיות. גילוי זהות המקור עלול לסכן את שלומם של בני אדם, לפגוע בשיתוף הפעולה של הציבור עם המשטרה ולחשוף שיטות עבודה ודרכי פעולה של המשטרה, ובכך לפגוע ביעילות פעולותיה (Verdict: ת"פ (שלום קריות) 28826-04-14 מדינת ישראל נ'' שרון פיסחוב (1.2.2015), Reference 3; Verdict: ת"פ (שלום אש'') 5832-06-19 מדינת ישראל נ'' אושרי גנח (10.11.2019), Reference 6). כאשר נאשם עותר לגילוי זהות המקור, בית המשפט נדרש לאזן בין אינטרסים ציבוריים אלו לבין הצורך לגלות את הראיה לשם עשיית צדק, ובפרט אם הראיה חיונית או מועילה להגנת הנאשם (Verdict: ת"פ (שלום ק"ש) 2145-08-19 אליסף מיוסט נ'' מדינת ישראל (15.2.2020), Reference 16; Verdict: ת"פ (שלום רמ'') 44188-01-24 מדינת ישראל נ'' יאמין מנסור (29.9.2024), Reference 32). הפסיקה מדגישה כי חשיפת זהותם של מוסרי מידע עלולה לסכן את שלומם ולעתים אף את חייהם, ולכן האיזון חייב להיעשות בזהירות רבה (Verdict: ע"ח (שלום נצ'') 4104843 שאדי אבו אסעד נ'' מדינת ישראל (22.5.2017), Reference 40).',
    'הסטודנט עלול לזלזל בחשיבות האינטרס הציבורי שבשמירה על זהות מקורות מודיעיניים, או לחילופין לחשוב שחיסיון זה הוא מוחלט ואינו ניתן להסרה.',
    '["חיסיון לטובת הציבור", "זהות מוסר מידע", "אינטרס ציבורי", "סיכון חיי אדם", "שיתוף פעולה עם המשטרה", "שיטות עבודה משטרתיות"]'::jsonb,
    '**וריאציה 1 — אינטרסים ציבוריים מוגנים:** אילו אינטרסים ציבוריים מגנים על זהות מוסר מידע מודיעיני? ← מניעת סיכון חיי אדם, שמירה על שיתוף פעולה עם המשטרה, מניעת חשיפת שיטות עבודה (ת"פ (שלום קריות) 28826-04-14 פיסחוב, רפרנס 3). **וריאציה 2 — מבחן האיזון:** כיצד בית המשפט מכריע בעתירה לגילוי זהות המקור? ← מאזן בין הצורך בגילוי לשם עשיית צדק (חיוניות/תועלת להגנה) לבין האינטרסים הציבוריים המוגנים (ת"פ (שלום ק"ש) 2145-08-19 מיוסט, רפרנס 16). **וריאציה 3 — חשיבות האינטרס הציבורי:** עד כמה חשוב האינטרס הציבורי בחיסיון זהות המקור? ← משמעותי, חשיפת זהותם עלולה לסכן את שלומם ולעתים אף את חייהם (ע"ח (שלום נצ'') 4104843 אבו אסעד, רפרנס 40).',
    'חיסיון על זהות מוסר מידע מודיעיני ← אינטרס ציבורי חשוב (סיכון, שיתוף פעולה, שיטות) ← איזון מול חיוניות/תועלת להגנה (סעיף 45 לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 45", "ת\"פ (שלום קריות) 28826-04-14 מדינת ישראל נ'' שרון פיסחוב (1.2.2015)", "ת\"פ (שלום אש'') 5832-06-19 מדינת ישראל נ'' אושרי גנח (10.11.2019)", "ת\"פ (שלום אש'') 26971-01-18 מדינת ישראל נ'' ישראל אוחנה (17.5.2018)", "ת\"פ (שלום ק\"ש) 2145-08-19 אליסף מיוסט נ'' מדינת ישראל (15.2.2020)", "ת\"פ (שלום רמ'') 44188-01-24 מדינת ישראל נ'' יאמין מנסור (29.9.2024)", "ת\"פ (שלום י-ם) 36754-10-24 מדינת ישראל נ'' אוראל דוגה (18.7.2025)", "ע\"ח (שלום חד'') 5602487 אדיר אהרן נ'' מדינת ישראל (28.10.2021)", "ת\"פ (שלום ראשל\"צ) 13012-12-24 מדינת ישראל נ'' אחמד גאבר (16.1.2026)", "ת\"פ (שלום ב\"ש) 48173-12-13 שאקר אלרייאט נ'' מדינת ישראל (24.8.2014)", "ע\"ח (שלום נצ'') 4104843 שאדי אבו אסעד נ'' מדינת ישראל (22.5.2017)", "ת\"פ (שלום כ\"ס) 1330-09 מ.י. פרקליטות מחוז המרכז נ'' מורסי מסראווה בן עלי (27.7.2010)", "ע\"ח (שלום אש'') 30932-12-10 אריאל אמנו נ'' מדינת ישראל (26.4.2011)", "ת\"פ (שלום אש'') 5284314 מדינת ישראל נ'' דניאל בן פורת (2.12.2020)", "ע\"ח (שלום חד'') 5903786 בת אל יטרס נ'' מדינת ישראל (5.6.2019)", "ת\"פ (שלום חי'') 62333-10-21 מדינת ישראל נ'' צבי גנדלמן (1.11.2022)", "ת\"פ (שלום רח'') 52716-09-16 מדינת ישראל משטרת ישראל נ'' מהדי אבו אלקיעאן (3.4.2017)", "ת\"פ (שלום י-ם) 5853121 מדינת ישראל נ'' ולרי פרחומנקו (11.8.2022)", "ת\"פ (שלום חיפה) 407828 מדינת ישראל נ'' בראנסה סוהיל (17.12.2003)", "ת\"פ (שלום ראשל\"צ) 3599874 משטרת ישראל תביעות- שלוחת ראשון לציון נ'' מעתצם חדיראת (2.2.2016)", "ת\"פ (שלום אש'') 3555242 מכלוף מיכאל מלכה נ'' מדינת ישראל (2.12.2015)", "ע\"ח (שלום ב\"ש) 28118-04-13 פלוני נ'' מדינת ישראל (20.5.2013)", "ע\"ח (שלום ב\"ש) 4005763 הלאל אלטורי נ'' מדינת ישראל פמ\"ד (7.3.2017)", "ע\"ח (שלום חד'') 5132622 ראמי גנאים נ'' מדינת ישראל (13.6.2020)", "ת\"פ (שלום חד'') 4486468 מדינת ישראל נ'' בני קבדה (6.6.2018)", "ב\"ש (שלום נצרת) 466970 מחמוד מוחמד בן ראוף נ'' משטרת נצרת - תביעות מרחב עמקים (28.2.2005)", "בע\"ח (שלום ב\"ש) 5283324 סארי אלקואעין נ'' מדינת ישראל (1.12.2020)", "ת\"פ (שלום חי'') 3800400 מדינה ישראל- משטרת ישראל נ'' יצחק לוזון (12.9.2016)", "ת\"פ (שלום ת\"א) 3251024 יוסף לוי נ'' מדינת ישראל (6.10.2014)", "ע\"ח (שלום חד'') 4828539 בת אל יטרס נ'' מדינת ישראל (5.6.2019)", "ע\"ח (שלום חד'') 4972381 ציון אברמוב נ'' מדינת ישראל (7.12.2019)", "ת\"פ (שלום כ\"ס) 3130000 פאכר עיראקי נ'' מדינת ישראל (29.5.2014)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'השפעת אי-חוקיות השגת ראיה חסויה', 4, 'ההגנה טוענת כי ראיה חסויה, שעליה הוצאה תעודת חיסיון לפי סעיף 45 לפקודת הראיות, הושגה על ידי המשטרה באופן בלתי חוקי (למשל, באמצעות תוכנת רוגלה בחריגה מצו שיפוטי). האם טענה זו משפיעה על הדיון בעתירה לגילוי הראיה החסויה?',
    'השאלה בוחנת את השפעת טענת אי-חוקיות בהשגת ראיה חסויה על הדיון בעתירה לגילוי ראיה לפי סעיף 45 לפקודת הראיות. הפסיקה קובעת כי שאלת אי-החוקיות נבחנת במסגרת העתירה לגילוי, וכי תעודת חיסיון אוסרת את מסירת החומר לכולי עלמא, גם אם יש חובה בדין אחר למסור אותו.',
    'סעיף 45 לפקודת הראיות קובע כי אם ניתנה תעודת חיסיון ביחס לדבר שיש לו פוטנציאל לשמש ככלי להוכחת נתון כלשהו במסגרת הליך משפטי, תעודה זו אוסרת הן על מסירת הדבר החסוי לכולי עלמא, אף אם יש חובה בכל דין אחר למסור אותו, והן על הגשתו כראיה לבית המשפט (Verdict: ת"פ (שלום ת"א) 39087-05-22 מדינת ישראל נ'' גלעד פלג לורברבום (16.2.2024), Reference 24). הדרך היחידה לאפשר את מסירת החומר היא בהחלטת בית המשפט במסגרת דיון בעתירה לגילוי ראיה חסויה (Verdict: ת"פ (שלום ת"א) 39087-05-22 מדינת ישראל נ'' גלעד פלג לורברבום (16.2.2024), Reference 24). אף אם קיים ויכוח בשאלת עצם תחולת תעודת החיסיון על חומר מסוים, או אם חומר המחשב המוחזק הושג לכאורה ללא סמכות חוקית, המסגרת שבה ייבחנו שאלת אי-החוקיות ומשמעותה תהיה המסגרת של עתירה לגילוי ראיה חסויה (Verdict: ת"פ (שלום ת"א) 39087-05-22 מדינת ישראל נ'' גלעד פלג לורברבום (16.2.2024), Reference 24). לא ניתן לבצע ''תקיפה עקיפה'' של תעודת החיסיון במתווה דיוני אחר (Verdict: ת"פ (שלום ת"א) 39087-05-22 מדינת ישראל נ'' גלעד פלג לורברבום (16.2.2024), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שטענת אי-חוקיות השגת ראיה יכולה להוביל לפסילת תעודת החיסיון אוטומטית, או שהיא נדונה בהליך נפרד, מבלי להבין שהיא חלק ממבחן האיזון בעתירה לגילוי חיסיון.',
    '["חיסיון לטובת הציבור", "אי-חוקיות השגת ראיה", "עתירה לגילוי ראיה", "תקיפה עקיפה", "סעיף 45 לפקודת הראיות", "סמכות בית המשפט"]'::jsonb,
    '**וריאציה 1 — מסגרת דיונית לאי-חוקיות:** היכן נבחנת טענת אי-חוקיות בהשגת ראיה חסויה? ← במסגרת העתירה לגילוי ראיה חסויה לפי סעיף 45 לפקודת הראיות (ת"פ (שלום ת"א) 39087-05-22 לורברבום, רפרנס 24). **וריאציה 2 — תוקף החיסיון:** האם תעודת חיסיון גוברת על חובת מסירה אחרת? ← כן, היא אוסרת מסירת החומר לכולי עלמא, גם אם יש חובה בדין אחר (ת"פ (שלום ת"א) 39087-05-22 לורברבום, רפרנס 24). **וריאציה 3 — דרך עקיפה:** האם ניתן לתקוף תעודת חיסיון בדרך דיונית אחרת? ← לא, הדרך היחידה היא עתירה לגילוי ראיה חסויה (ת"פ (שלום ת"א) 39087-05-22 לורברבום, רפרנס 23).',
    'טענת אי-חוקיות בהשגת ראיה חסויה נבחנת במסגרת העתירה לגילוי ראיה לפי סעיף 45 לפקודת הראיות, ולא ניתן לתקוף את החיסיון בדרך עקיפה.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 45", "ת\"פ (שלום ת\"א) 39087-05-22 מדינת ישראל נ'' גלעד פלג לורברבום (16.2.2024)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט יאזן בין הצורך לגלות את הראיה לשם עשיית צדק לבין העניין הציבורי שלא לגלותה, ורק אם הצורך בעשיית צדק עדיף, יורה על גילויה.', false, 'בחירה זו מתארת את מבחן האיזון הכללי, אך אינה מדויקת כאשר הראיה ''חיונית'' להגנת הנאשם, שאז אין צורך באיזון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'אם הראיה חיונית להגנת הנאשם, בית המשפט יורה על הסרת החיסיון ללא צורך באיזון עם האינטרס הציבורי, ואם היא רק מועילה, יאזן בין התועלת להגנה לבין האינטרס הציבורי.', true, 'בחירה זו נכונה. הפסיקה מבחינה בין ראיה ''חיונית'' ל''מועילה''. כאשר הראיה חיונית, אין איזון והחיסיון יוסר. כאשר היא מועילה, נערך איזון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט יורה על הסרת החיסיון רק אם הראיה עשויה להביא לזיכוי ודאי של הנאשם.', false, 'בחירה זו שגויה. המבחן הוא ''פוטנציאל מזכה'' או ''עשויה לעורר ספק סביר'', ולא זיכוי ודאי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט יורה על הסרת החיסיון רק אם האינטרס הציבורי המוגן בתעודת החיסיון אינו ''עניין ציבורי חשוב''.', false, 'בחירה זו שגויה. זהו השלב הראשון בבחינה, אך אם נמצא שיש אינטרס ציבורי חשוב, עוברים לשלב השני של האיזון או הסרת החיסיון אם הראיה חיונית.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'לא, העתירה חייבת להידון בפני השופט הדן בתיק העיקרי, ואין סמכות להעבירה לשופט אחר.', false, 'בחירה זו שגויה. אף שהכלל הוא שהעתירה נדונה בפני השופט הדן בתיק, סעיף 45(ג) מאפשר העברה לשופט אחר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'כן, בית המשפט רשאי להעביר את הדיון בעתירה לשופט יחיד שאינו דן בתיק, או אם היה הרכב, לשופט יחיד שהוא אחד משופטי ההרכב או שאינו דן בתיק.', true, 'בחירה זו נכונה. סעיף 45(ג) לפקודת הראיות מאפשר לבית המשפט להעביר את הדיון בעתירה לגילוי ראיה חסויה לשופט יחיד שאינו דן בתיק העיקרי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'כן, אך רק אם הנאשם ביקש זאת במפורש, ובתנאי שהמאשימה הסכימה לכך.', false, 'בחירה זו שגויה. סמכות ההעברה נתונה לבית המשפט ואינה תלויה בבקשת הנאשם או בהסכמת המאשימה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'לא, אלא אם כן מדובר בחיסיון לפי סעיף 44 לפקודת הראיות, שאז הדיון נערך בפני שופט של בית המשפט העליון.', false, 'בחירה זו שגויה. היא מתארת את הדין לגבי חיסיון לפי סעיף 44, אך אינה רלוונטית לשאלת העברת הדיון לשופט אחר בחיסיון לפי סעיף 45.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט יבחן רק את חיוניות המידע להגנת הנאשם, ואין רלוונטיות לשיקולים של סיכון המקור או פגיעה בשיתוף הפעולה עם המשטרה.', false, 'בחירה זו שגויה. שיקולים של סיכון המקור ופגיעה בשיתוף הפעולה עם המשטרה הם אינטרסים ציבוריים חשובים הנבחנים במסגרת האיזון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט יאזן בין הצורך בגילוי זהות המקור לשם עשיית צדק לבין האינטרסים הציבוריים של מניעת סיכון חיי אדם, שמירה על שיתוף הפעולה עם המשטרה ומניעת חשיפת שיטות עבודה.', true, 'בחירה זו נכונה. אלו הם האינטרסים המרכזיים המתנגשים בעתירה לגילוי זהות מוסר מידע מודיעיני, ובית המשפט נדרש לאזן ביניהם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט יורה על גילוי זהות המקור רק אם הנאשם יוכיח שהמידע המודיעיני נמסר בחוסר תום לב או מתוך מניע פסול.', false, 'בחירה זו שגויה. אף שמניע פסול יכול להיות שיקול, הוא אינו התנאי היחיד או המרכזי לגילוי, והאיזון רחב יותר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'זהות מוסר מידע מודיעיני חסויה באופן מוחלט, ואין לבית המשפט סמכות להורות על גילויה.', false, 'בחירה זו שגויה. חיסיון זה אינו מוחלט, ובית המשפט מוסמך להסירו בכפוף למבחני האיזון הקבועים בסעיף 45 לפקודת הראיות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'לא, אי-חוקיות השגת הראיה אינה רלוונטית לדיון בעתירה לגילוי חיסיון, שכן תעודת החיסיון גוברת על כל חובה אחרת בדין למסור את החומר.', false, 'בחירה זו שגויה. אף שתעודת החיסיון גוברת על חובות מסירה אחרות, שאלת אי-החוקיות נבחנת במסגרת העתירה לגילוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'כן, שאלת אי-החוקיות של השגת הראיה תיבחן במסגרת העתירה לגילוי ראיה חסויה, והיא יכולה להשפיע על ההחלטה אם להסיר את החיסיון.', true, 'בחירה זו נכונה. הפסיקה קובעת כי גם אם חומר המחשב המוחזק הושג לכאורה ללא סמכות חוקית, המסגרת שבה תיבחן שאלת אי-החוקיות ומשמעותה תהיה המסגרת של עתירה לגילוי ראיה חסויה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, אך טענת אי-חוקיות השגת ראיה צריכה להידון בהליך נפרד של פסילת ראיות, ולא במסגרת העתירה לגילוי חיסיון.', false, 'בחירה זו שגויה. הפסיקה קובעת כי הדרך הדיונית היחידה לבחון את מסירת החומר לאחר הוצאת תעודת חיסיון היא עתירה לגילוי ראיה חסויה, ולא ניתן לבצע ''תקיפה עקיפה'' במתווה דיוני אחר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט יורה על הסרת החיסיון באופן אוטומטי אם הוכח שהראיה הושגה באופן בלתי חוקי.', false, 'בחירה זו שגויה. אי-חוקיות אינה מובילה להסרה אוטומטית, אלא נבחנת במסגרת האיזון הכולל של העתירה לגילוי.', 4);

END $$;

-- ============================================================
-- Q26 — 2019-S-Q26 — chapter=criminal_proc subtopic=publication_ban
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q26 skipped: external_id % already exists', '2019-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'publication_ban';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'publication_ban';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q26', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'בית משפט השלום בתל אביב ציווה, לבקשת חשוד שאינו עצור ושטרם הוגש נגדו כתב אישום, על איסור פרסום שמו לאחר שנוכח שהדבר עלול לגרום לחשוד נזק חמור ולאחר שמצא שבנסיבות העניין יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום. נורית, כתבת חדשות כאן 11, מבקשת לתקוף את ההחלטה ולהגיש בקשה לביטול צו איסור הפרסום. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 26}'::jsonb,
    'השאלה עוסקת בסמכות לדון בבקשה לביטול צו איסור פרסום, ובפרט בערכאה ובסוג ההרכב שידון בבקשה. היא מתייחסת להוראות סעיף 70ג(א) לחוק בתי המשפט, המהווה חריג לעקרון פומביות הדיון, ומאפשר לכל מי שמעוניין בביטול הצו, לרבות כלי תקשורת, לפנות לבית המשפט שנתן את הצו.',
    'סעיף 70ג(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע במפורש כי "ציווה בית המשפט על איסור פרסום לפי סעיף 70(ד), (ה) או (ה1), רשאי מי שמעוניין בביטול האיסור, לרבות כלי תקשורת, להגיש לבית המשפט שנתן את הצו בקשה לביטולו; בקשת הביטול תידון לפני דן יחיד" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70ג). הוראה זו מבטיחה כי בקשות לביטול צווי איסור פרסום יידונו באופן יעיל ומהיר על ידי הערכאה המקורית שנתנה את הצו, ובפני שופט יחיד, כדי למנוע סחבת ולהקל על הגישה לערכאות. היא משקפת את האיזון בין עקרון פומביות הדיון לבין הצורך להגן על זכויות הפרט, תוך מתן אפשרות לבחון מחדש את הצו לאור נסיבות משתנות (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 5).',
    'הסטודנט עלול לטעות ולחשוב שבקשה לביטול צו איסור פרסום תוגש לערכאת ערעור (כמו בית המשפט המחוזי) או תידון בפני הרכב שופטים, במקום לבית המשפט שנתן את הצו ובפני דן יחיד.',
    '["צו איסור פרסום", "ביטול צו איסור פרסום", "פומביות הדיון", "דן יחיד", "כלי תקשורת", "סעיף 70ג לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — ערכאה מוסמכת:** לאיזה בית משפט תוגש בקשה לביטול צו איסור פרסום? ← לבית המשפט שנתן את הצו (סעיף 70ג(א) לחוק בתי המשפט). **וריאציה 2 — הרכב שיפוטי:** בפני מי תידון בקשה לביטול צו איסור פרסום? ← בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט). **וריאציה 3 — מי רשאי להגיש בקשה:** מי רשאי להגיש בקשה לביטול צו איסור פרסום? ← מי שמעוניין בביטול האיסור, לרבות כלי תקשורת (סעיף 70ג(א) לחוק בתי המשפט).',
    'בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו ותידון בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70ג", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט המחוזי שבאזור שיפוטו נמצא בית המשפט שנתן את הצו. הבקשה תידון בפני שלושה שופטים.', false, 'בחירה זו שגויה. בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו, והיא תידון בפני דן יחיד, ולא בפני הרכב של שלושה שופטים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט המחוזי שבאזור שיפוטו נמצא בית המשפט שנתן את הצו. הבקשה תידון בפני דן יחיד.', false, 'בחירה זו שגויה. בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו, ולא לבית המשפט המחוזי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט שנתן את הצו. הבקשה תידון בפני שלושה שופטים.', false, 'בחירה זו שגויה. אף שהבקשה תוגש לבית המשפט שנתן את הצו, היא תידון בפני דן יחיד, ולא בפני הרכב של שלושה שופטים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט שנתן את הצו. הבקשה תידון בפני דן יחיד.', true, 'בחירה זו נכונה. סעיף 70ג(א) לחוק בתי המשפט קובע כי בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו ותידון בפני דן יחיד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'שינוי נסיבות לביטול צו איסור פרסום', 1, 'צו איסור פרסום על שמו של חשוד ניתן לפני מספר חודשים. כעת, הפרקליטות הודיעה על כוונתה להגיש כתב אישום נגד החשוד בכפוף לשימוע. האם החלטה זו מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור הפרסום?',
    'שאלה זו עוסקת במושג ''נסיבות חדשות'' בהקשר של בקשה לביטול צו איסור פרסום, כפי שמופיע בסעיף 70ג(ב) לחוק בתי המשפט. היא בוחנת האם החלטת הפרקליטות להגיש כתב אישום בכפוף לשימוע נחשבת לשינוי נסיבות המצדיק עיון מחודש בצו איסור הפרסום.',
    'סעיף 70ג(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "היה מבקש הביטול כאמור בסעיף קטן (א) צד לבקשה לאיסור הפרסום, עליו להראות נסיבות חדשות המצדיקות את בקשת הביטול; לעניין זה, ''נסיבות חדשות'' – לרבות הזמן שחלף ממועד מתן צו איסור הפרסום" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70ג). הפסיקה קבעה כי החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור הפרסום (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 5, 6, 7, 9, 10). הרציונל הוא שהחלטה כזו משמעותה שהתביעה הכללית שקלה היטב את חומרי החקירה והגיעה למסקנה כי אלו מבססים יסוד סביר להרשעה, מה שמחזק את האינטרס הציבורי בפרסום ומטה את נקודת האיזון לעבר פומביות הדיון (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 9, 10).',
    'הסטודנט עלול לטעות ולחשוב שרק הגשת כתב אישום בפועל מהווה שינוי נסיבות, ולא להבין שהחלטה על הגשת כתב אישום בכפוף לשימוע כבר משנה את נקודת האיזון.',
    '["צו איסור פרסום", "נסיבות חדשות", "שימוע", "הגשת כתב אישום", "פומביות הדיון", "סעיף 70ג לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — הגשת כתב אישום בכפוף לשימוע:** האם החלטה על הגשת כתב אישום בכפוף לשימוע נחשבת ''נסיבות חדשות'' לביטול צו איסור פרסום? ← כן (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 5, 6, 7, 9, 10). **וריאציה 2 — רציונל השינוי:** מדוע החלטה כזו מהווה שינוי נסיבות? ← היא משקפת הערכה ראייתית מבוססת יותר ומטה את נקודת האיזון לעבר פומביות הדיון (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 9, 10). **וריאציה 3 — סמכות לדון בביטול:** מי דן בבקשה לביטול צו איסור פרסום? ← בית המשפט שנתן את הצו, בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט).',
    'החלטה על הגשת כתב אישום בכפוף לשימוע ← ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור פרסום (סעיף 70ג(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70ג", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'נטל ההוכחה ל"נזק חמור" באיסור פרסום', 2, 'חשוד מבקש מבית המשפט לאסור את פרסום שמו, בטענה שהדבר יגרום לו נזק חמור. מהו נטל ההוכחה המוטל על החשוד להוכחת קיומו של ''נזק חמור''?',
    'שאלה זו מתמקדת בנטל ההוכחה הכבד המוטל על חשוד המבקש צו איסור פרסום על שמו, ובפרט בהגדרת המונח ''נזק חמור'' כפי שפורש בפסיקה. הבנת רף זה חיונית להבנת החריג לעקרון פומביות הדיון.',
    'סעיף 70(ה1)(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע שני תנאים מצטברים לאיסור פרסום שמו של חשוד: האחד, שהדבר עלול לגרום לחשוד ''נזק חמור'', והשני, שבית המשפט סבר כי יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). הפסיקה קבעה כי נטל ההוכחה ל''נזק חמור'' הוא משמעותי וכבד. על החשוד להראות כי עלול להיגרם לו, במידה קרובה של ודאות, נזק המתאפיין בחומרה מיוחדת, יוצאת מגדר הרגיל, החורג בחומרתו מהפגיעה הטבעית העלולה להיגרם לכל אדם בעקבות פתיחת חקירה פלילית נגדו (Verdict: מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016), Reference 1, 2; Verdict: מ"י (שלום ת"א) 11090-03-20 הלל בבייב נ'' מדינת ישראל (7.3.2020), Reference 11, 12; Verdict: מ"י (שלום ת"א) 13028-08-18 אילנית יהב בלילה נ'' מדינת ישראל (17.3.2019), Reference 14, 15). נזק זה יכול לכלול פגיעה בעיסוקו של החשוד שעיקר עיסוקו כרוך במגע עם אנשים, או שיקולים רלוונטיים למצבו המשפחתי (Verdict: מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016), Reference 2).',
    'הסטודנט עלול לטעות ולחשוב שכל פגיעה בשם הטוב או בפרנסה כתוצאה מחקירה פלילית עונה על הגדרת ''נזק חמור'', מבלי להבין את הרף הגבוה שנקבע בפסיקה.',
    '["צו איסור פרסום", "נזק חמור", "נטל הוכחה", "פומביות הדיון", "חריג לכלל", "סעיף 70(ה1)(1) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — הגדרת ''נזק חמור'':** מהו ''נזק חמור'' המצדיק איסור פרסום? ← נזק בחומרה מיוחדת, החורג מהפגיעה הטבעית של הליך פלילי (רע"פ 7276/13 פינטו, רפרנס 8, 11, 12, 17, 20, 31, 39, 40, 41, 50, 52, 53, 54, 55, 60, 65). **וריאציה 2 — נטל ההוכחה:** מי נושא בנטל להוכחת ''נזק חמור''? ← החשוד, וזהו נטל כבד ומשמעותי (מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני, רפרנס 1, 2). **וריאציה 3 — שיקולים לבחינת נזק חמור:** אילו שיקולים נבחנים בקביעת ''נזק חמור''? ← נסיבות אישיות ומשפחתיות, אופי עיסוקו של החשוד, עברו הפלילי ומשקל הראיות (בש"ע (שלום ראשל"צ) 34135-09-17 יהלום נ'' ניזאר אעלימי, רפרנס 17).',
    'להוכחת ''נזק חמור'' לאיסור פרסום, על החשוד להראות נזק חריג וקונקרטי, במידה קרובה של ודאות, החורג מהנזק הרגיל של הליך פלילי (רע"פ 7276/13 פינטו).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "מ\"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016)", "מ\"י (שלום ת\"א) 11090-03-20 הלל בבייב נ'' מדינת ישראל (7.3.2020)", "מ\"י (שלום ת\"א) 13028-08-18 אילנית יהב בלילה נ'' מדינת ישראל (17.3.2019)", "בש\"ע (שלום ראשל\"צ) 34135-09-17 יהלום - היחידה הארצית לחקירות ומאבק בפשיעה נ'' ניזאר אעלימי (3.10.2017)", "מ\"י (שלום ת\"א) 33630-10-16 מדינת ישראל נ'' דוד מירזה (18.11.2016)", "בש\"ע (שלום י-ם) 31437-07-21 פלונית נ'' מדינת ישראל רשות המיסים (5.8.2021)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)", "מ\"י (שלום חדרה) 39017-03-24 תחנת משטרה - זכרון נ'' אוליה קולטין (20.3.2024)", "ת\"פ (שלום כ\"ס) 10507-03-10 ערן מאיוסט נ'' מדינת ישראל (26.5.2022)", "א\"פ (שלום ראשון לציון) 2439-08-20 פלונית נ'' יאח\"ס, להב 433 (6.8.2020)", "ת\"פ (שלום ק\"ג) 4508-08-23 מדינת ישראל נ'' יאיר וקראט (23.4.2026)", "מ\"י (שלום ת\"א) 65385-09-16 חיים טולדנו נ'' מדינת ישראל (29.9.2016)", "ת\"פ (שלום ק\"ש) 3803-01-14 מדינת ישראל נ'' תמיר יואל (2.1.2017)", "ת\"פ (שלום נצרת) 48570-10-23 מדינת ישראל נ'' דני קריבוש (7.12.2025)", "מ\"ת (שלום י-ם) 13159-01-22 מדינת ישראל נ'' פלוני (8.5.2022)", "בש\"ע (שלום חד'') 50388-08-17 מע\"מ חדרה נ'' פהמי אבו מוח x (26.9.2017)", "ת\"פ (שלום קריות) 18951-12-19 ידיעות תקשורת בע\"מ נ'' שמואל שמש (18.4.2021)", "ת\"פ (שלום ת\"א) 20482-05-17 פלוני נ'' מדינת ישראל (10.4.2020)", "ת\"א (שלום ראשון לציון) 10295-07-19 פלוני נ'' אלה לוי וינריב (7.1.2022)", "ת\"א (שלום נת'') 12612-01-20 ניר חפץ נ'' יאיר נתניהו (5.2.2025)", "מ\"י (שלום ראשל\"צ) 39883-01-19 עופר זלצמן נ'' מדינת ישראל - יאל\"כ להב 433 (20.10.2019)", "צ\"א (שלום ראשון לציון) 10689-11-17 מדינת ישראל נ'' עודד מיליניאק (12.4.2018)", "מ\"י (שלום ראשל\"צ) 31364-01-14 מדינת ישראל נ'' פלוני (15.1.2014)", "ת\"א (שלום ת\"א) 19700-08-12 אברהם עמית נ'' וואלה תקשורת בע\"מ (1.9.2015)", "ת\"פ (שלום חי'') 39077-08-15 ילנה קיריצ''יק נ'' מדינת ישראל (25.5.2025)", "ת\"פ (שלום ת\"א) 51391-07-25 מדינת ישראל נ'' ניר שמשון ירון (12.1.2026)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'איסור פרסום לאחר הגשת כתב אישום', 3, 'נאשם, שנגדו הוגש כתב אישום, מבקש מבית המשפט לאסור את פרסום שמו. מהם התנאים שבית המשפט יבחן בבקשה זו?',
    'שאלה זו בוחנת את ההבחנה בין העילות לאיסור פרסום שמו של חשוד (לפני הגשת כתב אישום) לבין העילות לאיסור פרסום שמו של נאשם (לאחר הגשת כתב אישום). היא מדגישה את שינוי נקודת האיזון עם התקדמות ההליך הפלילי.',
    'הכלל בדבר פומביות הדיון הוא עקרון יסוד במשפט הישראלי, המעוגן בסעיף 3 לחוק יסוד: השפיטה ובסעיף 68(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984 (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). עם זאת, קיימים חריגים לכלל זה. כאשר מדובר בבקשה לאיסור פרסום שמו של חשוד שטרם הוגש נגדו כתב אישום, חל סעיף 70(ה1)(1) לחוק בתי המשפט, הדורש הוכחת ''נזק חמור'' והעדפת מניעת הנזק על פני העניין הציבורי (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). לעומת זאת, לאחר הגשת כתב אישום, נקודת האיזון משתנה באופן מובהק לעבר פרסום, והכלל הוא פרסום שמו של הנאשם (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 9). העילות לאיסור פרסום בשלב זה מצומצמות יותר וקבועות בסעיף 70(ד) לחוק בתי המשפט, המאפשר איסור פרסום לשם הגנה על ביטחונו של בעל דין, עד או אדם אחר, או לשם מניעת פגיעה חמורה בפרטיות של אחד מהם (Law: חוק בתי המשפ [נוסח משולב], תשמ"ד-1984, סעיף 70). הפסיקה מדגישה כי פגיעה פוטנציאלית בפרנסה או בשם הטוב אינה מובילה בהכרח לפגיעה חמורה בפרטיות (Verdict: תא"מ (שלום רח'') 25710-02-20 משה מנשה נ'' חונן קריספל (19.3.2020), Reference 68, 70).',
    'הסטודנט עלול לבלבל בין העילות השונות לאיסור פרסום לפני ואחרי הגשת כתב אישום, ולא להבין את ההבחנה המהותית שקבע המחוקק והפסיקה בין שלבי ההליך הפלילי.',
    '["צו איסור פרסום", "פומביות הדיון", "חשוד מול נאשם", "הגשת כתב אישום", "פגיעה חמורה בפרטיות", "סעיף 70(ד) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — איסור פרסום חשוד:** מהם התנאים לאיסור פרסום שמו של חשוד? ← נזק חמור והעדפת מניעת הנזק על פני העניין הציבורי (סעיף 70(ה1)(1) לחוק בתי המשפט). **וריאציה 2 — איסור פרסום נאשם:** מהם התנאים לאיסור פרסום שמו של נאשם? ← הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות (סעיף 70(ד) לחוק בתי המשפט). **וריאציה 3 — שינוי נקודת האיזון:** כיצד משתנה נקודת האיזון עם הגשת כתב אישום? ← נוטה באופן מובהק לעבר פרסום (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 9).',
    'איסור פרסום שמו של נאשם (לאחר כתב אישום) אפשרי רק לשם הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות (סעיף 70(ד) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)", "ת\"פ (שלום ק\"ש) 3803-01-14 מדינת ישראל נ'' תמיר יואל (2.1.2017)", "ת\"פ (שלום ת\"א) 30453-04-10 יהושע צולר נ'' מדינת ישראל פמת\"א (מיסוי וכלכלה) (21.12.2016)", "תא\"מ (שלום רח'') 25710-02-20 משה מנשה נ'' חונן קריספל (19.3.2020)", "ת\"פ (שלום ת\"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022)", "ת\"פ (שלום ת\"א) 20556-08-16 מדינת ישראל נ'' עומר פורן (5.8.2019)", "ת\"פ (שלום חי'') 39077-08-15 ילנה קיריצ''יק נ'' מדינת ישראל (25.5.2025)", "ת\"פ (שלום ת\"א) 20482-05-17 פלוני נ'' מדינת ישראל (10.4.2020)", "ת\"פ (שלום ראשל\"צ) 13147-01-15 פלוני נ'' מדינת ישראל (2.6.2015)", "מ\"ת (שלום ת\"א) 51232-07-15 מדינת ישראל נ'' זואי מיטל שפיר (26.7.2015)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'איסור פרסום פרטי חקירה הפוגעים בחקירה', 4, 'המשטרה מבקשת מבית המשפט לאסור פרסום פרטים מסוימים מחקירה מתנהלת, בטענה שהדבר עלול לפגוע בחקירה. מה הדין?',
    'שאלה זו עוסקת בעילה נוספת לאיסור פרסום, והיא פגיעה בחקירה מתנהלת. היא מדגישה את האיזון בין עקרון פומביות הדיון לבין הצורך להגן על יעילות החקירה הפלילית.',
    'סעיף 70(ה) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית משפט רשאי לאסור פרסום שמו של חשוד שטרם הוגש נגדו כתב אישום, או פרט אחר מפרטי החקירה, אם הדבר עלול לפגוע בחקירה שעל פי דין; אסר בית המשפט כאמור, יפקע האיסור עם הגשת כתב האישום נגד החשוד, אלא אם כן קבע בית המשפט אחרת" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). הוראה זו מאפשרת לבית המשפט להגן על שלמות ויעילות החקירה הפלילית, תוך הכרה בכך שפרסום מוקדם של פרטים מסוימים עלול לסכל את מטרותיה. הפסיקה מדגישה כי בשלב החקירה, בקשות רשויות החקירה נדונות, ככלל, במעמד צד אחד ובדלתיים סגורות, וכי איסורי פרסום שניתנו בשלב זה יפקעו מאליהם עם הגשת כתב אישום, אלא אם נקבע אחרת (Verdict: ת"פ (שלום ת"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022), Reference 29, 46).',
    'הסטודנט עלול לבלבל בין העילות השונות לאיסור פרסום המנויות בסעיף 70 לחוק בתי המשפט, ולא להבחין בין איסור פרסום שמו של חשוד (סעיף 70(ה1)(1)) לבין איסור פרסום פרטי חקירה (סעיף 70(ה)).',
    '["צו איסור פרסום", "פגיעה בחקירה", "פרטי חקירה", "פומביות הדיון", "שלב החקירה", "סעיף 70(ה) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — עילה לאיסור פרסום פרטי חקירה:** מתי בית המשפט רשאי לאסור פרסום פרטים מפרטי חקירה? ← אם הדבר עלול לפגוע בחקירה שעל פי דין (סעיף 70(ה) לחוק בתי המשפט). **וריאציה 2 — פקיעת הצו:** מתי יפקע איסור פרסום שניתן לפי סעיף 70(ה)? ← עם הגשת כתב האישום, אלא אם נקבע אחרת (סעיף 70(ה) לחוק בתי המשפט). **וריאציה 3 — אופי הדיון בשלב החקירה:** כיצד נדונות בקשות רשויות החקירה בשלב זה? ← ככלל, במעמד צד אחד ובדלתיים סגורות (ת"פ (שלום ת"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי, רפרנס 29, 46).',
    'בית המשפט רשאי לאסור פרסום פרטי חקירה אם הדבר עלול לפגוע בחקירה, והצו יפקע עם הגשת כתב האישום (סעיף 70(ה) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "ת\"פ (שלום ת\"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)", "ת\"פ (שלום נצרת) 3439-02-21 ג''בר חג''אזי נ'' מדינת ישראל (7.2.2021)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, החלטה על הגשת כתב אישום בכפוף לשימוע אינה מהווה ''נסיבות חדשות'', שכן הסטטוס של החשוד לא השתנה באופן מהותי.', false, 'בחירה זו שגויה. הפסיקה קבעה כי החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'', שכן היא משקפת הערכה ראייתית מבוססת יותר ומטה את נקודת האיזון לעבר פומביות הדיון.', true, 'בחירה זו נכונה. הפסיקה רואה בהחלטה על הגשת כתב אישום בכפוף לשימוע כ''נסיבות חדשות'' המצדיקות בחינה מחודשת של צו איסור הפרסום, בהתאם לסעיף 70ג(ב) לחוק בתי המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם חלף זמן רב ממועד מתן הצו המקורי, וזאת בנוסף להחלטת הפרקליטות.', false, 'בחירה זו שגויה. חלוף הזמן הוא נסיבה חדשה בפני עצמה, אך החלטת הפרקליטות מהווה נסיבה חדשה גם ללא קשר לחלוף הזמן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן הוגש כתב אישום בפועל, שכן רק אז פוקע הצו מאליו.', false, 'בחירה זו שגויה. אף שהצו פוקע עם הגשת כתב אישום, החלטה על הגשת כתב אישום בכפוף לשימוע מהווה נסיבה חדשה המצדיקה עיון חוזר עוד לפני הגשת כתב האישום בפועל.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'על החשוד להראות כי ייגרם לו נזק, ודי בכך כדי להצדיק איסור פרסום.', false, 'בחירה זו שגויה. לא די בנזק רגיל, אלא נדרש ''נזק חמור'' החורג מהרגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'על החשוד להראות כי עלול להיגרם לו, במידה קרובה של ודאות, נזק המתאפיין בחומרה מיוחדת, החורג בחומרתו מהפגיעה הטבעית העלולה להיגרם לכל אדם בעקבות פתיחת חקירה פלילית נגדו.', true, 'בחירה זו נכונה. הפסיקה קבעה כי נטל ההוכחה ל''נזק חמור'' הוא כבד ודורש הוכחת נזק חריג וקונקרטי, במידה קרובה של ודאות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'על החשוד להראות כי פרסום שמו יפגע בפרנסתו או בשמו הטוב, ובית המשפט יאזן זאת מול האינטרס הציבורי.', false, 'בחירה זו שגויה. פגיעה בפרנסה או בשם הטוב היא נזק אינהרנטי להליך פלילי, ואינה מספיקה כשלעצמה להוכחת ''נזק חמור'' חריג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'על החשוד להראות כי פרסום שמו יביא לפגיעה בלתי הפיכה בפרטיותו, ורק אז יורה בית המשפט על איסור פרסום.', false, 'בחירה זו שגויה. אף שפגיעה חמורה בפרטיות היא עילה לאיסור פרסום (לפי סעיף 70(ד)), המבחן ל''נזק חמור'' לפי סעיף 70(ה1)(1) רחב יותר ואינו מוגבל רק לפגיעה בלתי הפיכה בפרטיות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט יורה על איסור פרסום רק אם הפרסום עלול לפגוע בחקירה שעל פי דין.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום בשלב החקירה (סעיף 70(ה)), ולא לאחר הגשת כתב אישום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט יורה על איסור פרסום אם הדבר נחוץ לשם הגנה על ביטחונו של בעל דין, עד או אדם אחר, או לשם מניעת פגיעה חמורה בפרטיות של אחד מהם.', true, 'בחירה זו נכונה. סעיף 70(ד) לחוק בתי המשפט קובע את העילות לאיסור פרסום לאחר הגשת כתב אישום, והן כוללות הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט יורה על איסור פרסום אם הפרסום עלול לגרום לנאשם נזק חמור, ובית המשפט סבר כי יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום בשלב החשד (סעיף 70(ה1)(1)), ולאחר הגשת כתב אישום נקודת האיזון משתנה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא ניתן לאסור פרסום שמו של נאשם לאחר הגשת כתב אישום, שכן פומביות הדיון היא הכלל המוחלט בשלב זה.', false, 'בחירה זו שגויה. אף שפומביות הדיון היא הכלל, קיימים חריגים המאפשרים איסור פרסום גם לאחר הגשת כתב אישום, כפי שקבוע בסעיף 70(ד).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט רשאי לאסור פרסום פרטים מפרטי החקירה אם הדבר עלול לפגוע בחקירה שעל פי דין.', true, 'בחירה זו נכונה. סעיף 70(ה) לחוק בתי המשפט מסמיך את בית המשפט לאסור פרסום פרטי חקירה אם הדבר עלול לפגוע בחקירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט חייב לאסור פרסום פרטים מפרטי החקירה אם המשטרה טוענת לפגיעה בחקירה.', false, 'בחירה זו שגויה. הסמכות היא ''רשאי'' ולא ''חייב'', ונתונה לשיקול דעת בית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לא ניתן לאסור פרסום פרטי חקירה, שכן פומביות הדיון גוברת על כל אינטרס אחר בשלב זה.', false, 'בחירה זו שגויה. קיימת עילה מפורשת בחוק לאיסור פרסום פרטי חקירה אם הדבר עלול לפגוע בה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט רשאי לאסור פרסום רק אם הפרסום עלול לגרום נזק חמור לחשוד.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום שמו של חשוד (סעיף 70(ה1)(1)), אך קיימת עילה נפרדת לפגיעה בחקירה (סעיף 70(ה)).', 4);

END $$;

-- ============================================================
-- Q27 — 2019-S-Q27 — chapter=civil_proc subtopic=jurisdiction_subject
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q27 skipped: external_id % already exists', '2019-S-Q27';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'jurisdiction_subject';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'jurisdiction_subject';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q27', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'עורך דין מטעם ארגון עובדים מעוניין לפעול בשם הארגון ולהגיש תביעה בגין הפרת הוראות הסכם קיבוצי. עורך הדין מעוניין כי התביעה תידון בבית הדין הארצי לעבודה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 27}'::jsonb,
    'השאלה עוסקת בסמכות העניינית של בתי הדין לעבודה, ובפרט באפשרות להעביר תובענה מבית הדין האזורי לבית הדין הארצי כערכאה ראשונה. סעיף 24(ג) לחוק בית הדין לעבודה קובע חריג לכלל הסמכות של בית הדין האזורי, ומאפשר לנשיא בית הדין הארצי או סגנו להורות על העברה במקרים בעלי חשיבות, דחיפות או רגישות מיוחדת.',
    'הכלל הוא שתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי מיוחד, בעניין קיומו, תחולתו, פירושו, ביצועו או הפרתו של הסכם קיבוצי, נתונה לסמכותו הייחודית של בית הדין האזורי לעבודה, בהתאם לסעיף 24(א)(2) לחוק בית הדין לעבודה, תשכ"ט-1969 (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 24). עם זאת, סעיף 24(ג) לחוק קובע חריג לכלל זה: "על אף הוראות סעיף קטן (א)(2), רשאי נשיא בית הדין הארצי או סגנו, על פי בקשה של בעל דין או של היועץ המשפטי לממשלה שהוגשה לפני תחילת הדיון או במהלכו, להורות שדיון בתובענה לפי הסעיף הקטן האמור, שהוא בעל חשיבות, דחיפות או רגישות מיוחדת, יתקיים בבית הדין הארצי" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 24). במקרה הנדון, עורך הדין מטעם ארגון העובדים הוא ''בעל דין'' לעניין זה, והוא יכול להגיש בקשה לסגן נשיא בית הדין הארצי, אשר מוסמך להורות על העברת הדיון לבית הדין הארצי אם התקיימו התנאים של חשיבות, דחיפות או רגישות מיוחדת (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 10).',
    'הסטודנט עלול לטעות ולחשוב שכל תביעה בגין הפרת הסכם קיבוצי נדונית בבית הדין האזורי, מבלי להכיר את החריג הקבוע בסעיף 24(ג) המאפשר העברה לבית הדין הארצי במקרים מיוחדים.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "בית הדין האזורי לעבודה", "הסכם קיבוצי", "העברת דיון", "סעיף 24(ג) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סמכות העברה:** מי מוסמך להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי? ← נשיא בית הדין הארצי או סגנו (סעיף 24(ג) לחוק בית הדין לעבודה). **וריאציה 2 — תנאי העברה:** מהם התנאים להעברת תובענה לבית הדין הארצי? ← חשיבות, דחיפות או רגישות מיוחדת של התובענה (סעיף 24(ג) לחוק בית הדין לעבודה). **וריאציה 3 — יוזם הבקשה:** מי רשאי להגיש בקשה להעברה? ← בעל דין או היועץ המשפטי לממשלה (סעיף 24(ג) לחוק בית הדין לעבודה).',
    'תביעה בגין הפרת הסכם קיבוצי, שאמורה להידון בבית הדין האזורי, יכולה לעבור לבית הדין הארצי אם נשיא בית הדין הארצי או סגנו הורה על כך, לבקשת בעל דין, בשל חשיבות, דחיפות או רגישות מיוחדת (סעיף 24(ג) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 24", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התביעה תידון בבית הדין הארצי לעבודה אם סגן נשיא בית הדין הארצי לעבודה הורה על כך לאור בקשת עורך הדין.', true, 'בחירה זו נכונה. סעיף 24(ג) לחוק בית הדין לעבודה מאפשר לנשיא בית הדין הארצי או סגנו להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי, לבקשת בעל דין, אם היא בעלת חשיבות, דחיפות או רגישות מיוחדת.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התביעה תידון בבית הדין הארצי לעבודה אם הורה על כך נשיא בית הדין האזורי לעבודה שבו הייתה אמורה להיות מוגשת התביעה.', false, 'בחירה זו שגויה. הסמכות להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי נתונה לנשיא בית הדין הארצי או סגנו, ולא לנשיא בית הדין האזורי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התביעה תידון בבית הדין הארצי לעבודה אם נשיא בית הדין הארצי לעבודה הורה על כך לאור בקשת נשיא בית הדין האזורי שבו הייתה אמורה להיות מוגשת התביעה.', false, 'בחירה זו שגויה. אף שנשיא בית הדין הארצי מוסמך להורות על העברה, הבקשה יכולה להיות מוגשת ישירות על ידי בעל דין, ולא רק על ידי נשיא בית הדין האזורי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית הדין הארצי לא יוכל לדון בתביעה כערכאה ראשונה.', false, 'בחירה זו שגויה. אף שהכלל הוא שתביעות מסוג זה נדונות בבית הדין האזורי, סעיף 24(ג) לחוק בית הדין לעבודה קובע חריג המאפשר לבית הדין הארצי לדון בהן כערכאה ראשונה במקרים מיוחדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות בית הדין הארצי בסכסוך בין ארגוני עובדים', 1, 'ארגון עובדים א'' וארגון עובדים ב'' חלוקים ביניהם בשאלת יציגותם במקום עבודה מסוים. ארגון עובדים א'' מעוניין להגיש תובענה נגד ארגון עובדים ב'' בעניין זה. לאיזה בית דין תוגש התובענה?',
    'שאלה זו בוחנת את הסמכות העניינית הייחודית של בית הדין הארצי לעבודה לדון בסכסוכים בין ארגוני עובדים. היא מדגישה את ההבחנה בין סכסוכים אלו לבין סכסוכים אחרים הנדונים בבית הדין האזורי.',
    'סעיף 25(2) לחוק בית הדין לעבודה, תשכ"ט-1969, קובע כי לבית הדין הארצי תהא הסמכות הייחודית לדון "בתובענות בין ארגון עובדים לארגון עובדים אחר ותובענות בין ארגון מעבידים לארגון מעבידים אחר, הכל אם התובענות נובעות מענינים שביחסי עבודה" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 25). סכסוך יציגות בין שני ארגוני עובדים נופל במובהק בגדר עניינים שביחסי עבודה, ולכן הסמכות לדון בו נתונה לבית הדין הארצי לעבודה כערכאה ראשונה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 13).',
    'הסטודנט עלול לטעות ולחשוב שכל סכסוך הנוגע למקום עבודה ספציפי נדון בבית הדין האזורי, מבלי להבחין בסמכות הייחודית של בית הדין הארצי לסכסוכים בין-ארגוניים.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "ארגון עובדים", "סכסוך יציגות", "סעיף 25(2) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סכסוך בין ארגוני עובדים:** היכן נדון סכסוך בין ארגון עובדים אחד לארגון עובדים אחר? ← בבית הדין הארצי לעבודה בסמכות ייחודית (סעיף 25(2) לחוק בית הדין לעבודה). **וריאציה 2 — מהות הסכסוך:** האם סכסוך יציגות נחשב ''עניין שביחסי עבודה''? ← כן, ולכן הוא בסמכות בית הדין הארצי (נבו - המתמחה, דיני עבודה, עמ'' 13). **וריאציה 3 — ערכאה ראשונה:** האם בית הדין הארצי דן בכך כערכאה ראשונה? ← כן, זו סמכותו הייחודית כערכאה ראשונה (נבו - המתמחה, דיני עבודה, עמ'' 13).',
    'סכסוך בין ארגוני עובדים בענייני יחסי עבודה נדון בסמכות ייחודית של בית הדין הארצי לעבודה כערכאה ראשונה (סעיף 25(2) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 25", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחני סמכות עניינית של בית הדין לעבודה', 2, 'מהם המבחנים העיקריים לקביעת סמכותו העניינית של בית הדין לעבודה לדון בתובענה?',
    'שאלה זו עוסקת במבחנים הכלליים לקביעת הסמכות העניינית של בתי הדין לעבודה. הבנת מבחנים אלו חיונית להבחנה בין סמכות בתי הדין לעבודה לבין סמכות בתי המשפט האזרחיים.',
    'הסמכות העניינית של בתי הדין לעבודה נקבעת על פי שני מבחנים מצטברים: מבחן הצדדים ומבחן העילה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 11). מבחן הצדדים בוחן האם מדובר בתובענה בין עובד או חליפו למעסיק או חליפו (לפי סעיף 24(א)(1) לחוק בית הדין לעבודה), או בין גורמים אחרים המנויים בחוק (כגון ארגוני עובדים/מעבידים). מבחן העילה בוחן האם עילת התובענה היא ביחסי עבודה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 11). רק אם שני המבחנים מתקיימים, קמה לבית הדין לעבודה הסמכות העניינית לדון בתובענה (Verdict: סע"ש (אזורי ת"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע"מ (11.8.2024), Reference 23). מרכז הכובד לבחינת הסמכות העניינית הוא ''מהות הסכסוך וייחודו במסגרת משפט העבודה'' (Verdict: סע"ש (אזורי ת"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע"מ (11.8.2024), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שאחד המבחנים מספיק בפני עצמו, או לבלבל בין מבחני הסמכות העניינית של בית הדין לעבודה לבין אלו של בתי המשפט האזרחיים.',
    '["סמכות עניינית", "מבחן הצדדים", "מבחן העילה", "יחסי עבודה", "בית הדין לעבודה", "מבחנים מצטברים"]'::jsonb,
    '**וריאציה 1 — המבחנים העיקריים:** מהם המבחנים לקביעת סמכות עניינית של בית הדין לעבודה? ← מבחן הצדדים ומבחן העילה, במצטבר (נבו - המתמחה, דיני עבודה, עמ'' 11). **וריאציה 2 — מהות הסכסוך:** מהו מרכז הכובד לבחינת הסמכות העניינית? ← מהות הסכסוך וייחודו במסגרת משפט העבודה (סע"ש (אזורי ת"א) 4426-12-20 דרוקר, רפרנס 23). **וריאציה 3 — סמכות ייחודית:** מה משמעות קביעת סמכות לבית הדין לעבודה? ← מופקעת סמכותן של הערכאות האזרחיות הכלליות (סע"ש (אזורי ת"א) 4426-12-20 דרוקר, רפרנס 23).',
    'סמכות עניינית של בית הדין לעבודה נקבעת על פי מבחן הצדדים ומבחן העילה במצטבר, תוך התמקדות במהות הסכסוך (נבו - המתמחה, דיני עבודה, עמ'' 11).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 24", "סע\"ש (אזורי ת\"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע\"מ (11.8.2024)", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סמכות בית הדין הארצי להסכם קיבוצי כללי', 3, 'ארגון עובדים מעוניין להגיש תובענה בעניין פירושו של הסכם קיבוצי כללי החל על ענף שלם במשק. לאיזה בית דין תוגש התובענה?',
    'שאלה זו בוחנת את הסמכות העניינית הייחודית של בית הדין הארצי לעבודה לדון בתובענות הנוגעות להסכמים קיבוציים כלליים. היא מדגישה את הרציונל של ריכוז סכסוכים ארציים ובעלי חשיבות בערכאה העליונה של דיני העבודה.',
    'סעיף 25(1) לחוק בית הדין לעבודה, תשכ"ט-1969, קובע כי לבית הדין הארצי תהא הסמכות הייחודית לדון "בתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי כללי כמשמעותו בחוק הסכמים קיבוציים בענין קיומו, תחולתו, פירושו, ביצועו או הפרתו של הסכם קיבוצי, או הסדר קיבוצי אחר, או בכל ענין אחר הנובע מהם, או בענין תחולתו, פירושו, ביצועו או הפרתו של כל דין" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 25). הרציונל מאחורי הוראה זו הוא רצונו של המחוקק שסכסוכים ''ארציים'', בעלי היבט מיוחד ורחב היקף, יתבררו ישירות בפני בית הדין הארצי, כערכאה עליונה בתחום משפט העבודה והביטחון הסוציאלי (Verdict: סק"כ (עבודה ארצי) 51/09 "סאוט אלעאמל" - להגנת זכויות העובדים והמובטלים - שר התעשיה המסחר והתעסוקה (3.1.2012), Reference 8, 9).',
    'הסטודנט עלול לבלבל בין סמכות בית הדין האזורי (הסכם קיבוצי מיוחד) לבין סמכות בית הדין הארצי (הסכם קיבוצי כללי), או להתעלם מהסמכות הייחודית של בית הדין הארצי במקרים אלו.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "הסכם קיבוצי כללי", "פירוש הסכם קיבוצי", "סעיף 25(1) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סמכות להסכם קיבוצי כללי:** היכן נדון סכסוך בעניין פירוש הסכם קיבוצי כללי? ← בבית הדין הארצי לעבודה בסמכות ייחודית (סעיף 25(1) לחוק בית הדין לעבודה). **וריאציה 2 — רציונל הסמכות:** מדוע סכסוכים אלו נדונים בבית הדין הארצי? ← כדי להעביר למסלול הכרעה מהירה סכסוכים ארציים מרכזיים ויוצאי דופן בחשיבותם (סק"כ (עבודה ארצי) 51/09 "סאוט אלעאמל", רפרנס 9). **וריאציה 3 — הרכב בית הדין הארצי:** באיזה הרכב ידון בית הדין הארצי בעניינים אלו? ← בשבעה, שהם שלושה שופטים, שני נציגי עובדים ושני נציגי מעסיקים (סעיף 20(א)(3) לחוק בית הדין לעבודה).',
    'תובענה בעניין הסכם קיבוצי כללי נדונית בסמכות ייחודית של בית הדין הארצי לעבודה כערכאה ראשונה (סעיף 25(1) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 20", "חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 25", "סק\"כ (עבודה ארצי) 51/09 \"סאוט אלעאמל\" - להגנת זכויות העובדים והמובטלים - שר התעשיה המסחר והתעסוקה (3.1.2012)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'התערבות בג"ץ בפסקי דין של בתי הדין לעבודה', 4, 'צד להליך בבית הדין הארצי לעבודה אינו מרוצה מפסק הדין שניתן. האם הוא יכול להגיש עתירה לבג"ץ נגד פסק הדין, ומהם התנאים להתערבות בג"ץ?',
    'שאלה זו עוסקת ביחסי הגומלין בין בית המשפט העליון (בג"ץ) לבין בתי הדין לעבודה, ובפרט באמות המידה להתערבות בג"ץ בפסקי דין של בית הדין הארצי לעבודה. היא מדגישה את עקרון אי-ההתערבות של בג"ץ כערכאת ערעור, למעט במקרים חריגים ביותר.',
    'הלכה פסוקה היא כי בג"ץ אינו משמש כערכאת ערעור על החלטות ופסקי דין של בתי הדין לעבודה (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14; Verdict: בג"ץ 5596819 אביב חזיזה נ'' בית הדין הארצי לעבודה (25.10.2021), Reference 20, 21). התערבות בג"ץ בהחלטות אלו שמורה למקרים חריגים ביותר, בהם מתקיימים שני תנאים מצטברים: (1) נפלה טעות משפטית מהותית בהחלטה, ו-(2) שיקולי צדק מחייבים את התערבות בג"ץ בנסיבות העניין (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14). נקודת המוצא היא שבית הדין הארצי לעבודה נחשב לערכאה השיפוטית בעלת המומחיות בתחום משפט העבודה, ועליו הוטל התפקיד של גיבוש ההלכה בתחום זה (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14; Verdict: בג"ץ 5589304 אריה בגו נ'' בית הדין הארצי לעבודה (17.10.2021), Reference 22).',
    'הסטודנט עלול לטעות ולחשוב שבג"ץ הוא ערכאת ערעור רגילה על בתי הדין לעבודה, מבלי להבין את אמות המידה המחמירות והחריגות להתערבותו.',
    '["בג\"ץ", "בית הדין הארצי לעבודה", "ביקורת שיפוטית", "טעות משפטית מהותית", "שיקולי צדק", "מומחיות שיפוטית"]'::jsonb,
    '**וריאציה 1 — מעמד בג"ץ:** האם בג"ץ הוא ערכאת ערעור על בית הדין הארצי לעבודה? ← לא, הוא אינו משמש כערכאת ערעור (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14). **וריאציה 2 — תנאי התערבות:** מתי יתערב בג"ץ בפסק דין של בית הדין הארצי? ← במקרים חריגים, אם נפלה טעות משפטית מהותית ושיקולי צדק מחייבים התערבות (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14). **וריאציה 3 — מומחיות בית הדין לעבודה:** מדוע בג"ץ מצמצם את התערבותו? ← לבית הדין הארצי מומחיות מיוחדת בתחום משפט העבודה (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14).',
    'בג"ץ אינו ערכאת ערעור על בית הדין הארצי לעבודה, ויתערב רק במקרים חריגים של טעות משפטית מהותית ושיקולי צדק (בג"ץ 5200/23 עו"ד שאול כהן).',
    '["בג\"ץ 4737/14 הסתדרות העובדים הלאומית נ'' שר הכלכלה (5.11.2014)", "בג\"ץ 5200/23 עו\"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023)", "בג\"ץ 5148/18 אור שחם נ'' בית הדין הארצי לעבודה (11.7.2022)", "בג\"ץ 5589304 אריה בגו נ'' בית הדין הארצי לעבודה (17.10.2021)", "בג\"ץ 5596819 אביב חזיזה נ'' בית הדין הארצי לעבודה (25.10.2021)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לבית הדין האזורי לעבודה, שכן מדובר בסכסוך הנוגע למקום עבודה ספציפי.', false, 'בחירה זו שגויה. סכסוכים בין ארגוני עובדים נדונים בסמכות ייחודית של בית הדין הארצי לעבודה, ללא קשר למקום העבודה הספציפי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לבית הדין הארצי לעבודה, שכן זוהי תובענה בין ארגון עובדים אחד לארגון עובדים אחר הנובעת מענייני יחסי עבודה.', true, 'בחירה זו נכונה. סעיף 25(2) לחוק בית הדין לעבודה קובע סמכות ייחודית לבית הדין הארצי לדון בתובענות בין ארגון עובדים לארגון עובדים אחר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'לבית המשפט המחוזי, שכן מדובר בסכסוך בעל אופי ציבורי הנוגע לזכויות התאגדות.', false, 'בחירה זו שגויה. סכסוכים בין ארגוני עובדים הם בתחום סמכותו הייחודית של בית הדין לעבודה, ולא של בית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לבית הדין האזורי לעבודה, אלא אם כן נשיא בית הדין הארצי הורה אחרת.', false, 'בחירה זו שגויה. אין צורך בהוראת נשיא בית הדין הארצי במקרה זה, שכן הסמכות הייחודית לבית הדין הארצי קבועה בחוק במפורש לסכסוכים בין ארגוני עובדים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'מבחן הסעד הנתבע בלבד.', false, 'בחירה זו שגויה. מבחן הסעד אינו עומד בפני עצמו, אלא נבחן בשילוב עם מבחן העילה ומבחן הצדדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'מבחן הצדדים ומבחן העילה, כאשר שניהם צריכים להתקיים במצטבר.', true, 'בחירה זו נכונה. הפסיקה קבעה כי סמכותו העניינית של בית הדין לעבודה נקבעת על פי שני מבחנים מצטברים: מבחן הצדדים ומבחן העילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'מבחן מהות הסכסוך וייחודו במסגרת משפט העבודה, ללא קשר לזהות הצדדים.', false, 'בחירה זו שגויה. אף ש''מהות הסכסוך'' היא מרכזית, היא נבחנת במסגרת מבחן העילה, וזהות הצדדים היא מבחן נפרד ומצטבר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'מבחן הסעד הנתבע או מבחן העילה, לפי בחירת התובע.', false, 'בחירה זו שגויה. הסמכות העניינית נקבעת על פי דין, ולא לפי בחירת התובע, ודורשת עמידה במבחנים מצטברים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לבית הדין האזורי לעבודה, שכן הוא הערכאה הראשונה לרוב סכסוכי העבודה.', false, 'בחירה זו שגויה. אף שבית הדין האזורי הוא הערכאה הראשונה לרוב סכסוכי העבודה, סכסוכים הנוגעים להסכם קיבוצי כללי הם בסמכות ייחודית של בית הדין הארצי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לבית הדין הארצי לעבודה, שכן זוהי סמכותו הייחודית לדון בתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי כללי.', true, 'בחירה זו נכונה. סעיף 25(1) לחוק בית הדין לעבודה מקנה סמכות ייחודית לבית הדין הארצי לדון בתובענות הנוגעות להסכם קיבוצי כללי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'לבית המשפט המחוזי, שכן מדובר בהסכם בעל השלכות רוחב על המשק.', false, 'בחירה זו שגויה. סכסוכים הנוגעים להסכמים קיבוציים הם בתחום סמכותו הייחודית של בית הדין לעבודה, ולא של בית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לבית הדין האזורי לעבודה, אלא אם כן נשיא בית הדין הארצי הורה על העברה.', false, 'בחירה זו שגויה. במקרה של הסכם קיבוצי כללי, הסמכות הייחודית היא מלכתחילה של בית הדין הארצי, ואין צורך בהוראת העברה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, בג"ץ משמש כערכאת ערעור על פסקי דין של בית הדין הארצי לעבודה, ויתערב אם נפלה טעות משפטית.', false, 'בחירה זו שגויה. בג"ץ אינו משמש כערכאת ערעור על בתי הדין לעבודה, והתערבותו שמורה למקרים חריגים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'כן, אך התערבות בג"ץ שמורה למקרים חריגים בלבד, בהם נפלה טעות משפטית מהותית בהחלטה ושיקולי צדק מחייבים התערבות.', true, 'בחירה זו נכונה. זוהי ההלכה הפסוקה לגבי התערבות בג"ץ בפסקי דין של בתי הדין לעבודה, תוך מתן משקל למומחיותם של בתי הדין לעבודה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לא, פסקי דין של בית הדין הארצי לעבודה הם סופיים ואינם ניתנים לביקורת שיפוטית נוספת.', false, 'בחירה זו שגויה. אף שפסקי הדין של בית הדין הארצי הם סופיים ברובם, קיימת אפשרות עקרונית לביקורת בג"ץ במקרים חריגים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'כן, אך רק אם פסק הדין של בית הדין הארצי עומד בסתירה להלכה קודמת של בית המשפט העליון.', false, 'בחירה זו שגויה. סתירה להלכה קודמת היא עילה לדיון נוסף בבית המשפט העליון, אך לא התנאי היחיד להתערבות בג"ץ בפסקי דין של בתי הדין לעבודה.', 4);

END $$;

-- ============================================================
-- Q28 — 2019-S-Q28 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q28';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q28 skipped: external_id % already exists', '2019-S-Q28';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q28', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'בתביעה שהגיש אביב בבית המשפט לתביעות קטנות בחדרה ביקש אביב כי בית המשפט ייתן צו לגילוי מסמכים. בית המשפט דחה את הבקשה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 28}'::jsonb,
    'השאלה עוסקת בסמכויותיו הדיוניות של בית המשפט לתביעות קטנות, ובפרט ביחסו להליכי גילוי מסמכים. בית המשפט לתביעות קטנות אינו כפוף באופן מלא לסדרי הדין הרגילים, ומוסמך לסטות מהם כדי להגיע להכרעה צודקת ומהירה, תוך איזון בין הצורך בגילוי לבין מטרות ההליך המיוחד.',
    'בית המשפט לתביעות קטנות הוא ערכאה ייחודית שנועדה לאפשר לאזרח הקטן גישה מהירה, פשוטה וזולה לצדק (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: ת"ק (תביעות קטנות ת"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015), Reference 18). לשם כך, סעיף 62(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית משפט לתביעות קטנות אינו קשור בסדרי הדין הנוהגים בבית משפט אחר, ובכפוף לסדרי דין שהתקין שר המשפטים לענין סימן זה, יפעל בדרך הנראית לו מועילה ביותר להכרעה צודקת ומהירה" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 62). תקנה 9 לתקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, מוסיפה כי "לבית המשפט יהיו הסמכויות הנתונות לבית משפט שלום בענינים שבסדר דין או שבנוהג... אולם רשאי בית המשפט שלא להשתמש בסמכות מסמכויות אלה אם נראה לו הדבר מועיל יותר להכרעה צודקת ומהירה" (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 9). מכאן שלבית המשפט לתביעות קטנות נתונות הסמכויות של בית משפט שלום, כולל הסמכות ליתן צו לגילוי מסמכים (כפי שקבוע בתקנות סדר הדין האזרחי), אך הוא רשאי שלא להשתמש בהן אם סבר שדחיית הבקשה מועילה יותר להכרעה צודקת ומהירה (Verdict: ת"ק (תביעות קטנות פ"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע"מ (3.9.2025), Reference 1, 2). הליכי גילוי ועיון מובנים, כפי שקיימים בהליכים אזרחיים רגילים, אינם קיימים בתביעות קטנות, שכן הם מייקרים ומאריכים את ההתדיינות (Literature: יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | ה. תביעות קטנות, עמ'' 4). עם זאת, בית המשפט רשאי לדרוש מבעל דין להמציא מסמכים ספציפיים אם מצא שהם רלוונטיים למחלוקת (Verdict: ת"ק (תביעות קטנות פ"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע"מ (3.9.2025), Reference 1, 2).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט לתביעות קטנות אינו מוסמך כלל ליתן צו לגילוי מסמכים, או לחילופין, שהוא חייב להיענות לבקשה כזו כמו בבית משפט שלום רגיל, מבלי להבין את שיקול הדעת הרחב הנתון לו.',
    '["בית משפט לתביעות קטנות", "גילוי מסמכים", "סדרי דין", "הכרעה צודקת ומהירה", "שיקול דעת שיפוטי", "סעיף 62(ב) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — סמכות כללית:** האם לבית המשפט לתביעות קטנות יש סמכות ליתן צו לגילוי מסמכים? ← כן, יש לו את הסמכויות הנתונות לבית משפט שלום (תקנה 9 לתקנות שיפוט בתביעות קטנות; ת"ק (פ"ת) 17980-02-25 בר, רפרנס 1). **וריאציה 2 — שיקול דעת:** האם בית המשפט חייב להיענות לבקשה לגילוי מסמכים? ← לא, הוא רשאי שלא להשתמש בסמכות זו אם סבר שזה מועיל יותר להכרעה צודקת ומהירה (תקנה 9 לתקנות שיפוט בתביעות קטנות; ת"ק (פ"ת) 17980-02-25 בר, רפרנס 1). **וריאציה 3 — תכלית ההליך:** מדוע ניתנת גמישות כזו? ← כדי לאפשר לאזרח הקטן גישה מהירה, פשוטה וזולה לצדק (רע"א 292/93 סרבוז, רפרנס 8).',
    'בית המשפט לתביעות קטנות מוסמך ליתן צו לגילוי מסמכים, אך רשאי לדחות בקשה כזו אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה, בהתאם לאופי ההליך (סעיף 62(ב) לחוק בתי המשפט ותקנה 9 לתקנות שיפוט בתביעות קטנות).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 62", "תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 9", "ת\"ק (תביעות קטנות פ\"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע\"מ (3.9.2025)", "רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "ת\"ק (תביעות קטנות נת'') 54901-11-18 שאול ג''ליקס נ'' רמי שבירו הנדסה בניה והשקעות בע\"מ (6.9.2019)", "יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | פרק יז הליכי גילוי ועיון בסוגים שונים של הליכים אזרחיים, עמ'' 4"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט לתביעות קטנות אינו מוסמך ליתן צו מסוג זה.', false, 'בחירה זו שגויה. לבית המשפט לתביעות קטנות נתונות כל הסמכויות הנתונות לבית משפט שלום, כולל הסמכות ליתן צו לגילוי מסמכים, אלא אם כן שר המשפטים קבע הסדר שונה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על בית המשפט להיענות לבקשה.', false, 'בחירה זו שגויה. לבית המשפט לתביעות קטנות שיקול דעת רחב בנוגע לסדרי הדין, והוא רשאי שלא להיענות לבקשה אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על בית המשפט לדחות את הבקשה.', false, 'בחירה זו שגויה. בית המשפט אינו חייב לדחות את הבקשה, אלא רשאי לדחותה אם סבר שזה מועיל להכרעה צודקת ומהירה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי היה לדחות את הבקשה אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה בתביעה.', true, 'בחירה זו נכונה. סעיף 62(ב) לחוק בתי המשפט ותקנה 9 לתקנות שיפוט בתביעות קטנות מעניקים לבית המשפט לתביעות קטנות גמישות רחבה בסדרי הדין, ומאפשרים לו לסטות מהם אם הדבר מועיל להכרעה צודקת ומהירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ייצוג עורך דין בתביעות קטנות', 1, 'בתביעה שהגיש ראובן בבית המשפט לתביעות קטנות, הוא מבקש להיות מיוצג על ידי עורך דין. מה הדין?',
    'שאלה זו עוסקת בכלל ובחריגים בנוגע לייצוג משפטי בבית המשפט לתביעות קטנות. מטרת המגבלה על ייצוג היא לפשט את ההליך, להוזיל אותו ולקדם שוויון מהותי בין בעלי הדין, אך החוק מאפשר חריגים במקרים מיוחדים.',
    'סעיף 63(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בעל דין בבית משפט לתביעות קטנות אינו רשאי להיות מיוצג על ידי עורך דין, אלא ברשות בית המשפט ומטעמים מיוחדים שיירשמו" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 63). הכלל הוא איסור ייצוג, והחריג הוא ייצוג על ידי עורך דין ברשות בית המשפט ומטעמים מיוחדים. מטרת האיסור היא להקטין את עלויות ההליך, לפשט אותו ולאפשר לאזרח הקטן גישה קלה ומהירה לצדק, תוך צמצום פערי הכוחות בין הצדדים (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: ת"ק (תביעות קטנות ת"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015), Reference 18). בית המשפט רשאי לנקוט גישה פעילה בניהול ההליך כדי להבטיח שוויון מהותי, גם כאשר אחד הצדדים הוא עורך דין והשני אינו מיוצג (Verdict: רע"א 5234/17 דרייבר ישראל בע"מ נ'' עו"ד אלירן ג''נח (4.7.2018), Reference 17).',
    'הסטודנט עלול לטעות ולחשוב שייצוג עורך דין אסור באופן מוחלט בתביעות קטנות, מבלי להכיר את החריג המאפשר ייצוג ברשות בית המשפט ומטעמים מיוחדים.',
    '["בית משפט לתביעות קטנות", "ייצוג עורך דין", "סעיף 63 לחוק בתי המשפט", "טעמים מיוחדים", "פומביות הדיון", "שוויון מהותי"]'::jsonb,
    '**וריאציה 1 — הכלל בייצוג:** האם בעל דין רשאי להיות מיוצג על ידי עורך דין בתביעות קטנות? ← לא, אלא ברשות בית המשפט ומטעמים מיוחדים (סעיף 63(א) לחוק בתי המשפט). **וריאציה 2 — מטרת האיסור:** מהי מטרת האיסור על ייצוג? ← להקטין עלויות, לפשט הליך, לאפשר גישה לצדק ולצמצם פערי כוחות (רע"א 292/93 סרבוז, רפרנס 8). **וריאציה 3 — תפקיד בית המשפט:** מה תפקיד בית המשפט כשיש פערי כוחות? ← לנקוט גישה פעילה בניהול ההליך כדי להבטיח שוויון מהותי (רע"א 5234/17 דרייבר ישראל, רפרנס 17).',
    'ייצוג עורך דין בתביעות קטנות אסור ככלל, אך מותר ברשות בית המשפט ומטעמים מיוחדים (סעיף 63(א) לחוק בתי המשפט), במטרה לשמור על אופי ההליך.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 63", "רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "ת\"ק (תביעות קטנות ת\"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015)", "רע\"א 5234/17 דרייבר ישראל בע\"מ נ'' עו\"ד אלירן ג''נח (4.7.2018)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 77"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'אמות מידה למתן רשות ערעור', 2, 'צד המבקש לערער על פסק דין של בית משפט לתביעות קטנות. מהן אמות המידה למתן רשות ערעור על פסק דין כזה?',
    'שאלה זו עוסקת באמות המידה המחמירות למתן רשות ערעור על פסקי דין של בית המשפט לתביעות קטנות. אמות מידה אלו נועדו לשמר את תכלית ההליך בתביעות קטנות – דיון מהיר, פשוט וזול – ולמנוע סרבול והתייקרות של ההתדיינות.',
    'ערעור על פסק דין של בית משפט לתביעות קטנות טעון רשות (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). הפסיקה קבעה כי אמת המידה למתן רשות ערעור על פסקי דינו של בית המשפט לתביעות קטנות היא מחמירה במיוחד, ורשות זו תינתן רק במקרים חריגים ביותר בהם נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור (Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). זאת, כדי לשמור על תכלית הקמתו של בית המשפט לתביעות קטנות – לאפשר דיון מהיר, קצר, פשוט וזול (Verdict: רת"ק (מחוזי ב"ש) 5505360 שלמה אבי עוז נ'' חדוה אפללו (24.6.2021), Reference 12). רשות ערעור לא בהכרח תינתן אף כאשר מתעוררת שאלה משפטית בעלת חשיבות החורגת מעניינם הישיר של הצדדים למחלוקת (Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). כמו כן, ערכאת הערעור לא תתערב ככלל בממצאים עובדתיים וקביעות מהימנות של בית המשפט לתביעות קטנות (Verdict: רע"א 5623/18 עיריית ירושלים נ'' נתנאל מור (9.8.2018), Reference 6; Verdict: רת"ק (מחוזי ב"ש) 37422-05-21 רשל קרין רוזן נ'' חיים גרמן (27.7.2021), Reference 13).',
    'הסטודנט עלול לבלבל בין אמות המידה למתן רשות ערעור על פסקי דין של בית משפט שלום רגיל לבין אלו של בית המשפט לתביעות קטנות, שהן מחמירות יותר באופן משמעותי.',
    '["בית משפט לתביעות קטנות", "רשות ערעור", "פגם מהותי", "תכלית ההליך", "ממצאים עובדתיים", "קביעות מהימנות"]'::jsonb,
    '**וריאציה 1 — סוג הערעור:** האם ערעור על פסק דין של תביעות קטנות הוא בזכות או ברשות? ← ברשות (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא, רפרנס 10). **וריאציה 2 — אמות המידה:** מהן אמות המידה למתן רשות ערעור? ← מחמירות במיוחד, רק במקרים חריגים ביותר בהם נפל פגם מהותי (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא, רפרנס 10). **וריאציה 3 — התערבות בממצאים עובדתיים:** האם ערכאת הערעור תתערב בממצאים עובדתיים? ← ככלל לא, אלא במקרים חריגים ביותר (רע"א 5623/18 עיריית ירושלים, רפרנס 6).',
    'רשות ערעור על פסק דין של תביעות קטנות תינתן במשורה ובמקרים חריגים בלבד של פגם מהותי, כדי לשמר את אופי ההליך (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא).',
    '["רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "רע\"א 5623/18 עיריית ירושלים נ'' נתנאל מור (9.8.2018)", "רת\"ק (מחוזי ב\"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022)", "רת\"ק (מחוזי ב\"ש) 5505360 שלמה אבי עוז נ'' חדוה אפללו (24.6.2021)", "רת\"ק (מחוזי ב\"ש) 37422-05-21 רשל קרין רוזן נ'' חיים גרמן (27.7.2021)", "רע\"א 5106/23 גג-כל איתום בע\"מ נ'' רינה עמרם (22.10.2023)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק שבעה-עשר - בית משפט לתביעות קטנות, עמ'' 13"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'העברת דיון מבית משפט לתביעות קטנות', 3, 'בתביעה שהוגשה לבית המשפט לתביעות קטנות, התברר כי היא מעוררת שאלות משפטיות מורכבות מתחום המשפט המינהלי. האם בית המשפט רשאי להעביר את הדיון לבית משפט השלום?',
    'שאלה זו בוחנת את סמכותו של בית המשפט לתביעות קטנות להעביר דיון לבית משפט השלום, במיוחד כאשר התביעה מורכבת מדי עבור הפורום הייחודי של תביעות קטנות. סמכות זו נועדה לשמור על אופי ההליך הפשוט והמהיר, תוך הבטחת בירור הולם של תביעות מורכבות.',
    'סעיף 60(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית המשפט רשאי לא לדון בתביעה או בתביעה-שכנגד ולהעבירן לבית משפט שלום או לבית המשפט המוסמך לדון בהן, לפי העניין, אם ראה שהדיון בבית משפט לתביעות קטנות אינו מתאים להן" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 60). הפסיקה מפרשת את עילת ''אי התאמה'' ככוללת מקרים בהם מדובר בעניין מורכב וסבוך הדורש בירור מקיף, כגון שאלות משפטיות מורכבות מתחום המשפט המינהלי או תביעות לשון הרע (Verdict: ת"ק (שלום נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021), Reference 15; Verdict: ת"ק (תביעות קטנות עפ'') 35280-11-24 מי מגידו - חברת הביוב והמים מייסודה של המועצה האזורית מגידו נ'' דנה לישינסקי (24.4.2025), Reference 14). במקרים כאלה, בית המשפט רשאי לפעול מיוזמתו להעברת התיק לבית משפט השלום, וזאת אף אם המבקש לא ביקש זאת בתחילת הדיון (Verdict: ת"ק (שלום נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021), Reference 15).',
    'הסטודנט עלול לטעות ולחשוב שסמכות ההעברה מוגבלת למקרים של ריבוי תביעות בלבד, ולא להבין שהיא חלה גם על תביעות מורכבות שאינן מתאימות לאופי הפשוט של בית המשפט לתביעות קטנות.',
    '["בית משפט לתביעות קטנות", "העברת דיון", "סמכות עניינית", "מורכבות משפטית", "סעיף 60(ב) לחוק בתי המשפט", "יוזמת בית המשפט"]'::jsonb,
    '**וריאציה 1 — עילת העברה:** מתי בית המשפט לתביעות קטנות רשאי להעביר דיון לבית משפט השלום? ← אם ראה שהדיון אינו מתאים לתביעה (סעיף 60(ב) לחוק בתי המשפט). **וריאציה 2 — דוגמאות לאי-התאמה:** אילו מקרים נחשבים ל''אי-התאמה''? ← תביעות מורכבות, כגון שאלות משפטיות מורכבות או תביעות לשון הרע (ת"ק (שלום נת'') 62274-11-20 חירותי סובר, רפרנס 15). **וריאציה 3 — יוזמת ההעברה:** האם בית המשפט יכול להעביר תיק מיוזמתו? ← כן, גם אם המבקש לא ביקש זאת (ת"ק (שלום נת'') 62274-11-20 חירותי סובר, רפרנס 15).',
    'בית המשפט לתביעות קטנות רשאי להעביר דיון לבית משפט השלום, גם מיוזמתו, אם התביעה מורכבת ואינה מתאימה לאופי ההליך (סעיף 60(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 60", "ת\"ק (תביעות קטנות נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021)", "ת\"ק (תביעות קטנות עפ'') 35280-11-24 מי מגידו - חברת הביוב והמים מייסודה של המועצה האזורית מגידו נ'' דנה לישינסקי (24.4.2025)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות מקומית בתביעות קטנות', 4, 'ראובן הגיש תביעה קטנה לבית המשפט בחדרה. הנתבע, שמעון, מתגורר בתל אביב, ובהסכם ביניהם נקבע כי בית המשפט המוסמך לדון בכל מחלוקת הוא בתל אביב. מה הדין לגבי הסמכות המקומית?',
    'שאלה זו עוסקת בכללי הסמכות המקומית הייחודיים לבית המשפט לתביעות קטנות. בניגוד לדין הכללי, בתביעות קטנות לא ניתן להתנות על כללי הסמכות המקומית בהסכם בין הצדדים, וזאת כדי להקל על האזרח הקטן בגישה לערכאות.',
    'תקנה 2(א) לתקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, קובעת כי תביעה תוגש לבית המשפט שאזור שיפוטו הוא אחד המקומות המנויים בה, וזאת "על אף האמור בכל הסכם שבין בעלי הדין" (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 2). כללים אלו כוללים, בין היתר, את מקום מגוריו או מקום עסקו של הנתבע, או מקום המעשה או המחדל שבשלו תובעים (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 2). המשמעות היא שבתביעות קטנות, כללי הסמכות המקומית הם קוגנטיים (לא ניתן להתנות עליהם), ואין תוקף להסכם שיפוט בין הצדדים (Verdict: רת"ק (מחוזי ב"ש) 5156-10-24 ברוריה שולה אבקסיס נ'' אירית דימר (29.12.2024), Reference 21; Literature: נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76).',
    'הסטודנט עלול לטעות וליישם את הכללים הרגילים של הסמכות המקומית, המאפשרים התניה בהסכם, מבלי להכיר את החריג הקבוע בתקנות שיפוט בתביעות קטנות.',
    '["בית משפט לתביעות קטנות", "סמכות מקומית", "הסכם שיפוט", "תקנה 2 לתקנות שיפוט בתביעות קטנות", "כללים קוגנטיים", "מקום מגורים/עסק"]'::jsonb,
    '**וריאציה 1 — תוקף הסכם שיפוט:** האם הסכם שיפוט בין הצדדים תקף בתביעות קטנות? ← לא, הסמכות המקומית נקבעת על אף האמור בכל הסכם (תקנה 2(א) לתקנות שיפוט בתביעות קטנות). **וריאציה 2 — כללי הסמכות המקומית:** מהם כללי הסמכות המקומית בתביעות קטנות? ← מקום מגוריו או עסקו של הנתבע, או מקום המעשה/מחדל (תקנה 2(א) לתקנות שיפוט בתביעות קטנות). **וריאציה 3 — רציונל הכלל:** מדוע לא ניתן להתנות על הסמכות המקומית? ← כדי לפתוח את שערי בית המשפט בפני ''האזרח הקטן'' ולהקל עליו (נבו - המתמחה, מערכת בתי המשפט, עמ'' 76).',
    'בתביעות קטנות, הסמכות המקומית נקבעת לפי כללים קוגנטיים (כגון מקום מגורי הנתבע), ואין תוקף להסכם שיפוט בין הצדדים (תקנה 2(א) לתקנות שיפוט בתביעות קטנות).',
    '["תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 2", "רת\"ק (מחוזי ב\"ש) 5156-10-24 ברוריה שולה אבקסיס נ'' אירית דימר (29.12.2024)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'ראובן אינו רשאי להיות מיוצג על ידי עורך דין, שכן ייצוג אסור בתביעות קטנות.', false, 'בחירה זו שגויה. אף שהכלל הוא איסור ייצוג, קיימים חריגים המאפשרים ייצוג על ידי עורך דין ברשות בית המשפט ומטעמים מיוחדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'ראובן רשאי להיות מיוצג על ידי עורך דין רק ברשות בית המשפט ומטעמים מיוחדים שיירשמו.', true, 'בחירה זו נכונה. סעיף 63(א) לחוק בתי המשפט קובע כי ייצוג על ידי עורך דין בתביעות קטנות מותנה ברשות בית המשפט ומטעמים מיוחדים שיירשמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ראובן רשאי להיות מיוצג על ידי עורך דין ללא צורך ברשות, שכן זו זכות יסוד.', false, 'בחירה זו שגויה. זכות הייצוג בתביעות קטנות מוגבלת, ואינה זכות מוחלטת ללא צורך ברשות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'ראובן רשאי להיות מיוצג על ידי עורך דין אם הצד שכנגד מיוצג אף הוא.', false, 'בחירה זו שגויה. אף ששוויון בייצוג הוא שיקול, הוא אינו תנאי אוטומטי לייצוג, ועדיין נדרשת רשות בית המשפט ומטעמים מיוחדים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רשות ערעור תינתן בזכות, שכן זו זכות יסוד של כל מתדיין.', false, 'בחירה זו שגויה. ערעור על פסק דין של בית משפט לתביעות קטנות טעון רשות, ואינו בזכות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רשות ערעור תינתן רק במקרים חריגים ביותר בהם נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור, וזאת כדי לשמור על תכלית ההליך הפשוט והמהיר.', true, 'בחירה זו נכונה. הפסיקה קבעה אמות מידה מחמירות למתן רשות ערעור על פסקי דין של תביעות קטנות, כדי לשמר את אופיו של ההליך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רשות ערעור תינתן אם מתעוררת שאלה משפטית בעלת חשיבות החורגת מעניינם הישיר של הצדדים למחלוקת.', false, 'בחירה זו שגויה. אף שזהו שיקול במתן רשות ערעור ''רגילה'', בתביעות קטנות הרף מחמיר יותר, ורשות לא בהכרח תינתן גם במקרה כזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רשות ערעור תינתן אם בית המשפט לתביעות קטנות שגה בממצאים עובדתיים או בקביעות מהימנות.', false, 'בחירה זו שגויה. ערכאת הערעור לא תתערב ככלל בממצאים עובדתיים וקביעות מהימנות של בית המשפט לתביעות קטנות, אלא במקרים חריגים ביותר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לא, בית המשפט לתביעות קטנות אינו מוסמך להעביר דיון לבית משפט השלום.', false, 'בחירה זו שגויה. סעיף 60(ב) לחוק בתי המשפט מעניק לבית המשפט לתביעות קטנות סמכות להעביר דיון לבית משפט השלום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'כן, בית המשפט רשאי להעביר את הדיון לבית משפט השלום אם ראה שהדיון בבית המשפט לתביעות קטנות אינו מתאים לתביעה, למשל בשל מורכבותה המשפטית.', true, 'בחירה זו נכונה. סעיף 60(ב) לחוק בתי המשפט מאפשר העברת דיון אם הוא אינו מתאים לבית המשפט לתביעות קטנות, ופסיקה מפרשת זאת כמקרים של מורכבות משפטית או עובדתית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם התובע ביקש זאת במפורש בתחילת הדיון.', false, 'בחירה זו שגויה. בית המשפט רשאי להעביר את התיק מיוזמתו, גם אם המבקש לא ביקש זאת בתחילת הדיון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אלא אם כן התובע הגיש באותה שנה יותר מחמש תביעות באותו בית משפט.', false, 'בחירה זו שגויה. זהו אחד התנאים להעברת דיון לפי סעיף 60(ב), אך לא התנאי היחיד, וקיימת גם עילת ''אי התאמה'' בשל מורכבות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הסכם השיפוט בין הצדדים גובר, ולכן הסמכות המקומית היא לבית המשפט בתל אביב.', false, 'בחירה זו שגויה. בתביעות קטנות, הסכם שיפוט בין הצדדים אינו בעל תוקף לעניין קביעת הסמכות המקומית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הסמכות המקומית נקבעת לפי מקום מגוריו או מקום עסקו של הנתבע, וזאת על אף האמור בכל הסכם בין בעלי הדין.', true, 'בחירה זו נכונה. תקנה 2(א) לתקנות שיפוט בתביעות קטנות קובעת כללים קוגנטיים לסמכות מקומית, המבטלים הסכמים בין הצדדים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הסמכות המקומית היא לבית המשפט בחדרה, שכן התובע רשאי לבחור את מקום הגשת התביעה.', false, 'בחירה זו שגויה. אף שלתובע יש אפשרויות בחירה, הן מוגבלות לכללים הקבועים בתקנה 2, ואינן כוללות בחירה שרירותית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט בחדרה רשאי להעביר את הדיון לבית המשפט בתל אביב, אם סבר שזה מועיל להכרעה צודקת ומהירה.', false, 'בחירה זו שגויה. אף שקיימת סמכות העברה, היא אינה נובעת מהסכם שיפוט, אלא משיקולים אחרים של אי-התאמה או ריבוי תביעות.', 4);

END $$;
